INSERT INTO agent_runs VALUES('agent_run_1a013558-0229-4ccf-86f2-00795e6abdd6','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "requestedGoal": "\ubc15\uc218\ubbfc\uc740 \uc0c1\ud669 \uadf8\ub9bc\uc744 \uba3c\uc800 \ubcf4\uba74 \uc9c0\uae08 \ud574\uc57c \ud560 \uc77c\uc744 \uc798 \ud30c\uc545\ud569\ub2c8\ub2e4.\n\uc13c\ud130\uc5d0 \uac00\uae30 \uc704\ud574 \ubc84\uc2a4\ub97c \ud0c0\ub294 \uc0dd\ud65c \uc7a5\uba74\uc744 \ubc14\ud0d5\uc73c\ub85c, \uc21c\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \uc5f0\uc2b5\ud558\ub294 \uc218\uc5c5 \uc790\ub8cc\ub97c \ub9cc\ub4e4\uc5b4\uc8fc\uc138\uc694.\n\n1\ub2e8\uacc4\ub294 \ubc84\uc2a4 \uc815\ub958\uc7a5 \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc9c0\uae08 \uc788\ub294 \uc7a5\uc18c\ub97c \uace0\ub974\ub294 \ud65c\ub3d9,\n2\ub2e8\uacc4\ub294 \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \uce74\ub4dc\ub85c \uace0\ub974\ub294 \ud65c\ub3d9,\n3\ub2e8\uacc4\ub294 \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \ud560 \ub9d0\uc744 2\uac1c \uc120\ud0dd\uc9c0 \uc911 \uace0\ub974\ub294 \ud65c\ub3d9,\n4\ub2e8\uacc4\ub294 \ud559\uc0dd\uc774 \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uc5d0\uac8c \u201c\ub3c4\uc640\uc8fc\uc138\uc694\u201d, \u201c\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u201d\ucc98\ub7fc \uc9e7\uac8c \ub9d0\ud574\ubcf4\ub294 \uc2e4\uc2dc\uac04 \ubc1c\ud654 \uc5f0\uc2b5\uc774\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.\n\n\ubb38\uc7a5\uc740 \uc9e7\uace0 \uc2e4\uc81c \uc0dd\ud65c\uc5d0\uc11c \uc4f8 \uc218 \uc788\ub294 \ub9d0\ub85c \uc368\uc8fc\uc138\uc694.\n\uc120\ud0dd\uc9c0\ub294 2\uac1c\ub9cc \uc8fc\uc138\uc694.\n\uc2e4\ud328\ud588\uc744 \ub54c\ub294 \ub2e4\uc2dc \ub9d0\ud574\ubcfc \uc218 \uc788\ub3c4\ub85d \ubd80\ub2f4 \uc5c6\ub294 \ud53c\ub4dc\ubc31\uc744 \ub123\uc5b4\uc8fc\uc138\uc694.", "contentType": "learning_focus", "caseFile": {"profile": {"id": "student_learning_clock", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_clock", "displayName": "\uae40\uc9c0\uc6b0", "grade": "elementary_3", "schoolCode": "8811046", "studentType": "learning_focus", "primaryNeed": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "younger", "gradeNumber": "3", "className": "1", "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": null, "gradeLabel": "\ucd083", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uc0dd\uc131", "attendanceLabel": "\uae30\ub85d \uc804", "summaryLine": "\uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uae34 \uc124\uba85\ubcf4\ub2e4 \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\ub85c \uc2dc\uce68\uacfc \ubd84\uce68\uc744 \uad6c\ubd84\ud558\uace0 \uc77d\ub294 \uc21c\uc11c\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2dc\uac01 \ub2e8\uc11c \uae30\ubc18 2\uc9c0\uc120\ub2e4 \uc218\uc5c5", "supportStrategyDetail": "\ud55c \ubb38\uc7a5 \uc9c0\uc2dc, \ud070 \uadf8\ub9bc \ub2e8\uc11c, 2\uac1c \uc120\ud0dd\uc9c0\ub97c \uc0ac\uc6a9\ud574 \uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c\ub97c \uc548\uc815\ud654\ud558\ub294 \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc73c\uba74 \ubc14\ub85c \ubc18\uc751\ud574\uc694.", "\uc120\ud0dd\uc9c0\uac00 2\uac1c\uc77c \ub54c \ubd80\ub2f4\uc774 \uc904\uace0 \uc548\uc815\uc801\uc73c\ub85c \uace0\ub97c \uc218 \uc788\uc5b4\uc694.", "\ub9c8\uc2a4\ucf54\ud2b8\uac00 \uc9e7\uac8c \uc548\ub0b4\ud558\uba74 \uc2dc\uc120\uc744 \uc798 \ubaa8\uc544\uc694."], "weaknesses": ["\ubb38\uc7a5\uc774 \uae38\uc5b4\uc9c0\uba74 \ubb34\uc5c7\ubd80\ud130 \ud574\uc57c \ud560\uc9c0 \uba48\uce6b\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc2dc\uacc4\ub97c \uc77d\uc744 \ub54c \uc9e7\uc740 \ubc14\ub298\ubd80\ud130 \ubd10\uc57c \ud558\ub294 \uc21c\uc11c\uac00 \ud754\ub4e4\ub824\uc694.", "\ud2c0\ub9b0 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \uc870\uae08 \ud544\uc694\ud574\uc694."], "emotionalNote": "\ucc98\uc74c \ubb38\ud56d\uc5d0\uc11c \uc131\uacf5 \uacbd\ud5d8\uc744 \uc5bb\uc73c\uba74 \uc774\ud6c4 \ucc38\uc5ec\uac00 \uc548\uc815\ub429\ub2c8\ub2e4.", "responsePattern": "\uadf8\ub9bc\uc744 \uba3c\uc800 \ubcf4\uace0, \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub97c \ubc1b\uc744 \ub54c \ubc18\uc751\uc774 \uac00\uc7a5 \uc88b\uc2b5\ub2c8\ub2e4.", "guardianCooperation": "\ubcf4\ud638\uc790\ub294 \uac00\uc815\uc5d0\uc11c \uc9e7\uc740 \uc2dc\uacc4 \uc77d\uae30 \uc5f0\uc2b5\uc744 \ub3c4\uc6b8 \uc218 \uc788\uc73c\ub098, \uae34 \ud559\uc2b5\uc9c0\ub294 \ubd80\ub2f4\uc774 \ud07d\ub2c8\ub2e4.", "schoolContextNote": "NEIS \ud559\uad50 \uae30\ubcf8\uc815\ubcf4\uc640 \uc2dc\uac04\ud45c\ub97c \uc5f0\uacb0\ud574 \ud559\uad50 \uc218\uc5c5 \ud750\ub984\uacfc \ud68c\uae30 \ubaa9\ud45c\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.", "nextSessionFocus": ["\uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c \uc775\ud788\uae30", "2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc815\uac01 \uc2dc\uac04 \ud655\uc778\ud558\uae30", "\uccab \ubb38\ud56d\uc740 \uc26c\uc6b4 \uc131\uacf5 \uacbd\ud5d8\uc73c\ub85c \uc2dc\uc791"], "aiContextSummary": "\ucd083 \uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615 \ud559\uc0dd. \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694. \uae34 \ubb38\uc7a5 \uc124\uba85\ubcf4\ub2e