"case_learning_clock", "periodType": "next_session", "goalText": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc775\ud600\ubcf4\uba74 \uc88b\uaca0\uc5b4\uc694.", "checklistJson": {"checks": ["\uc9e7\uc740 \ubc14\ub298 \ucc3e\uae30", "2\uac1c \uc120\ud0dd\uc9c0\uc5d0\uc11c \uc2dc\uac04 \uace0\ub974\uae30"]}, "status": "planned"}], "publicContextSummary": {"schoolCode": "8811046", "schoolName": "\uc601\uc8fc\uc911\uc559\ucd08\ub4f1\ud559\uad50", "schoolKind": "\ucd08\ub4f1\ud559\uad50", "sources": ["curriculum_seed", "neis_open_api"]}}}','{"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "contentType": "learning_focus", "sessionGoal": "\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac08 \ub54c, \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9ac\uace0 \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0\uc744 \uc5f0\uc2b5\ud55c\ub2e4.", "targetSkill": "\uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0, \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubcf4\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uccab \ubb38\ud56d\uc5d0\uc11c\uc758 \uc131\uacf5 \uacbd\ud5d8\uc774 \uc774\ud6c4 \ucc38\uc5ec\uc640 \uc815\uc11c \uc548\uc815\uc5d0 \uc911\uc694\ud558\uba70, \uc77d\uae30 \ubd80\ud558\uac00 \ud06c\uc9c0 \uc54a\uc740 \uc9e7\uc740 \ubb38\uc7a5\uacfc 2\uc9c0\uc120\ub2e4 \uc120\ud0dd\uc774 \uad8c\uc7a5\ub41c\ub2e4."}, "selectedStrategy": ["success-first", "two-choice_reduction", "short_visual_explanation", "step-by-step_sequencing"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\uc694", "purpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5\uacfc \ubc84\uc2a4 \uc548 \uc7a5\uba74\uc744 \uadf8\ub9bc\uc73c\ub85c \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uba70, \uc624\ub298 \ud560 \uc77c\uc774 \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\uc640 \ub3c4\uc6c0 \ub9d0 \uc5f0\uc2b5\u2019\uc784\uc744 \uc9e7\uac8c \uc548\ub0b4\ud55c\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "scene_question", "studentTitle": "\uc9c0\uae08 \uc788\ub294 \uacf3\uc740 \uc5b4\ub514\uc77c\uae4c\uc694?", "purpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5 \uadf8\ub9bc\uc744 \ubcf4\uace0 \u2018\uc9c0\uae08 \uc788\ub294 \uc7a5\uc18c\u2019\ub97c 2\uac1c \ubcf4\uae30 \uc911\uc5d0\uc11c \uace0\ub974\uac8c \ud558\uc5ec, \ud559\uc0dd\uc774 \uc0c1\ud669 \ubc30\uacbd\uc744 \uc548\uc815\uc801\uc73c\ub85c \ud30c\uc545\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "sequence_ordering", "studentTitle": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c, \ubb34\uc5c7\uc744 \uba3c\uc800 \ud560\uae4c\uc694?", "purpose": "\ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uae30 \u2192 \ubc84\uc2a4\uc5d0 \ud0c0\uae30 \u2192 \uce74\ub4dc\ub098 \ub3c8 \ub0b4\uae30 \uc21c\uc11c\ub97c 2\uc7a5\uc529 \uc9dd\uc9c0\uc5b4 \uac04\ub2e8\ud788 \uc120\ud0dd\ud558\uac8c \ud558\uc5ec, \ubc84\uc2a4 \ud0c0\ub294 \uae30\ubcf8 \uc21c\uc11c\ub97c \uc9e7\uc740 \ubb38\uc7a5\uacfc \uadf8\ub9bc\uc73c\ub85c \uc5f0\uc2b5\ud55c\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \ub9d0\ud574 \ubd10\uc694", "purpose": "\ubc84\uc2a4\ub97c \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uc5d0\uac8c \u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019\uc640 \uac19\uc774 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0\uc744 \uc2e4\uc81c\ucc98\ub7fc \ub530\ub77c \ub9d0\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc13c\ud130\uc5d0 \uac00\uae30 \uc704\ud574 \ubc84\uc2a4\ub97c \ud0c0\ub7ec \uac00\ub294 \ud558\ub8e8\ub97c \ud55c\ub208\uc5d0 \ubcf4\uc5ec \uc8fc\uc5b4, \ud559\uc0dd\uc774 \uc624\ub298 \ud65c\ub3d9\uc774 \u2018\ubc84\uc2a4 \ud0c0\uace0 \uc774\ub3d9\ud558\uae30\u2019\uc640 \uad00\ub828\ub41c\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uac8c \ud55c\ub2e4.", "mustShow": ["\ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \uac00\ubc29\uc744 \uba54\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310 \uc55e\uc5d0 \uc11c \uc788\ub294 \ubaa8\uc2b5", "\ub4a4\ucabd \ub3c4\ub85c\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \ub178\uc120 \ubc84\uc2a4 \ud55c \ub300", "\ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0 \ub2e8\uc21c\ud55c \uadf8\ub9bc \uc544\uc774\ucf58(\ubc84\uc2a4 \ubaa8\uc591)\ub9cc \uc788\uace0 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\uae30", "\uba40\ub9ac \uc13c\ud130 \uac74\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \uac74\ubb3c\uc774 \uc791\uac8c \ubcf4\uc774\uc9c0\ub9cc \uc138\ubd80 \uae00\uc790\ub294 \uc0dd\ub7b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \ubc84\uc2a4 \ubc88\ud638 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \ubb38\uc790 \uc815\ubcf4", "\ubcf5\uc7a1\ud55c \uad11\uace0 \ubb38\uad6c\ub098 \uc548\ub0b4\ubb38 \ud14d\uc2a4\ud2b8"]}, {"assetRole": "stage_1", "scenePurpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uae30\ubcf8 \uc0c1\ud669\uc744 \ub610\ub837\ud558\uac8c \ubcf4\uc5ec \uc8fc\uc5b4, \uc774\ud6c4 \ub2e8\uacc4\uc758 \ud65c\ub3d9 \ubc30\uacbd\uc744 \uc774\ud574\uc2dc\ud0a4\ub294 \uc6a9\ub3c4.", "mustShow": ["\ubc84\uc2a4 \uc815\ub958\uc7a5 \uc758\uc790\uc640 \uc9c0\ubd95\uc774 \uc788\ub294 \uac04\ub2e8\ud55c \uc815\ub958\uc7a5 \uad6c\uc870", "\uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud07c\uc9c1\ud558\uac8c \ud45c\uc2dc", "\uc544\uc774 \uc606\uc5d0 \uce5c\uadfc\ud55c \ub3d9\ubb3c \ub9c8\uc2a4\ucf54\ud2b8(\uc608: \uc6c3\ub294 \ubcc4 \ubaa8\uc591 \uce90\ub9ad\ud130 \ub610\ub294 \uc791\uc740 \uac15\uc544\uc9c0)\uac00 \ud568\uaed8 \uc11c \uc788\uc74c", "\uba40\ub9ac\uc11c \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\ub294 \ubc84\uc2a4\uc758 \uc55e\ubaa8\uc2b5", "\ud558\ub298\uacfc \uae38\uc774 \ub2e8\uc21c\ud55c \uc0c9\uac10\uc73c\ub85c \ud45c\ud604\ub41c \uc548\uc804\ud55c \uac70\ub9ac \ud48d\uacbd"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc815\ub958\uc7a5 \uc774\ub984, \ub178\uc120\ud45c, \uc2dc\uac04\ud45c \ub4f1 \uc77d\uc5b4\uc57c \ud558\ub294 \uae00\uc790", "\uc0ac\uace0 \uc0c1\ud669\uc774\ub098 \uc704\ud5d8\ud55c \uc7a5\uba74"]}, {"assetRole": "stage_2", "scenePurpose": "\u2018\uc9c0\uae08 \uc788\ub294 \uc7a5\uc18c\u2019\ub97c \uace0\ub974\uac8c \ud560 \ub54c, \ubc84\uc2a4 \uc815\ub958\uc7a5\uacfc \ub2e4\ub978 \uc7a5\uc18c\uac00 \uadf8\ub9bc\ub9cc\uc73c\ub85c\ub3c4 \ud655\uc2e4\ud788 \uad6c\ubd84\ub418\ub3c4\ub85d \ub300\ube44\ub97c \uc8fc\ub294 \uc6a9\ub3c4.", "mustShow": ["\ud654\uba74 \uc67c\ucabd: \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc7a5\uba74(\uc815\ub958\uc7a5 \ud45c\uc9c0\ud310, \uc758\uc790, \ub3c4\ub85c, \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uc544\uc774\uc640 \ub9c8\uc2a4\ucf54\ud2b8)", "\ud654\uba74 \uc624\ub978\ucabd: \uc804\ud600 \ub2e4\ub978 \uc7a5\uc18c \uc608\uc2dc(\uc608: \uc9d1 \uac70\uc2e4\uc774\ub098 \uad50\uc2e4 \uc548, \ucc45\uc0c1\uacfc \uc758\uc790, \uc2e4\ub0b4 \ubc30\uacbd)", "\ub450 \uc7a5\uc18c \ubaa8\ub450 \uac19\uc740 \uc544\uc774\uc640 \uac19\uc740 \ub9c8\uc2a4\ucf54\ud2b8 \uce90\ub9ad\ud130\uac00 \uc788\uc9c0\ub9cc \ubc30\uacbd\uc774 \ud655\uc5f0\ud788 \ub2e4\ub984", "\uae00\uc790\ub294 \uc804\ud600 \uc5c6\uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \uc7a5\uc18c \ucc28\uc774\uac00 \ub4dc\ub7ec\ub098\ub3c4\ub85d \uad6c\uc131"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\u2018\uc815\ub958\uc7a5\u2019, \u2018\uc9d1\u2019 \ub4f1 \uc7a5\uc18c \uc774\ub984 \uae00\uc790", "\uc124\uba85 \uae00\uc774\ub098 \ub9d0\ud48d\uc120 \ud14d\uc2a4\ud2b8"]}, {"assetRole": "stage_3", "scenePurpose": "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uac8c, \uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30 \ud750\ub984\uc744 \uac01\uac01 \ub2e8\uc21c\ud55c \uc7a5\uba74\uc73c\ub85c \ub098\ub220 \ubcf4\uc5ec \uc8fc\ub294 \uc6a9\ub3c4.", "mustShow": ["\uc7a5\uba74 1: \uc544\uc774\uac00 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc14\ub974\uac8c \uc11c\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \ubaa8\uc2b5", "\uc7a5\uba74 2: \ubc84\uc2a4 \ubb38\uc774 \uc5f4\ub824 \uc788\uace0, \uc544\uc774\uac00 \uc190\uc7a1\uc774\ub97c \uc7a1\uace0 \ucc28\ubd84\ud788 \ubc84\uc2a4\uc5d0 \uc62c\ub77c\ud0c0\ub294 \ubaa8\uc2b5", "\uc7a5\uba74 3: \uc544\uc774\uac00 \uad50\ud1b5\uce74\ub4dc\ub098 \ub3d9\uc804\uc744 \uae30\uc0ac\ub2d8 \uc606 \ub2e8\ub9d0\uae30\uc5d0 \ub300\uac70\ub098 \uc694\uae08\ud568\uc5d0 \ub123\ub294 \ubaa8\uc2b5", "\uce5c\uc808\ud55c \ud45c\uc815\uc758 \ubc84\uc2a4 \uae30\uc0ac\ub2d8", "\uac01 \uc7a5\uba74\uc774 \uce74\ub4dc\ucc98\ub7fc \ubd84\ub9ac\ub418\uc5b4 \ubcf4\uc774\uc9c0\ub9cc \ubc88\ud638\ub098 \uae00\uc790 \uc5c6\uc774 \uadf8\ub9bc\ub9cc \uc788\uc74c"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc694\uae08 \uae08\uc561, \ubc84\uc2a4 \ubc88\ud638, \uc815\ub958\uc7a5 \uc774\ub984 \ub4f1 \uae00\uc790 \uc815\ubcf4", "\ubcf5\uc7a1\ud55c \uad70\uc911 \uc7a5\uba74\uc774\ub098 \ud63c\uc7a1\ud55c \uc0c1\ud669"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c, \ud559\uc0dd\uc774 \uae30\uc0ac\ub2d8\uc774\ub098 \ub9c8\uc2a4\ucf54\ud2b8\uc5d0\uac8c \ub9d0\uc744 \uac74\ub124\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc5b4 \uc2e4\uc81c \ub9d0\ud558\uae30 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc6a9\ub3c4.", "mustShow": ["\ubc84\uc2a4 \uc548 \uc88c\uc11d\uc5d0 \uc549\uc544 \ucc3d\ubc16\uc744 \ubcf4\ub294 \uc544\uc774", "\uc544\uc774 \uc606 \uc88c\uc11d\uc5d0 \uc549\uc544 \uc788\ub294 \uce5c\uadfc\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce90\ub9ad\ud130(\ubcc4, \ub3d9\ubb3c \ub4f1)\uac00 \uc544\uc774 \ucabd\uc744 \ubc14\ub77c\ubcf4\uba70 \uadc0 \uae30\uc6b8\uc774\ub294 \ubaa8\uc2b5", "\uc55e\ucabd\uc5d0\ub294 \uc6b4\uc804\uc11d\uacfc \uc628\ud654\ud55c \ud45c\uc815\uc758 \ubc84\uc2a4 \uae30\uc0ac\ub2d8\uc774 \ubcf4\uc774\uc9c0\ub9cc \ub108\ubb34 \uba40\uc9c0 \uc54a\uac8c \ubb18\uc0ac", "\ucc3d \ubc16\uc73c\ub85c \uc9c0\ub098\uac00\ub294 \uac74\ubb3c\ub4e4(\uc13c\ud130 \uac19\uc740 \uac74\ubb3c\uc774 \uba40\ub9ac \uc788\uc9c0\ub9cc \uae00\uc790 \uc5c6\uc774 \ub2e8\uc21c\ud55c \ud615\ud0dc)", "\uc548\uc804\ubca8\ud2b8\ub098 \uc190\uc7a1\uc774 \ub4f1 \uc548\uc804\ud55c \ubc84\uc2a4 \ub0b4\ubd80 \ud45c\ud604"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ub9d0\ud48d\uc120 \uc548\uc5d0 \ub300\uc0ac\ub098 \uae00\uc790", "\uc0ac\uace0, \uae09\uc815\uac70 \ub4f1 \ubd88\uc548\ud55c \uc0c1\ud669"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298 \ud65c\ub3d9\uc774 \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uc0c1\ud669 \uc5f0\uc2b5\u2019\uc774\ub77c\ub294 \uac83\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc54c\ub824 \uc8fc\uace0, \ud559\uc0dd\uc758 \uae34\uc7a5\uc744 \ud480\uc5b4 \uc8fc\ub294 \ub3c4\uc785 \uc548\ub0b4.", "tone": "bright"}, {"assetRole": "stage_1", "voicePurpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5 \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc9c0\uae08 \uc0c1\ud669\uc744 \uc9e7\uac8c \uc124\uba85\ud558\uace0, \uc55e\uc73c\ub85c \ud560 \ud65c\ub3d9\uc774 \uc21c\uc11c\uc640 \ub3c4\uc6c0 \ub9d0 \uc5f0\uc2b5\uc774\ub77c\ub294 \uc810\uc744 \uac04\ub2e8\ud788 \uc608\uace0\ud55c\ub2e4.", "tone": "bright"}, {"assetRole": "stage_2", "voicePurpose": "\u2018\uc9c0\uae08 \uc788\ub294 \uacf3\uc774 \uc5b4\ub514\uc778\uc9c0\u2019 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc9c8\ubb38\ud558\uace0, \ub450 \uadf8\ub9bc \uc911\uc5d0\uc11c \uace0\ub974\uac8c \ud558\ub294 \uac04\ub2e8\ud55c \uc548\ub0b4\ub97c \uc81c\uacf5\ud55c\ub2e4.", "tone": "calm"}, {"assetRole": "stage_3", "voicePurpose": "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub098\ub204\uc5b4 \uc548\ub0b4\ud558\uace0, \ud559\uc0dd\uc774 \uc21c\uc11c\uc5d0 \ub9de\ub294 \uce74\ub4dc\ub97c \uace0\ub974\ub3c4\ub85d \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\ub97c \ub4e4\ub824\uc900\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc9e7\uc740 \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc744 \uc608\ub85c \ub4e4\uace0, \ud559\uc0dd\uc774 \uc9c1\uc811 \ub530\ub77c \ub9d0\ud574 \ubcf4\ub3c4\ub85d \ubd80\ub4dc\ub7fd\uac8c \uc774\ub048\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\ub2e8\uacc4 1~3\uc758 \ubaa8\ub4e0 \ubb38\uc7a5\uc774 \ud55c \ubb38\uc7a5 \ub610\ub294 \ub9e4\uc6b0 \uc9e7\uc740 \ub450 \ubb38\uc7a5 \uc774\ub0b4\ub85c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ubaa8\ub4e0 \uc120\ud0dd\uc9c0\ub294 2\uac1c\ub9cc \uc81c\uc2dc\ub418\ub3c4\ub85d \ud15c\ud50c\ub9bf \uc124\uc815\uacfc \ubb38\ud56d \uad6c\uc131\uc744 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694.", "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c(\uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30)\uac00 \uc2e4\uc81c \uc9c0\uc5ed \uad50\ud1b5 \uc0c1\ud669\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \uc5f0\uc2b5 \ubb38\uc7a5(\u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019 \ub4f1)\uc774 \ud559\uc0dd\uc5d0\uac8c \uc2e4\uc81c\ub85c \ud65c\uc6a9 \uac00\ub2a5\ud55c \ud45c\ud604\uc778\uc9c0, \ud559\uad50\u00b7\uac00\uc815\uacfc \ud611\uc758\ub41c \ud45c\ud604\uc778\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc624\ub2f5 \uc120\ud0dd \uc2dc \ud53c\ub4dc\ubc31 \ubb38\uc7a5\uc774 \uc9e7\uace0 \ubd80\ub2f4\uc774 \uc801\uc73c\uba70, \uc7ac\uc2dc\ub3c4 \uc758\uc695\uc744 \ub5a8\uc5b4\ub728\ub9ac\uc9c0 \uc54a\ub294\uc9c0 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694."], "safetyNotes": ["\ubc84\uc2a4 \uc7a5\uba74\uc5d0\uc11c \ub3c4\ub85c \uc548\uc804\uc744 \ud574\uce58\ub294 \ubaa8\uc2b5(\ubb34\ub2e8\ud6a1\ub2e8, \ub6f0\uc5b4\ub4e4\uae30 \ub4f1)\uc744 \ub123\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud569\ub2c8\ub2e4.", "\uc2e4\uc2dc\uac04 \ubc1c\ud654 \ub2e8\uacc4\uc5d0\uc11c \uac1c\uc778 \uc2e0\uc0c1\uc815\ubcf4(\uc9d1 \uc8fc\uc18c, \uc804\ud654\ubc88\ud638 \ub4f1)\ub97c \ub9d0\ud558\ub3c4\ub85d \uc720\ub3c4\ud558\ub294 \uc9c8\ubb38\uc740 \ud53c\ud574\uc57c \ud569\ub2c8\ub2e4.", "\u2018\uc798\ubabb \ud0c4 \ubc84\uc2a4\u2019 \uc0c1\ud669\uc744 \ub2e4\ub8f0 \ub54c, \uacf5\ud3ec\uac10\uc774\ub098 \uc704\ud5d8 \uc0c1\ud669\uc744 \uacfc\uc7a5\ud558\uc9c0 \ub9d0\uace0, \uce68\ucc29\ud558\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uae0d\uc815\uc801 \ub300\ucc98\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdb0 \uc8fc\uc138\uc694.", "\uc2e4\uc81c \ubc84\uc2a4 \uc774\uc6a9 \uaddc\uce59(\ub4b7\ubb38 \uc2b9\ud558\ucc28 \ub4f1)\uc774 \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c, \ud544\uc694 \uc2dc \uad50\uc0ac\uac00 \ud604\uc7a5 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc21c\uc11c \uc608\uc2dc\ub97c \uc218\uc815\ud560 \uc218 \uc788\uc74c\uc744 \uc5fc\ub450\uc5d0 \ub450\uc138\uc694."]}','gpt-5.1','succeeded','{"input_tokens": 10055, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 2604, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 12659}',NULL,NULL,0,'2026-05-03T01:10:27.745442+00:00','2026-05-03T01:10:49.793861+00:00');
INSERT INTO agent_runs VALUES('agent_run_7982e327-9d43-42a1-89c5-c565f75340d1','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "orchestratorRunId": "agent_run_1a013558-0229-4ccf-86f2-00795e6abdd6", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "contentType": "learning_focus", "sessionGoal": "\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac08 \ub54c, \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9ac\uace0 \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0\uc744 \uc5f0\uc2b5\ud55c\ub2e4.", "targetSkill": "\uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0, \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubcf4\uae30", "difficultyPolicy": {"level": "easy_success", "reason": "\uccab \ubb38\ud56d\uc5d0\uc11c\uc758 \uc131\uacf5 \uacbd\ud5d8\uc774 \uc774\ud6c4 \ucc38\uc5ec\uc640 \uc815\uc11c \uc548\uc815\uc5d0 \uc911\uc694\ud558\uba70, \uc77d\uae30 \ubd80\ud558\uac00 \ud06c\uc9c0 \uc54a\uc740 \uc9e7\uc740 \ubb38\uc7a5\uacfc 2\uc9c0\uc120\ub2e4 \uc120\ud0dd\uc774 \uad8c\uc7a5\ub41c\ub2e4."}, "selectedStrategy": ["success-first", "two-choice_reduction", "short_visual_explanation", "step-by-step_sequencing"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\uc694", "purpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5\uacfc \ubc84\uc2a4 \uc548 \uc7a5\uba74\uc744 \uadf8\ub9bc\uc73c\ub85c \uba3c\uc800 \ubcf4\uc5ec \uc8fc\uba70, \uc624\ub298 \ud560 \uc77c\uc774 \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\uc640 \ub3c4\uc6c0 \ub9d0 \uc5f0\uc2b5\u2019\uc784\uc744 \uc9e7\uac8c \uc548\ub0b4\ud55c\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "scene_question", "studentTitle": "\uc9c0\uae08 \uc788\ub294 \uacf3\uc740 \uc5b4\ub514\uc77c\uae4c\uc694?", "purpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5 \uadf8\ub9bc\uc744 \ubcf4\uace0 \u2018\uc9c0\uae08 \uc788\ub294 \uc7a5\uc18c\u2019\ub97c 2\uac1c \ubcf4\uae30 \uc911\uc5d0\uc11c \uace0\ub974\uac8c \ud558\uc5ec, \ud559\uc0dd\uc774 \uc0c1\ud669 \ubc30\uacbd\uc744 \uc548\uc815\uc801\uc73c\ub85c \ud30c\uc545\ud558\ub3c4\ub85d \ub3d5\ub294\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "sequence_ordering", "studentTitle": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c, \ubb34\uc5c7\uc744 \uba3c\uc800 \ud560\uae4c\uc694?", "purpose": "\ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uae30 \u2192 \ubc84\uc2a4\uc5d0 \ud0c0\uae30 \u2192 \uce74\ub4dc\ub098 \ub3c8 \ub0b4\uae30 \uc21c\uc11c\ub97c 2\uc7a5\uc529 \uc9dd\uc9c0\uc5b4 \uac04\ub2e8\ud788 \uc120\ud0dd\ud558\uac8c \ud558\uc5ec, \ubc84\uc2a4 \ud0c0\ub294 \uae30\ubcf8 \uc21c\uc11c\ub97c \uc9e7\uc740 \ubb38\uc7a5\uacfc \uadf8\ub9bc\uc73c\ub85c \uc5f0\uc2b5\ud55c\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \ub9d0\ud574 \ubd10\uc694", "purpose": "\ubc84\uc2a4\ub97c \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uc5d0\uac8c \u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019\uc640 \uac19\uc774 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0\uc744 \uc2e4\uc81c\ucc98\ub7fc \ub530\ub77c \ub9d0\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc13c\ud130\uc5d0 \uac00\uae30 \uc704\ud574 \ubc84\uc2a4\ub97c \ud0c0\ub7ec \uac00\ub294 \ud558\ub8e8\ub97c \ud55c\ub208\uc5d0 \ubcf4\uc5ec \uc8fc\uc5b4, \ud559\uc0dd\uc774 \uc624\ub298 \ud65c\ub3d9\uc774 \u2018\ubc84\uc2a4 \ud0c0\uace0 \uc774\ub3d9\ud558\uae30\u2019\uc640 \uad00\ub828\ub41c\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uac8c \ud55c\ub2e4.", "mustShow": ["\ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \uac00\ubc29\uc744 \uba54\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310 \uc55e\uc5d0 \uc11c \uc788\ub294 \ubaa8\uc2b5", "\ub4a4\ucabd \ub3c4\ub85c\uc5d0\uc11c \ub2e4\uac00\uc624\ub294 \ub178\uc120 \ubc84\uc2a4 \ud55c \ub300", "\ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0 \ub2e8\uc21c\ud55c \uadf8\ub9bc \uc544\uc774\ucf58(\ubc84\uc2a4 \ubaa8\uc591)\ub9cc \uc788\uace0 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\uae30", "\uba40\ub9ac \uc13c\ud130 \uac74\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \uac74\ubb3c\uc774 \uc791\uac8c \ubcf4\uc774\uc9c0\ub9cc \uc138\ubd80 \uae00\uc790\ub294 \uc0dd\ub7b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \ubc84\uc2a4 \ubc88\ud638 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \ubb38\uc790 \uc815\ubcf4", "\ubcf5\uc7a1\ud55c \uad11\uace0 \ubb38\uad6c\ub098 \uc548\ub0b4\ubb38 \ud14d\uc2a4\ud2b8"]}, {"assetRole": "stage_1", "scenePurpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uae30\ubcf8 \uc0c1\ud669\uc744 \ub610\ub837\ud558\uac8c \ubcf4\uc5ec \uc8fc\uc5b4, \uc774\ud6c4 \ub2e8\uacc4\uc758 \ud65c\ub3d9 \ubc30\uacbd\uc744 \uc774\ud574\uc2dc\ud0a4\ub294 \uc6a9\ub3c4.", "mustShow": ["\ubc84\uc2a4 \uc815\ub958\uc7a5 \uc758\uc790\uc640 \uc9c0\ubd95\uc774 \uc788\ub294 \uac04\ub2e8\ud55c \uc815\ub958\uc7a5 \uad6c\uc870", "\uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud07c\uc9c1\ud558\uac8c \ud45c\uc2dc", "\uc544\uc774 \uc606\uc5d0 \uce5c\uadfc\ud55c \ub3d9\ubb3c \ub9c8\uc2a4\ucf54\ud2b8(\uc608: \uc6c3\ub294 \ubcc4 \ubaa8\uc591 \uce90\ub9ad\ud130 \ub610\ub294 \uc791\uc740 \uac15\uc544\uc9c0)\uac00 \ud568\uaed8 \uc11c \uc788\uc74c", "\uba40\ub9ac\uc11c \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\ub294 \ubc84\uc2a4\uc758 \uc55e\ubaa8\uc2b5", "\ud558\ub298\uacfc \uae38\uc774 \ub2e8\uc21c\ud55c \uc0c9\uac10\uc73c\ub85c \ud45c\ud604\ub41c \uc548\uc804\ud55c \uac70\ub9ac \ud48d\uacbd"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc815\ub958\uc7a5 \uc774\ub984, \ub178\uc120\ud45c, \uc2dc\uac04\ud45c \ub4f1 \uc77d\uc5b4\uc57c \ud558\ub294 \uae00\uc790", "\uc0ac\uace0 \uc0c1\ud669\uc774\ub098 \uc704\ud5d8\ud55c \uc7a5\uba74"]}, {"assetRole": "stage_2", "scenePurpose": "\u2018\uc9c0\uae08 \uc788\ub294 \uc7a5\uc18c\u2019\ub97c \uace0\ub974\uac8c \ud560 \ub54c, \ubc84\uc2a4 \uc815\ub958\uc7a5\uacfc \ub2e4\ub978 \uc7a5\uc18c\uac00 \uadf8\ub9bc\ub9cc\uc73c\ub85c\ub3c4 \ud655\uc2e4\ud788 \uad6c\ubd84\ub418\ub3c4\ub85d \ub300\ube44\ub97c \uc8fc\ub294 \uc6a9\ub3c4.", "mustShow": ["\ud654\uba74 \uc67c\ucabd: \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc7a5\uba74(\uc815\ub958\uc7a5 \ud45c\uc9c0\ud310, \uc758\uc790, \ub3c4\ub85c, \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uc544\uc774\uc640 \ub9c8\uc2a4\ucf54\ud2b8)", "\ud654\uba74 \uc624\ub978\ucabd: \uc804\ud600 \ub2e4\ub978 \uc7a5\uc18c \uc608\uc2dc(\uc608: \uc9d1 \uac70\uc2e4\uc774\ub098 \uad50\uc2e4 \uc548, \ucc45\uc0c1\uacfc \uc758\uc790, \uc2e4\ub0b4 \ubc30\uacbd)", "\ub450 \uc7a5\uc18c \ubaa8\ub450 \uac19\uc740 \uc544\uc774\uc640 \uac19\uc740 \ub9c8\uc2a4\ucf54\ud2b8 \uce90\ub9ad\ud130\uac00 \uc788\uc9c0\ub9cc \ubc30\uacbd\uc774 \ud655\uc5f0\ud788 \ub2e4\ub984", "\uae00\uc790\ub294 \uc804\ud600 \uc5c6\uc774 \uadf8\ub9bc\ub9cc\uc73c\ub85c \uc7a5\uc18c \ucc28\uc774\uac00 \ub4dc\ub7ec\ub098\ub3c4\ub85d \uad6c\uc131"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\u2018\uc815\ub958\uc7a5\u2019, \u2018\uc9d1\u2019 \ub4f1 \uc7a5\uc18c \uc774\ub984 \uae00\uc790", "\uc124\uba85 \uae00\uc774\ub098 \ub9d0\ud48d\uc120 \ud14d\uc2a4\ud2b8"]}, {"assetRole": "stage_3", "scenePurpose": "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uac8c, \uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30 \ud750\ub984\uc744 \uac01\uac01 \ub2e8\uc21c\ud55c \uc7a5\uba74\uc73c\ub85c \ub098\ub220 \ubcf4\uc5ec \uc8fc\ub294 \uc6a9\ub3c4.", "mustShow": ["\uc7a5\uba74 1: \uc544\uc774\uac00 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc14\ub974\uac8c \uc11c\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \ubaa8\uc2b5", "\uc7a5\uba74 2: \ubc84\uc2a4 \ubb38\uc774 \uc5f4\ub824 \uc788\uace0, \uc544\uc774\uac00 \uc190\uc7a1\uc774\ub97c \uc7a1\uace0 \ucc28\ubd84\ud788 \ubc84\uc2a4\uc5d0 \uc62c\ub77c\ud0c0\ub294 \ubaa8\uc2b5", "\uc7a5\uba74 3: \uc544\uc774\uac00 \uad50\ud1b5\uce74\ub4dc\ub098 \ub3d9\uc804\uc744 \uae30\uc0ac\ub2d8 \uc606 \ub2e8\ub9d0\uae30\uc5d0 \ub300\uac70\ub098 \uc694\uae08\ud568\uc5d0 \ub123\ub294 \ubaa8\uc2b5", "\uce5c\uc808\ud55c \ud45c\uc815\uc758 \ubc84\uc2a4 \uae30\uc0ac\ub2d8", "\uac01 \uc7a5\uba74\uc774 \uce74\ub4dc\ucc98\ub7fc \ubd84\ub9ac\ub418\uc5b4 \ubcf4\uc774\uc9c0\ub9cc \ubc88\ud638\ub098 \uae00\uc790 \uc5c6\uc774 \uadf8\ub9bc\ub9cc \uc788\uc74c"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc694\uae08 \uae08\uc561, \ubc84\uc2a4 \ubc88\ud638, \uc815\ub958\uc7a5 \uc774\ub984 \ub4f1 \uae00\uc790 \uc815\ubcf4", "\ubcf5\uc7a1\ud55c \uad70\uc911 \uc7a5\uba74\uc774\ub098 \ud63c\uc7a1\ud55c \uc0c1\ud669"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c, \ud559\uc0dd\uc774 \uae30\uc0ac\ub2d8\uc774\ub098 \ub9c8\uc2a4\ucf54\ud2b8\uc5d0\uac8c \ub9d0\uc744 \uac74\ub124\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\uc5b4 \uc2e4\uc81c \ub9d0\ud558\uae30 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc6a9\ub3c4.", "mustShow": ["\ubc84\uc2a4 \uc548 \uc88c\uc11d\uc5d0 \uc549\uc544 \ucc3d\ubc16\uc744 \ubcf4\ub294 \uc544\uc774", "\uc544\uc774 \uc606 \uc88c\uc11d\uc5d0 \uc549\uc544 \uc788\ub294 \uce5c\uadfc\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce90\ub9ad\ud130(\ubcc4, \ub3d9\ubb3c \ub4f1)\uac00 \uc544\uc774 \ucabd\uc744 \ubc14\ub77c\ubcf4\uba70 \uadc0 \uae30\uc6b8\uc774\ub294 \ubaa8\uc2b5", "\uc55e\ucabd\uc5d0\ub294 \uc6b4\uc804\uc11d\uacfc \uc628\ud654\ud55c \ud45c\uc815\uc758 \ubc84\uc2a4 \uae30\uc0ac\ub2d8\uc774 \ubcf4\uc774\uc9c0\ub9cc \ub108\ubb34 \uba40\uc9c0 \uc54a\uac8c \ubb18\uc0ac", "\ucc3d \ubc16\uc73c\ub85c \uc9c0\ub098\uac00\ub294 \uac74\ubb3c\ub4e4(\uc13c\ud130 \uac19\uc740 \uac74\ubb3c\uc774 \uba40\ub9ac \uc788\uc9c0\ub9cc \uae00\uc790 \uc5c6\uc774 \ub2e8\uc21c\ud55c \ud615\ud0dc)", "\uc548\uc804\ubca8\ud2b8\ub098 \uc190\uc7a1\uc774 \ub4f1 \uc548\uc804\ud55c \ubc84\uc2a4 \ub0b4\ubd80 \ud45c\ud604"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ub9d0\ud48d\uc120 \uc548\uc5d0 \ub300\uc0ac\ub098 \uae00\uc790", "\uc0ac\uace0, \uae09\uc815\uac70 \ub4f1 \ubd88\uc548\ud55c \uc0c1\ud669"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298 \ud65c\ub3d9\uc774 \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uc0c1\ud669 \uc5f0\uc2b5\u2019\uc774\ub77c\ub294 \uac83\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc54c\ub824 \uc8fc\uace0, \ud559\uc0dd\uc758 \uae34\uc7a5\uc744 \ud480\uc5b4 \uc8fc\ub294 \ub3c4\uc785 \uc548\ub0b4.", "tone": "bright"}, {"assetRole": "stage_1", "voicePurpose": "\ubc84\uc2a4 \uc815\ub958\uc7a5 \uadf8\ub9bc\uc744 \ubcf4\uba70 \uc9c0\uae08 \uc0c1\ud669\uc744 \uc9e7\uac8c \uc124\uba85\ud558\uace0, \uc55e\uc73c\ub85c \ud560 \ud65c\ub3d9\uc774 \uc21c\uc11c\uc640 \ub3c4\uc6c0 \ub9d0 \uc5f0\uc2b5\uc774\ub77c\ub294 \uc810\uc744 \uac04\ub2e8\ud788 \uc608\uace0\ud55c\ub2e4.", "tone": "bright"}, {"assetRole": "stage_2", "voicePurpose": "\u2018\uc9c0\uae08 \uc788\ub294 \uacf3\uc774 \uc5b4\ub514\uc778\uc9c0\u2019 \ud55c \ubb38\uc7a5\uc73c\ub85c \uc9c8\ubb38\ud558\uace0, \ub450 \uadf8\ub9bc \uc911\uc5d0\uc11c \uace0\ub974\uac8c \ud558\ub294 \uac04\ub2e8\ud55c \uc548\ub0b4\ub97c \uc81c\uacf5\ud55c\ub2e4.", "tone": "calm"}, {"assetRole": "stage_3", "voicePurpose": "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub098\ub204\uc5b4 \uc548\ub0b4\ud558\uace0, \ud559\uc0dd\uc774 \uc21c\uc11c\uc5d0 \ub9de\ub294 \uce74\ub4dc\ub97c \uace0\ub974\ub3c4\ub85d \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\ub97c \ub4e4\ub824\uc900\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uc9e7\uc740 \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc744 \uc608\ub85c \ub4e4\uace0, \ud559\uc0dd\uc774 \uc9c1\uc811 \ub530\ub77c \ub9d0\ud574 \ubcf4\ub3c4\ub85d \ubd80\ub4dc\ub7fd\uac8c \uc774\ub048\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\ub2e8\uacc4 1~3\uc758 \ubaa8\ub4e0 \ubb38\uc7a5\uc774 \ud55c \ubb38\uc7a5 \ub610\ub294 \ub9e4\uc6b0 \uc9e7\uc740 \ub450 \ubb38\uc7a5 \uc774\ub0b4\ub85c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ubaa8\ub4e0 \uc120\ud0dd\uc9c0\ub294 2\uac1c\ub9cc \uc81c\uc2dc\ub418\ub3c4\ub85d \ud15c\ud50c\ub9bf \uc124\uc815\uacfc \ubb38\ud56d \uad6c\uc131\uc744 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694.", "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c(\uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30)\uac00 \uc2e4\uc81c \uc9c0\uc5ed \uad50\ud1b5 \uc0c1\ud669\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \uc5f0\uc2b5 \ubb38\uc7a5(\u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019 \ub4f1)\uc774 \ud559\uc0dd\uc5d0\uac8c \uc2e4\uc81c\ub85c \ud65c\uc6a9 \uac00\ub2a5\ud55c \ud45c\ud604\uc778\uc9c0, \ud559\uad50\u00b7\uac00\uc815\uacfc \ud611\uc758\ub41c \ud45c\ud604\uc778\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc624\ub2f5 \uc120\ud0dd \uc2dc \ud53c\ub4dc\ubc31 \ubb38\uc7a5\uc774 \uc9e7\uace0 \ubd80\ub2f4\uc774 \uc801\uc73c\uba70, \uc7ac\uc2dc\ub3c4 \uc758\uc695\uc744 \ub5a8\uc5b4\ub728\ub9ac\uc9c0 \uc54a\ub294\uc9c0 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694."], "safetyNotes": ["\ubc84\uc2a4 \uc7a5\uba74\uc5d0\uc11c \ub3c4\ub85c \uc548\uc804\uc744 \ud574\uce58\ub294 \ubaa8\uc2b5(\ubb34\ub2e8\ud6a1\ub2e8, \ub6f0\uc5b4\ub4e4\uae30 \ub4f1)\uc744 \ub123\uc9c0 \uc54a\ub3c4\ub85d \uc8fc\uc758\ud569\ub2c8\ub2e4.", "\uc2e4\uc2dc\uac04 \ubc1c\ud654 \ub2e8\uacc4\uc5d0\uc11c \uac1c\uc778 \uc2e0\uc0c1\uc815\ubcf4(\uc9d1 \uc8fc\uc18c, \uc804\ud654\ubc88\ud638 \ub4f1)\ub97c \ub9d0\ud558\ub3c4\ub85d \uc720\ub3c4\ud558\ub294 \uc9c8\ubb38\uc740 \ud53c\ud574\uc57c \ud569\ub2c8\ub2e4.", "\u2018\uc798\ubabb \ud0c4 \ubc84\uc2a4\u2019 \uc0c1\ud669\uc744 \ub2e4\ub8f0 \ub54c, \uacf5\ud3ec\uac10\uc774\ub098 \uc704\ud5d8 \uc0c1\ud669\uc744 \uacfc\uc7a5\ud558\uc9c0 \ub9d0\uace0, \uce68\ucc29\ud558\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uae0d\uc815\uc801 \ub300\ucc98\uc5d0 \ucd08\uc810\uc744 \ub9de\ucdb0 \uc8fc\uc138\uc694.", "\uc2e4\uc81c \ubc84\uc2a4 \uc774\uc6a9 \uaddc\uce59(\ub4b7\ubb38 \uc2b9\ud558\ucc28 \ub4f1)\uc774 \uc9c0\uc5ed\uc5d0 \ub530\ub77c \ub2e4\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c, \ud544\uc694 \uc2dc \uad50\uc0ac\uac00 \ud604\uc7a5 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc21c\uc11c \uc608\uc2dc\ub97c \uc218\uc815\ud560 \uc218 \uc788\uc74c\uc744 \uc5fc\ub450\uc5d0 \ub450\uc138\uc694."]}, "caseFile": {"profile": {"id": "student_learning_clock", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_clock", "displayName": "\uae40\uc9c0\uc6b0", "grade": "elementary_3", "schoolCode": "8811046", "studentType": "learning_focus", "primaryNeed": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "younger", "gradeNumber": "3", "className": "1", "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": null, "gradeLabel": "\ucd083", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uc0dd\uc131", "attendanceLabel": "\uae30\ub85d \uc804", "summaryLine": "\uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uae34 \uc124\uba85\ubcf4\ub2e4 \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\ub85c \uc2dc\uce68\uacfc \ubd84\uce68\uc744 \uad6c\ubd84\ud558\uace0 \uc77d\ub294 \uc21c\uc11c\ub97c \uc775\ud788\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2dc\uac01 \ub2e8\uc11c \uae30\ubc18 2\uc9c0\uc120\ub2e4 \uc218\uc5c5", "supportStrategyDetail": "\ud55c \ubb38\uc7a5 \uc9c0\uc2dc, \ud070 \uadf8\ub9bc \ub2e8\uc11c, 2\uac1c \uc120\ud0dd\uc9c0\ub97c \uc0ac\uc6a9\ud574 \uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c\ub97c \uc548\uc815\ud654\ud558\ub294 \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \uba3c\uc800 \ucc3e\uc73c\uba74 \ubc14\ub85c \ubc18\uc751\ud574\uc694.", "\uc120\ud0dd\uc9c0\uac00 2\uac1c\uc77c \ub54c \ubd80\ub2f4\uc774 \uc904\uace0 \uc548\uc815\uc801\uc73c\ub85c \uace0\ub97c \uc218 \uc788\uc5b4\uc694.", "\ub9c8\uc2a4\ucf54\ud2b8\uac00 \uc9e7\uac8c \uc548\ub0b4\ud558\uba74 \uc2dc\uc120\uc744 \uc798 \ubaa8\uc544\uc694."], "weaknesses": ["\ubb38\uc7a5\uc774 \uae38\uc5b4\uc9c0\uba74 \ubb34\uc5c7\ubd80\ud130 \ud574\uc57c \ud560\uc9c0 \uba48\uce6b\ud560 \uc218 \uc788\uc5b4\uc694.", "\uc2dc\uacc4\ub97c \uc77d\uc744 \ub54c \uc9e7\uc740 \ubc14\ub298\ubd80\ud130 \ubd10\uc57c \ud558\ub294 \uc21c\uc11c\uac00 \ud754\ub4e4\ub824\uc694.", "\ud2c0\ub9b0 \ub4a4\uc5d0\ub294 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uae30\uae4c\uc9c0 \uc2dc\uac04\uc774 \uc870\uae08 \ud544\uc694\ud574\uc694."], "emotionalNote": "\ucc98\uc74c \ubb38\ud56d\uc5d0\uc11c \uc131\uacf5 \uacbd\ud5d8\uc744 \uc5bb\uc73c\uba74 \uc774\ud6c4 \ucc38\uc5ec\uac00 \uc548\uc815\ub429\ub2c8\ub2e4.", "responsePattern": "\uadf8\ub9bc\uc744 \uba3c\uc800 \ubcf4\uace0, \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub97c \ubc1b\uc744 \ub54c \ubc18\uc751\uc774 \uac00\uc7a5 \uc88b\uc2b5\ub2c8\ub2e4.", "guardianCooperation": "\ubcf4\ud638\uc790\ub294 \uac00\uc815\uc5d0\uc11c \uc9e7\uc740 \uc2dc\uacc4 \uc77d\uae30 \uc5f0\uc2b5\uc744 \ub3c4\uc6b8 \uc218 \uc788\uc73c\ub098, \uae34 \ud559\uc2b5\uc9c0\ub294 \ubd80\ub2f4\uc774 \ud07d\ub2c8\ub2e4.", "schoolContextNote": "NEIS \ud559\uad50 \uae30\ubcf8\uc815\ubcf4\uc640 \uc2dc\uac04\ud45c\ub97c \uc5f0\uacb0\ud574 \ud559\uad50 \uc218\uc5c5 \ud750\ub984\uacfc \ud68c\uae30 \ubaa9\ud45c\ub97c \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.", "nextSessionFocus": ["\uc2dc\uac04 \uc77d\uae30 \uc21c\uc11c \uc775\ud788\uae30", "2\uac1c \uc120\ud0dd\uc9c0\ub85c \uc815\uac01 \uc2dc\uac04 \ud655\uc778\ud558\uae30", "\uccab \ubb38\ud56d\uc740 \uc26c\uc6b4 \uc131\uacf5 \uacbd\ud5d8\uc73c\ub85c \uc2dc\uc791"], "aiContextSummary": "\ucd083 \uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615 \ud559\uc0dd. \uc2dc\uac04 \uc77d\uae30 \uae30\ucd08 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694. \uae34 \ubb38\uc7a5 \uc124\uba85\ubcf4\ub2e4 \uc9e7\uc740 \uc2dc\uac01 \ub2e8\uc11c\uc640 2\uac1c \uc120\ud0dd\uc9c0\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uc131\uacf5 \uacbd\ud5d8\ud615 \ucf58\ud150\uce20\ub85c \uc2dc\uc791\ud558\uba74 \uc88b\uaca0\uc5b4\uc694."}}, "status": "active", "gradeLabel": "\ucd083", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uc800\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "attendanceRate": null, "attendanceLabel": "\uae30\ub85d \uc804", "strengths": ["\uadf8\ub9bc\uc5d0\uc11c \uc911\uc694\ud55c \ub2e8\uc11c\ub97c \u