ind": "\ucd08\ub4f1\ud559\uad50", "sources": ["curriculum_seed", "neis_open_api"]}}}','{"id": "content_bus_to_center_001", "studentId": "student_learning_clock", "caseId": "case_learning_clock", "contentType": "learning_focus", "title": "\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\uc694", "sessionGoal": "\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac08 \ub54c, \uadf8\ub9bc\uc744 \ubcf4\uace0 \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9ac\uace0 \uc798\ubabb \ud0c4 \uac83 \uac19\uc744 \ub54c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0\uc744 \uc5f0\uc2b5\ud55c\ub2e4.", "status": "teacher_review", "totalSteps": 4, "briefJson": {"orchestratorPlanVersion": "orchestrator_plan_v1", "targetSkill": "\uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0, \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubcf4\uae30", "strategy": "\uc9e7\uc740 \uadf8\ub9bc \ub2e8\uc11c\uc640 2\uc9c0\uc120\ub2e4 \uc120\ud0dd, \uc21c\uc11c \ub9de\ucd94\uae30, \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud574 \ubcf4\ub294 \ub2e8\uacc4 \uc5f0\uc2b5", "teacherReviewFocus": ["\ub2e8\uacc4 1~3\uc758 \ubaa8\ub4e0 \ubb38\uc7a5\uc774 \ud55c \ubb38\uc7a5 \ub610\ub294 \ub9e4\uc6b0 \uc9e7\uc740 \ub450 \ubb38\uc7a5 \uc774\ub0b4\ub85c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ubaa8\ub4e0 \uc120\ud0dd\uc9c0\ub294 2\uac1c\ub9cc \uc81c\uc2dc\ub418\ub3c4\ub85d \ud15c\ud50c\ub9bf \uc124\uc815\uacfc \ubb38\ud56d \uad6c\uc131\uc744 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694.", "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c(\uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30)\uac00 \uc2e4\uc81c \uc9c0\uc5ed \uad50\ud1b5 \uc0c1\ud669\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \uc5f0\uc2b5 \ubb38\uc7a5(\u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019 \ub4f1)\uc774 \ud559\uc0dd\uc5d0\uac8c \uc2e4\uc81c\ub85c \ud65c\uc6a9 \uac00\ub2a5\ud55c \ud45c\ud604\uc778\uc9c0, \ud559\uad50\u00b7\uac00\uc815\uacfc \ud611\uc758\ub41c \ud45c\ud604\uc778\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc624\ub2f5 \uc120\ud0dd \uc2dc \ud53c\ub4dc\ubc31 \ubb38\uc7a5\uc774 \uc9e7\uace0 \ubd80\ub2f4\uc774 \uc801\uc73c\uba70, \uc7ac\uc2dc\ub3c4 \uc758\uc695\uc744 \ub5a8\uc5b4\ub728\ub9ac\uc9c0 \uc54a\ub294\uc9c0 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694."]}, "stages": [{"id": "stage_bus_to_center_001_1", "missionContentId": "content_bus_to_center_001", "step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\uc694", "studentInstruction": "\uadf8\ub9bc\uc744 \ubcf4\uba74\uc11c \uc624\ub298 \uc5b4\ub5a4 \uae38\ub85c \uac00\ub294\uc9c0 \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4.", "sortOrder": 1, "templateJson": {"imageAssetId": "asset_content_bus_to_center_001_stage_1", "audioAssetId": "asset_content_bus_to_center_001_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_1", "audioAssetId": "asset_content_bus_to_center_001_stage_1_audio"}, "storyText": "\uc9c0\uc6b0\uac00 \uc13c\ud130\uc5d0 \uac00\ub824\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uace0 \uc788\uc5b4\uc694.", "missionText": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uae38\uacfc \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \ud568\uaed8 \uc5f0\uc2b5\ud574 \ubd05\uc2dc\ub2e4."}, "realtimeSpec": null}, {"id": "stage_bus_to_center_001_2", "missionContentId": "content_bus_to_center_001", "step": 2, "stageRole": "basic_problem", "templateType": "scene_question", "studentTitle": "\uc9c0\uae08 \uc788\ub294 \uacf3\uc740 \uc5b4\ub514\uc77c\uae4c\uc694?", "studentInstruction": "\ub450 \uadf8\ub9bc\uc744 \ubcf4\uace0, \uc9c0\uae08 \uc9c0\uc6b0\uac00 \uc788\ub294 \uacf3\uc744 \uace8\ub77c \ubd05\uc2dc\ub2e4.", "sortOrder": 2, "templateJson": {"imageAssetId": "asset_content_bus_to_center_001_stage_2", "audioAssetId": "asset_content_bus_to_center_001_stage_2_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_2", "audioAssetId": "asset_content_bus_to_center_001_stage_2_audio"}, "question": "\uc9c0\uc6b0\uc640 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uacf3\uc740 \uc5b4\ub290 \ucabd \uadf8\ub9bc\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "\ubc84\uc2a4 \uc815\ub958\uc7a5"}, {"id": "b", "text": "\uc9d1 \uc548\uc774\ub098 \uad50\uc2e4"}], "answer": "a", "correctFeedback": "\ub9de\uc544\uc694. \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uace0 \uc788\uc5b4\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \ubcf4\uc544\uc694. \ubc84\uc2a4 \ud45c\uc9c0\ud310\uc774 \ubcf4\uc774\ub294 \uacf3\uc744 \uace8\ub77c \ubd05\uc2dc\ub2e4."}, "realtimeSpec": null}, {"id": "stage_bus_to_center_001_3", "missionContentId": "content_bus_to_center_001", "step": 3, "stageRole": "applied_problem", "templateType": "sequence_ordering", "studentTitle": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c, \ubb34\uc5c7\uc744 \uba3c\uc800 \ud560\uae4c\uc694?", "studentInstruction": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c \uba3c\uc800 \ud560 \uc77c\uacfc \uadf8\ub2e4\uc74c \ud560 \uc77c\uc744 \uc21c\uc11c\ub300\ub85c \uace8\ub77c \ubd05\uc2dc\ub2e4.", "sortOrder": 3, "templateJson": {"imageAssetId": "asset_content_bus_to_center_001_stage_3", "audioAssetId": "asset_content_bus_to_center_001_stage_3_audio", "question": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c \uc5b4\ub5a4 \uc77c\uc744 \uba3c\uc800 \ud558\uace0, \uadf8\ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc744 \ud558\uba74 \uc88b\uc744\uae4c\uc694?", "cards": [{"id": "wait", "text": "\uc815\ub958\uc7a5\uc5d0\uc11c \ubc14\ub974\uac8c \uc11c\uc11c \uae30\ub2e4\ub9ac\uae30"}, {"id": "ride", "text": "\ubc84\uc2a4 \ubb38\uc774 \uc5f4\ub9ac\uba74 \ucc28\ubd84\ud788 \ud0c0\uae30"}], "answerOrder": ["wait", "ride"], "correctFeedback": "\uc88b\uc544\uc694. \uba3c\uc800 \uc815\ub958\uc7a5\uc5d0\uc11c \uae30\ub2e4\ub9ac\uace0, \uadf8\ub2e4\uc74c\uc5d0 \ucc28\ubd84\ud788 \ubc84\uc2a4\ub97c \ud0c0\uba74 \ub3fc\uc694.", "wrongFeedback": "\uc815\ub958\uc7a5\uc5d0\uc11c \uba3c\uc800 \uae30\ub2e4\ub9ac\ub294 \uc7a5\uba74\uc774 \uc55e\uc5d0 \uc624\ub3c4\ub85d \ub2e4\uc2dc \uace8\ub77c \ubd05\uc2dc\ub2e4."}, "realtimeSpec": null}, {"id": "stage_bus_to_center_001_4", "missionContentId": "content_bus_to_center_001", "step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \ub9d0\ud574 \ubd10\uc694", "studentInstruction": "\ubc84\uc2a4 \uc548 \uadf8\ub9bc\uc744 \ubcf4\uba74\uc11c \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \uc9c1\uc811 \ud574 \ubd05\uc2dc\ub2e4.", "sortOrder": 4, "templateJson": {"imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "audioAssetId": "asset_content_bus_to_center_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "audioAssetId": "asset_content_bus_to_center_001_stage_4_realtime_audio"}}, "realtimeSpec": {"id": "rt_spec_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0 \uc5f0\uc2b5\ud558\uae30", "situationText": "\uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uac00\ub294 \uae38\uc5d0 \uc870\uae08 \ud5f7\uac08\ub824\uc11c, \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uaed8 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ubb3c\uc5b4\ubcf4\ub824\uace0 \ud574\uc694.", "aiRole": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uc9c0\uc6b0 \uacc1\uc5d0 \uc788\ub294 \uce5c\uc808\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce5c\uad6c", "openingLine": "\uc9c0\uc6b0\uc57c, \uae38\uc774 \uc870\uae08 \ud5f7\uac08\ub9ac\uba74 \uc5b4\ub5bb\uac8c \ub9d0\ud574 \ubcfc\uae4c?", "studentGoal": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ud5f7\uac08\ub9b4 \ub54c \"\ub3c4\uc640\uc8fc\uc138\uc694.\", \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\" \uac19\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud574 \ubcf4\uae30", "rubric": [{"id": "say_help", "label": "\ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\ub3c4\uc640\uc8fc\uc138\uc694.\")", "required": true}, {"id": "ask_where_get_off", "label": "\ub0b4\ub9ac\ub294 \uacf3\uc744 \ubb3c\uc5b4\ubcf4\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\")", "required": false}], "allowedFeedback": ["\uc88b\uc544\uc694. \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \uc798 \ud588\uc5b4\uc694.", "\uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0\ub3c4 \uc9e7\uac8c \ubb3c\uc5b4\ubcfc \uc218\ub3c4 \uc788\uc5b4\uc694.", "\ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub9d0\ud574\ub3c4 \uad1c\ucc2e\uc544\uc694. \ud55c \ubb38\uc7a5\ub9cc \ud574\ub3c4 \uc88b\uc544\uc694."], "forbidden": ["\uc9c4\ub2e8\uba85\uc774\ub098 \uac80\uc0ac \uacb0\uacfc\ub97c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uae30", "\uc9d1 \uc8fc\uc18c, \uc804\ud654\ubc88\ud638 \uac19\uc740 \uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\ub9d0\ud574 \ubcf4\ub2c8 \uad1c\ucc2e\uc558\uc5b4\uc694.", "\uc870\uae08 \uc5b4\ub835\uc9c0\ub9cc \ud574 \ubcfc \ub9cc \ud588\uc5b4\uc694.", "\ub098\uc911\uc5d0 \ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud574 \ubcf4\uace0 \uc2f6\uc5b4\uc694."]}}], "assets": [{"id": "asset_content_bus_to_center_001_hero", "missionContentId": "content_bus_to_center_001", "stageId": null, "assetRole": "hero", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ubc1d\uc740 \ub0ae, \ud55c\uad6d \ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \ucc45\uac00\ubc29\uc744 \uba54\uace0 \uae54\ub054\ud55c \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310 \uc55e\uc5d0 \uc11c \uc788\ub294 \uc7a5\uba74. \ub4a4\ucabd \ub3c4\ub85c\uc5d0\uc11c\ub294 \ub178\ub780\uc0c9\uacfc \ucd08\ub85d\uc0c9\uc774 \uc11e\uc778 \ub2e8\uc21c\ud55c \ub514\uc790\uc778\uc758 \ub178\uc120 \ubc84\uc2a4 \ud55c \ub300\uac00 \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\uace0 \uc788\ub2e4. \ubc84\uc2a4 \uc815\ub958\uc7a5 \ud45c\uc9c0\ud310\uc5d0\ub294 \uad75\uc740 \uc120\uc73c\ub85c \uadf8\ub9b0 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud06c\uac8c \uc788\uace0, \uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \ubc88\ud638 \ub4f1 \uae00\uc790\ub294 \uc804\ud600 \uc5c6\ub2e4. \uba40\ub9ac\uc5d0\ub294 \uad50\uc721\uc13c\ud130 \uac74\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \ub2e8\uc21c\ud55c \uac74\ubb3c\uc774 \uc791\uac8c \ubcf4\uc774\uc9c0\ub9cc \uac04\ud310 \uae00\uc528\ub294 \uc5c6\uc774 \ud615\ud0dc\ub9cc \ud45c\ud604\ub41c\ub2e4. \uc804\ubc18\uc801\uc778 \ubd84\uc704\uae30\ub294 \uc548\uc804\ud558\uace0 \ucc28\ubd84\ud558\uba70, \ud559\uc2b5 \ud65c\ub3d9\uc73c\ub85c \u2018\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \ud558\ub8e8\u2019\ub97c \ub5a0\uc62c\ub9ac\uae30 \uc88b\uc740, \uae68\ub057\ud55c \uc0c9\uac10\uc758 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c. \uc7a5\uba74 \uc548\uc5d0\ub294 \uc5b4\ub5a4 \ubb38\uc81c \ubb38\uc7a5\uc774\ub098 \uc815\ub2f5, \uc120\ud0dd\uc9c0, \ud78c\ud2b8 \uac19\uc740 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "hero", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_hero_audio", "missionContentId": "content_bus_to_center_001", "stageId": null, "assetRole": "hero", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \ubaa8\uc2b5\uc744 \ud568\uaed8 \uc5f0\uc2b5\ud574 \ubcfc \uac70\uc608\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_1", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_1", "assetRole": "stage_1", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ubc1d\uc740 \ub0ae, \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc758\uc790\uc640 \uac04\ub2e8\ud55c \uc9c0\ubd95\uc774 \uc788\ub294 \uc791\uc740 \uc815\ub958\uc7a5 \uc7a5\uba74. \uc815\ub958\uc7a5 \uc606\uc5d0\ub294 \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \ud06c\uac8c \uadf8\ub824\uc9c4 \ud45c\uc9c0\ud310\uc774 \uc788\uace0, \uae00\uc790\ub294 \uc804\ud600 \uc5c6\ub2e4. \ucd08\ub4f1\ud559\uc0dd \ub610\ub798 \uc544\uc774\uac00 \uac00\ubc29\uc744 \uba54\uace0 \uc815\ub958\uc7a5 \uc55e\uc5d0 \uac00\uc9c0\ub7f0\ud788 \uc11c \uc788\uc73c\uba70, \uc606\uc5d0\ub294 \uc6c3\ub294 \ud45c\uc815\uc758 \uc791\uc740 \uac15\uc544\uc9c0 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ud568\uaed8 \uc11c \uc788\ub2e4. \uba40\ub9ac \ub3c4\ub85c\uc5d0\uc11c \ubc84\uc2a4 \ud55c \ub300\uc758 \uc55e\ubaa8\uc2b5\uc774 \ucc9c\ucc9c\ud788 \ub2e4\uac00\uc624\uace0 \uc788\ub2e4. \ud558\ub298\uacfc \uae38\uc740 \ub2e8\uc21c\ud55c \uc0c9\uac10\uc73c\ub85c \ud45c\ud604\ub418\uace0, \uc804\uccb4 \ubd84\uc704\uae30\ub294 \uc548\uc804\ud558\uace0 \ucc28\ubd84\ud558\ub2e4. \uc815\ub958\uc7a5 \uc774\ub984\uc774\ub098 \uc2dc\uac04\ud45c, \uad11\uace0 \ubb38\uad6c \uac19\uc740 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4. \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8 \uac19\uc740 \ud14d\uc2a4\ud2b8\ub294 \uc804\ud600 \uc5c6\uc774 \uc7a5\uba74\ub9cc \ubcf4\uc774\ub3c4\ub85d \ud55c\ub2e4.", "visualRole": "stage_1", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_1_audio", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_1", "assetRole": "stage_1", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uadf8\ub9bc\uc744 \ubcf4\uba74\uc11c, \uc624\ub298 \ud568\uaed8 \uc5f0\uc2b5\ud560 \uc77c\uc744 \uc0b4\uc9dd \ub5a0\uc62c\ub824 \ubd05\uc2dc\ub2e4.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_2", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_2", "assetRole": "stage_2", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud654\uba74\uc774 \uc67c\ucabd\uacfc \uc624\ub978\ucabd \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub25c \uc77c\ub7ec\uc2a4\ud2b8. \uc67c\ucabd\uc5d0\ub294 \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc7a5\uba74: \ubc84\uc2a4 \uc544\uc774\ucf58\ub9cc \uadf8\ub824\uc9c4 \ud45c\uc9c0\ud310, \uc758\uc790, \ub3c4\ub85c, \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uba70 \uc11c \uc788\ub294 \ucd08\ub4f1\ud559\uc0dd \uc544\uc774\uc640 \uc791\uc740 \uac15\uc544\uc9c0 \ub9c8\uc2a4\ucf54\ud2b8. \uc624\ub978\ucabd\uc5d0\ub294 \uc9d1 \uac70\uc2e4\uc774\ub098 \uad50\uc2e4 \uac19\uc740 \uc2e4\ub0b4 \uc7a5\uba74: \ucc45\uc0c1\uacfc \uc758\uc790, \uc120\ubc18\uc774 \uc788\ub294 \uc2e4\ub0b4 \ubc30\uacbd \uc18d\uc5d0 \uac19\uc740 \uc544\uc774\uc640 \uac19\uc740 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ud568\uaed8 \uc788\ub2e4. \ub450 \uc7a5\uba74 \ubaa8\ub450 \uae00\uc790\ub294 \uc804\ud600 \uc5c6\uace0, \ubc30\uacbd \ubd84\uc704\uae30\uc640 \ubb3c\uac74\ub4e4\uc774 \ub2ec\ub77c\uc11c \u2018\ubc16\uc758 \ubc84\uc2a4 \uc815\ub958\uc7a5\u2019\uacfc \u2018\uc2e4\ub0b4\u2019\uac00 \ud655\uc2e4\ud788 \uad6c\ubd84\ub418\ub3c4\ub85d \ud45c\ud604\ud55c\ub2e4. \uc5b4\ub5a4 \ubb38\uc81c \ubb38\uc7a5\uc774\ub098 \uc120\ud0dd\uc9c0, \uc7a5\uc18c \uc774\ub984 \uae00\uc790, \ub9d0\ud48d\uc120 \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_2", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_2_audio", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_2", "assetRole": "stage_2", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ub450 \uadf8\ub9bc\uc744 \ubcf4\uace0, \uc9c0\uc6b0\uc640 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uacf3\uc774 \uc5b4\ub514\uc778\uc9c0 \uace8\ub77c \ubcf4\uc138\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_3", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_3", "assetRole": "stage_3", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\uac00\ub85c\ub85c \ub098\ub780\ud788 \ub193\uc778 \uc138 \uac1c\uc758 \uc791\uc740 \uce74\ub4dc\ud615 \uc7a5\uba74\uc774 \uc788\ub294 \uc77c\ub7ec\uc2a4\ud2b8. \uce74\ub4dc 1: \uc544\uc774\uac00 \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc14\ub974\uac8c \uc11c\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \ubaa8\uc2b5. \uce74\ub4dc 2: \ubc84\uc2a4 \ubb38\uc774 \uc5f4\ub824 \uc788\uace0, \uc544\uc774\uac00 \uc190\uc7a1\uc774\ub97c \uc7a1\uace0 \ucc28\ubd84\ud788 \ubc84\uc2a4\uc5d0 \uc62c\ub77c\ud0c0\ub294 \ubaa8\uc2b5. \uce74\ub4dc 3: \ubc84\uc2a4 \uc548\uc5d0\uc11c \uc544\uc774\uac00 \uad50\ud1b5\uce74\ub4dc\ub098 \ub3d9\uc804\uc744 \uae30\uc0ac\ub2d8 \uc606 \ub2e8\ub9d0\uae30\uc5d0 \ub300\uac70\ub098 \uc694\uae08\ud568\uc5d0 \ub123\ub294 \ubaa8\uc2b5. \ubc84\uc2a4 \uae30\uc0ac\ub2d8\uc740 \uce5c\uc808\ud55c \ud45c\uc815\uc774\ub2e4. \uac01 \uc7a5\uba74\uc740 \uce74\ub4dc\ucc98\ub7fc \ud14c\ub450\ub9ac\ub85c\ub9cc \ub098\ub258\uc5b4 \uc788\uace0, \ubc88\ud638\ub098 \uae00\uc790\ub294 \uc804\ud600 \uc5c6\ub2e4. \ubc84\uc2a4 \ubc88\ud638, \uc694\uae08 \uae08\uc561, \uc815\ub958\uc7a5 \uc774\ub984 \ub4f1 \ubaa8\ub4e0 \ubb38\uc790 \uc815\ubcf4\ub294 \uc81c\uc678\ud55c\ub2e4. \ubb38\uc81c \ubb38\uc7a5\uc774\ub098 \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8 \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_3", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_3_audio", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_3", "assetRole": "stage_3", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \ubaa8\uc2b5\uacfc \ud0c0\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74\uc11c, \uba3c\uc800 \ud560 \uc77c\uacfc \uadf8\ub2e4\uc74c \ud560 \uc77c\uc744 \ucc28\ub840\ub300\ub85c \uace8\ub77c \ubcf4\uc138\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_4_realtime", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "assetRole": "stage_4_realtime", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ubc84\uc2a4 \uc548 \ub0b4\ubd80\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub530\ub73b\ud55c \uc77c\ub7ec\uc2a4\ud2b8. \uc544\uc774\uac00 \ucc3d\uac00 \ucabd \uc88c\uc11d\uc5d0 \uc549\uc544 \ubc16\uc744 \ubc14\ub77c\ubcf4\uace0 \uc788\uace0, \uc606 \uc88c\uc11d\uc5d0\ub294 \uadc0\uc5ec\uc6b4 \uac15\uc544\uc9c0 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \uc544\uc774 \ucabd\uc744 \ubcf4\uba70 \uadc0 \uae30\uc6b8\uc774\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uc55e\ucabd\uc5d0\ub294 \uc6b4\uc804\uc11d\uacfc \uc628\ud654\ud55c \ud45c\uc815\uc758 \ubc84\uc2a4 \uae30\uc0ac\ub2d8\uc774 \ubcf4\uc774\uc9c0\ub9cc \ub108\ubb34 \uba40\uc9c0 \uc54a\uac8c \ud45c\ud604\ud55c\ub2e4. \ucc3d \ubc16\uc73c\ub85c\ub294 \uc5ec\ub7ec \uac74\ubb3c\uc774 \uc9c0\ub098\uac00\uace0, \uc13c\ud130 \uac74\ubb3c\ucc98\ub7fc \ubcf4\uc774\ub294 \ub2e8\uc21c\ud55c \ud615\ud0dc\uc758 \uac74\ubb3c\uc774 \uba40\ub9ac \uc788\uc9c0\ub9cc \uac04\ud310 \uae00\uc528\ub294 \uc5c6\ub2e4. \uc190\uc7a1\uc774\uc640 \uc548\uc804 \uc190\uc7a1\uc774 \ub4f1 \uc548\uc804\ud55c \ubc84\uc2a4 \ub0b4\ubd80\uac00 \ud45c\ud604\ub418\uc5b4 \uc788\uace0, \uae09\uc815\uac70\ub098 \uc0ac\uace0 \uac19\uc740 \ubd88\uc548\ud55c \uc7a5\uba74\uc740 \uc5c6\ub2e4. \ub9d0\ud48d\uc120\uc774\ub098 \ub300\uc0ac, \ubb38\uc81c \ud14d\uc2a4\ud2b8, \uc815\ub2f5, \uc120\ud0dd\uc9c0, \ud78c\ud2b8 \uac19\uc740 \uae00\uc790\ub294 \uc804\ud600 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_4_realtime", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_bus_to_center_001_stage_4_realtime_audio", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "assetRole": "stage_4_realtime", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ubc84\uc2a4 \uc548 \uadf8\ub9bc\uc744 \ubcf4\uba74\uc11c, \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \"\ub3c4\uc640\uc8fc\uc138\uc694.\", \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\"\ucc98\ub7fc \uc9e7\uac8c \ub9d0\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud568\uaed8 \ud574 \ubcfc\uac8c\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}], "teacherReviewSummary": "\ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uc7a5\uba74\uc744 \ubc14\ud0d5\uc73c\ub85c, \ubc84\uc2a4 \uc815\ub958\uc7a5 \uc704\uce58 \ud30c\uc545 \u2192 \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c(\uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30) \u2192 \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \ub9d0 \uc5f0\uc2b5\uae4c\uc9c0 \ud55c \ubb38\uc7a5 \uc9c0\uc2dc\uc640 2\uac1c \uc120\ud0dd\uc9c0 \uc911\uc2ec\uc73c\ub85c \uad6c\uc131\ud588\uc2b5\ub2c8\ub2e4."}','gpt-5.1','succeeded','{"input_tokens": 14485, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 4724, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 19209}',NULL,NULL,0,'2026-05-03T01:10:49.837146+00:00','2026-05-03T01:11:17.310870+00:00');
INSERT INTO agent_runs VALUES('agent_run_56679e19-a5e1-4bc2-a392-a5c66e4e79db','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "requestedGoal": "\ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ud560\uc778 \uac00\uaca9\uc744 \uc774\ud574\ud558\ub294 \uc218\uc5c5 \uc790\ub8cc\ub97c \ub9cc\ub4e4\uc5b4\uc8fc\uc138\uc694. \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \ud45c\uc2dc\ub97c \uadf8\ub9bc\uc73c\ub85c \uba3c\uc800 \ubcf4\uace0, \uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0 \ub2e8\uacc4 \uce74\ub4dc\ub85c \ud655\uc778\ud55c \ub4a4 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uac8c \ud574\uc8fc\uc138\uc694. \ubbfc\uc900\uc774\ub294 \uae34 \uc124\uba85\ubcf4\ub2e4 \uc808\ucc28\uac00 \ub098\ub258\uc5b4 \uc788\uc744 \ub54c \uc774\ud574\uac00 \uc88b\uc544\uc11c, \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019 \ud750\ub984\uc73c\ub85c \uad6c\uc131\ud574\uc8fc\uc138\uc694. \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc65c \uadf8 \uae08\uc561\uc744 \ub0b4\uc57c \ud558\ub294\uc9c0 \uc790\uae30 \ub9d0\ub85c \uc124\uba85\ud574\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ub123\uc5b4\uc8fc\uc138\uc694.", "contentType": "learning_focus", "caseFile": {"profile": {"id": "student_learning_fraction", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_fraction", "displayName": "\uc774\ubbfc\uc900", "grade": "middle_2", "schoolCode": "8811058", "studentType": "learning_focus", "primaryNeed": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "older", "gradeNumber": "2", "className": "1", "interests": ["\uc694\ub9ac", "\ud0d0\ud5d8"], "readingLoad": "low", "choiceCountLimit": 3, "dashboard": {"attendanceRate": 95, "gradeLabel": "\uc9112", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uace0\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uac80\ud1a0", "attendanceLabel": "95%", "summaryLine": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \uc808\ucc28\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\ubd84\uc218 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uc804\uccb4\uc640 \ubd80\ubd84\uc744 \uad6c\ubd84\ud558\uace0 \ubd84\ubaa8\u00b7\ubd84\uc790\uc758 \uc758\ubbf8\ub97c \uc21c\uc11c\ub300\ub85c \uc5f0\uacb0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2dc\uac01 \uc790\ub8cc + \ub2e8\uacc4 \uce74\ub4dc + \ub9d0\ub85c \uc815\ub9ac\ud558\uae30", "supportStrategyDetail": "\uc2dc\uac01 \uc790\ub8cc, \ub2e8\uacc4 \uce74\ub4dc, \ube48\uce78 \ud655\uc778, \ub9d0\ub85c \uc815\ub9ac\ud558\uae30\ub97c \uc0ac\uc6a9\ud574 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ubc18\ubcf5 \uc5f0\uacb0\ud558\ub294 \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uadf8\ub9bc\uc774\ub098 \uc870\uac01 \ubaa8\ub378\uc744 \ubcf4\uba74 \uc804\uccb4\uc640 \ubd80\ubd84\uc744 \ub354 \uc27d\uac8c \uc774\ud574\ud574\uc694.", "\uacfc\uc815\uc744 \uc791\uc740 \ub2e8\uacc4\ub85c \ub098\ub204\uba74 \ub05d\uae4c\uc9c0 \ub530\ub77c\uc62c \uc218 \uc788\uc5b4\uc694.", "\uc694\ub9ac\ub098 \ud0d0\ud5d8\ucc98\ub7fc \uad6c\uccb4\uc801\uc778 \uc18c\uc7ac\uac00 \uc788\uc73c\uba74 \ucc38\uc5ec\uac00 \uc88b\uc544\uc838\uc694."], "weaknesses": ["\ubd84\ubaa8\uc640 \ubd84\uc790\uac00 \uac01\uac01 \ubb34\uc5c7\uc744 \ub73b\ud558\ub294\uc9c0 \uc790\uc8fc \ubc14\uafd4 \uc0dd\uac01\ud574\uc694.", "\ubb38\uc81c \uc124\uba85\uc774 \uae38\uba74 \uc911\uc694\ud55c \uc870\uac74\uc744 \ub193\uce60 \uc218 \uc788\uc5b4\uc694.", "\uc751\uc6a9 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc804\uccb4\ub97c \uba3c\u