uc704\uce58 \uc7ac\ud655\uc778"]}, "status": "planned"}], "publicContextSummary": {"schoolCode": "8811058", "schoolName": "\uc601\uc8fc\uc911\ud559\uad50", "schoolKind": "\uc911\ud559\uad50", "sources": ["curriculum_seed", "neis_open_api"]}}}','{"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "contentType": "learning_focus", "sessionGoal": "\ud559\uad50 \ub9e4\uc810 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019\uc744 \ubd84\uc218\uc640 \ub2e8\uacc4 \uce74\ub4dc\ub85c \ucc28\ub840\ub300\ub85c \ud30c\uc545\ud574 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uace0, \uc65c \uadf8 \uae08\uc561\uc778\uc9c0 \uc9e7\uac8c \uc124\uba85\ud55c\ub2e4.", "targetSkill": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc815\ubcf4\ub97c \ubcf4\uace0 \uc804\uccb4 \uae08\uc561, \uc904\uc5b4\ub4dc\ub294 \uae08\uc561, \ub0a8\ub294 \uae08\uc561\uc744 \uc21c\uc11c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc124\uba85\ud558\uae30", "difficultyPolicy": {"level": "standard", "reason": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ud55c \ucc28\ub840 \uacbd\ud5d8\ud588\uace0, \uc774\ubc88\uc5d0\ub294 \uc0dd\ud65c \ub9e5\ub77d(\ub9e4\uc810)\uc5d0\uc11c \uc804\uccb4-\ud560\uc778-\ucd5c\uc885 \uac00\uaca9\uc744 \ub2e8\uacc4\uc801\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uc751\uc6a9 \uc5f0\uc2b5\uc774 \ud544\uc694\ud558\uc9c0\ub9cc, \uc77d\uae30 \ubd80\ub2f4\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubb38\uc7a5\uc740 \uc9e7\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["step-by-step sequencing", "short visual explanation", "teach-back"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\ud559\uad50 \ub9e4\uc810 \uc7a5\uba74 \uadf8\ub9bc\uc744 \ud1b5\ud574 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \uac00\uaca9\uc774 \ud568\uaed8 \uc801\ud78c \uc0c1\ud669\uc744 \uac04\ub2e8\ud788 \uc18c\uac1c\ud558\uace0, \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub77c\ub294 \ud750\ub984\uc744 \uba3c\uc800 \uc2dc\uac01\uc801\uc73c\ub85c \ubcf4\uc5ec\uc900\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "purpose": "\ud55c \uac00\uc9c0 \ub9e4\uc810 \ubb3c\uac74\uc758 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc5d0 \ud574\ub2f9\ud558\ub294 \uce74\ub4dc 3\uc7a5\uc744 \uc62c\ubc14\ub978 \uc21c\uc11c\ub85c \ubc30\uc5f4\ud558\uba70 \uc808\ucc28 \ud750\ub984\uc744 \uc775\ud78c\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "applied_question", "studentTitle": "\ubb38\uc81c 2", "purpose": "\uac19\uc740 \ub9e4\uc810 \uc0c1\ud669\uc5d0\uc11c \ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uacc4\uc0b0\ud55c \ub4a4, \ubcf4\uae30 \uc911\uc5d0\uc11c \ucd5c\uc885 \ub0b4\uc57c \ud558\ub294 \uac00\uaca9\uc744 \uc120\ud0dd\ud574 \ubcf8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\ub9e4\uc810 \ubb3c\uac74 \ud558\ub098\ub97c \uace8\ub77c \u2018\uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\uac00 \ud560\uc778\ub418\uc5b4\uc11c, \uadf8\ub798\uc11c \ub0b4\uac00 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0\u2019\ub97c \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc804\uccb4 \ubbf8\uc158\uc758 \ubd84\uc704\uae30\ub97c \uc7a1\uae30 \uc704\ud574 \ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ud559\uc0dd\uc774 \uac04\uc2dd\uc744 \uace0\ub974\uba70 \ud560\uc778 \uac00\uaca9\ud45c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\ud559\uad50 \ub9e4\uc810 \ub0b4\ubd80 \uc804\uacbd", "\uac00\uaca9\ud45c\uac00 \ubd99\uc740 \uac04\uc2dd\uc774\ub098 \uc74c\ub8cc \uba87 \uac00\uc9c0", "\uc77c\ubd80 \uac00\uaca9\ud45c\uc5d0 \ud560\uc778 \uc2a4\ud2f0\ucee4\ub098 \ud560\uc778 \ud45c\uc2dc(\uc608: \u2018\ud560\uc778\u2019 \uc544\uc774\ucf58, \uc791\uac8c \ud45c\uc2dc\ub41c \ube44\uc728 \uae30\ud638 \ub4f1)\ub9cc \uc2dc\uac01\uc801 \uc694\uc18c\ub85c \uc554\uc2dc", "\uc911\ud559\uc0dd \ub610\ub798 \ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uad81\uae08\ud574\ud558\ub294 \ubaa8\uc2b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uad6c\uccb4\uc801\uc778 \uc22b\uc790 \ubb38\uc81c\ub098 \uc218\uc2dd", "\uc815\ub2f5\uc744 \uc9c1\uc811 \ub4dc\ub7ec\ub0b4\ub294 \uac00\uaca9 \uc22b\uc790 \uc870\ud569"]}, {"assetRole": "stage_1", "scenePurpose": "\ud55c\ucabd \ubcbd\uba74\uc5d0 \uac00\uaca9\ud45c\uac00 \uc798 \ubcf4\uc774\uac8c \ubd99\uc5b4 \uc788\ub294 \ub9e4\uc810 \ucf54\ub108\ub97c \ud074\ub85c\uc988\uc5c5\ud574 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \ud45c\uc2dc\uac00 \ud568\uaed8 \ubcf4\uc774\ub294 \uc0c1\ud669\uc744 \uc18c\uac1c\ud55c\ub2e4.", "mustShow": ["\uac04\uc2dd 1~2\uac1c\uac00 \ub193\uc778 \uc9c4\uc5f4\ub300", "\uac01 \uac04\uc2dd \uc544\ub798\uc5d0 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \ud45c\uc2dc\uac00 \ud568\uaed8 \uc788\ub294 \uac00\uaca9\ud45c(\uc608: \uc717\uc904\uc740 \uae30\ubcf8 \uac00\uaca9, \uc606\uc5d0 \uc791\uc740 \ud560\uc778 \ubc30\uc9c0)", "\u2018\ud560\uc778\u2019 \uac19\uc740 \uc9e7\uc740 \ub2e8\uc5b4 \ub610\ub294 \ub2e8\uc21c \uc544\uc774\ucf58 \uc218\uc900\uc758 \uc2dc\uac01\uc801 \ud45c\uc2dc(\uad6c\uccb4 \ubb38\uc81c \ubb38\uc7a5\uc740 \uc544\ub2d8)", "\ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uac00\ub9ac\ud0a4\uba70 \uc0b4\ud3b4\ubcf4\ub294 \ubaa8\uc2b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ud560\uc778\uac00 \uacc4\uc0b0\uc774 \ub05d\ub09c \ucd5c\uc885 \uac00\uaca9\uc744 \uac15\uc870\ud558\ub294 \uc5f0\ucd9c", "\ubcf5\uc7a1\ud55c \uc218\uc2dd\uc774\ub098 \uc5ec\ub7ec \uc904 \uc124\uba85"]}, {"assetRole": "stage_2", "scenePurpose": "\ud55c \ubb3c\uac74\uc5d0 \ub300\ud574 \u2018\uc6d0\ub798 \uac00\uaca9\u2019, \u2018\ud560\uc778 \uae08\uc561\u2019, \u2018\ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc744 \uac01\uac01 \uce74\ub4dc\ucc98\ub7fc \ub098\ub204\uc5b4 \ubcf4\uc5ec \uc8fc\ub294 \ub290\ub08c\uc744 \uc2dc\uac01\uc801\uc73c\ub85c \ub2f4\ub294\ub2e4.", "mustShow": ["\uac04\uc2dd \ud558\ub098\ub97c \uc911\uc2ec\uc5d0 \ubc30\uce58", "\uadf8 \uc8fc\ubcc0\uc5d0 \uc138 \uc7a5\uc758 \ube48 \uce74\ub4dc \ub610\ub294 \ub9d0\ud48d\uc120 \uc601\uc5ed(\uc21c\uc11c\ub300\ub85c \ubc30\uc5f4\ud560 \uc694\uc18c\ub77c\ub294 \ub290\ub08c\ub9cc)", "\uac01 \uce74\ub4dc\uc5d0\ub294 \uac04\ub2e8\ud55c \uc544\uc774\ucf58(\uc804\uccb4 \uac00\uaca9, \ub0b4\ub824\uac00\ub294 \ud654\uc0b4\ud45c, \uc9c0\uac11\uc5d0\uc11c \ub098\uac00\ub294 \ub3c8 \uac19\uc740 \uc0c1\uc9d5)\ub9cc \ud45c\ud604", "\ubc30\uacbd\uc740 \ub9e4\uc810 \uce74\uc6b4\ud130 \uadfc\ucc98\ub85c \ub2e8\uc21c\ud558\uac8c"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uce74\ub4dc \uc704\uc5d0 \uc2e4\uc81c \uc22b\uc790\ub098 \ubd84\uc218 \uae30\ud638", "\uc815\ub2f5 \uc21c\uc11c\ub97c \uc554\uc2dc\ud558\ub294 \ubc88\ud638(1,2,3 \ub4f1)"]}, {"assetRole": "stage_3", "scenePurpose": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc2a4\ud2f0\ucee4\uac00 \ubd99\uc740 \uac04\uc2dd \uac00\uaca9\ud45c\ub97c \uac15\uc870\ud574, \u2018\uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0\u2019\uc640 \u2018\ucd5c\uc885 \uac00\uaca9\u2019\uc744 \uacc4\uc0b0\ud574\uc57c \ud558\ub294 \uc0c1\ud669\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\uac04\uc2dd\uc774\ub098 \uc74c\ub8cc \ud558\ub098\uc758 \uac00\uaca9\ud45c \ud074\ub85c\uc988\uc5c5", "\uac00\uaca9\ud45c \ud55c\ucabd\uc5d0 \ubd84\uc218 \ubaa8\uc591 \uc544\uc774\ucf58\uc774 \ub4e4\uc5b4\uac04 \ud560\uc778 \ubc30\uc9c0(\uc608: \uc6d0 \uc548\uc5d0 \uac04\ub2e8\ud55c \ubd84\uc218 \uae30\ud638 \ub290\ub08c\ub9cc, \uad6c\uccb4 \uc218\uce58\ub294 \ubd88\uba85\ud655\ud558\uac8c)", "\uacc4\uc0b0\uae30\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ud559\uc0dd \ub610\ub294 \uc190", "\ud560\uc778\uc744 \uace0\ubbfc\ud558\ub294 \ub4ef\ud55c \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc644\uc131\ub41c \ucd5c\uc885 \uac00\uaca9 \uc22b\uc790", "\ubd84\uc218 \uac12\uc774 \uc815\ud655\ud788 \uc77d\ud788\ub294 \uc120\uba85\ud55c \uc218\uc2dd"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ud559\uc0dd\uc774 \uce5c\uad6c\ub098 \uc120\uc0dd\ub2d8\uc5d0\uac8c \ub9e4\uc810\uc5d0\uc11c \uace0\ub978 \ubb3c\uac74\uc758 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\ub9e4\uc810 \uc55e \ud14c\uc774\ube14\uc774\ub098 \ubcf5\ub3c4 \uc758\uc790\uc5d0 \uc549\uc544 \uac04\uc2dd\uc744 \ub4e0 \ud559\uc0dd", "\ud559\uc0dd \uc55e\uc5d0 \uce5c\uad6c\ub098 \uc120\uc0dd\ub2d8 \ud55c \uba85\uc774 \uc549\uc544 \ub4e3\uace0 \uc788\ub294 \ubaa8\uc2b5", "\ucc45\uc0c1 \uc704\uc5d0 \uac04\ub2e8\ud55c \uac00\uaca9\ud45c \ub610\ub294 \uc601\uc218\uc99d \ud55c \uc7a5", "\uc11c\ub85c \ub300\ud654\ub97c \ub098\ub204\ub294 \ub4ef\ud55c \ud45c\uc815\uacfc \ubab8\uc9d3"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ub300\ud654 \ub9d0\ud48d\uc120 \uc548\uc758 \uad6c\uccb4 \uc22b\uc790\ub098 \uc815\ub2f5 \ubb38\uc7a5", "\ud559\uc2b5 \uc9c4\ub2e8\uacfc \uad00\ub828\ub41c \ub2e8\uc5b4"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ud560\uc778\ub41c \uac00\uaca9\uc744 \uc54c\uc544\ubcf4\ub294 \uc624\ub298\uc758 \ud65c\ub3d9\uc744 \uac04\ub2e8\ud788 \uc548\ub0b4\ud558\uba70 \ud765\ubbf8\ub97c \ub04c\uc5b4\uc900\ub2e4.", "tone": "bright"}, {"assetRole": "stage_1", "voicePurpose": "\ub9e4\uc810 \uc7a5\uba74\uacfc \uac00\uaca9\ud45c\ub97c \uc9e7\uac8c \uc124\uba85\ud558\uba74\uc11c, \uace7 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019 \uc21c\uc11c\ub85c \ubc30\uc6b8 \uac83\uc784\uc744 \uc608\uace0\ud55c\ub2e4.", "tone": "calm"}, {"assetRole": "stage_2", "voicePurpose": "\ud55c \ubb3c\uac74\uc744 \uc608\ub85c \ub4e4\uc5b4 \uc6d0\ub798 \uac00\uaca9, \ud560\uc778 \uae08\uc561, \ub0b4\uc57c \ud558\ub294 \ub3c8\uc744 \uac01\uac01 \uc5b4\ub5a4 \uce74\ub4dc\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uac04\ub2e8\ud788 \ub9d0\ud574 \uc8fc\uace0, \uce74\ub4dc\ub97c \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \ub193\uc544 \ubcf4\ub3c4\ub85d \uc548\ub0b4\ud55c\ub2e4.", "tone": "bright"}, {"assetRole": "stage_3", "voicePurpose": "\ubc29\uae08 \uc5f0\uc2b5\ud55c \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\uba74\uc11c, \ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc5bc\ub9c8\ub098 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uc0dd\uac01\ud55c \ub4a4 \ubcf4\uae30\uc5d0\uc11c \ub9de\ub294 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\ub3c4\ub85d \ub3d5\ub294\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ud559\uc0dd\uc774 \uc9c1\uc811 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \uadf8\ub798\uc11c \ub0bc \ub3c8\u2019\uc744 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub3c4\ub85d \ucc28\ubd84\ud788 \uc694\uccad\ud558\uace0, \ub9d0\uc774 \ub9c9\ud788\uba74 \uc21c\uc11c\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uac8c \uaca9\ub824\ud55c\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\ub9e4\uc810 \ud560\uc778 \uc0c1\ud669\uc774 \uc911\ud559\uc0dd \uc218\uc900\uc5d0 \uc801\uc808\ud558\uace0, \ubd84\uc218 \uac1c\ub150 \ubcf5\uc2b5\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uac01 \ub2e8\uacc4 \uc124\uba85 \ubb38\uc7a5\uc774 \uc9e7\uace0 \uba85\ub8cc\ud558\uac8c \uad6c\uc131\ub418\uc5b4 \uae34 \uae00\uc744 \uc77d\uae30 \uc5b4\ub824\uc6b4 \ud559\uc0dd\uc5d0\uac8c \uacfc\ubd80\ud558\uac00 \ub418\uc9c0 \uc54a\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\ub2e8\uacc4 \ud750\ub984\uc774 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub85c \ubd84\uba85\ud558\uac8c \ub4dc\ub7ec\ub098\ub294\uc9c0 \uac80\ud1a0\ud574\uc8fc\uc138\uc694.", "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778\uc5d0\uc11c \ubd84\ubaa8\u00b7\ubd84\uc790 \uc758\ubbf8\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud53c\ub4dc\ubc31 \ubb38\uad6c\uc640 \ubcf4\uae30 \uad6c\uc131\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \uc124\uba85 \ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd\uc774 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c8\ubb38\uc774 \uac1c\ubc29\uc801\uc774\ub418, \ubd80\ub2f4\uc2a4\ub7fd\uc9c0 \uc54a\uc740\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694."], "safetyNotes": ["\ub9e4\uc810 \uc7a5\uba74\uacfc \ud559\uc0dd \uce90\ub9ad\ud130\ub294 \ud2b9\uc815 \uc2e4\uc81c \ud559\uc0dd\uacfc \uad6c\ubd84\ub418\ub294 \uc77c\ubc18\uc801\uc778 \ubb18\uc0ac\ub85c \uc81c\uc791\ud569\ub2c8\ub2e4.", "\uc774\ubbf8\uc9c0 \uc18d \uac00\uaca9\uacfc \ubd84\uc218 \ud45c\ud604\uc740 \uc2e4\uc81c \ubb38\uc81c\uc758 \uc815\ub2f5\uc744 \uc9c1\uc811 \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\ub3c4\ub85d \ud750\ub9bf\ud558\uac70\ub098 \uc0c1\uc9d5\uc801\uc73c\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc5d0\uac8c \ud559\uc2b5 \uc5b4\ub824\uc6c0\uc774\ub098 \uc9c4\ub2e8\uacfc \uad00\ub828\ub41c \uc6a9\uc5b4\ub294 \ub9d0\ud558\uc9c0 \uc54a\uc73c\uba70, \ub2e8\uc21c\ud788 \u2018\uc5f0\uc2b5\u2019, \u2018\ud655\uc778\u2019 \uac19\uc740 \uc911\ub9bd\uc801 \ud45c\ud604\ub9cc \uc0ac\uc6a9\ud569\ub2c8\ub2e4.", "\uc2e4\uc2dc\uac04 \uc124\uba85 \ud65c\ub3d9\uc5d0\uc11c\ub294 \uae08\uc804\uc801 \uc2e4\uc218\ub098 \uc624\ub2f5\uc5d0 \ub300\ud574 \ube44\ub09c \ub610\ub294 \ub180\ub9bc\uc73c\ub85c \ub4e4\ub9b4 \uc218 \uc788\ub294 \ud45c\ud604\uc744 \ud53c\ud558\uace0, \ub2e4\uc2dc \uc2dc\ub3c4\ud558\ub3c4\ub85d \uaca9\ub824\ud558\ub294 \ubb38\uc7a5\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4."]}','gpt-5.1','succeeded','{"input_tokens": 11071, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 2411, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 13482}',NULL,NULL,0,'2026-05-04T02:10:20.182966+00:00','2026-05-04T02:10:36.583690+00:00');
INSERT INTO agent_runs VALUES('agent_run_8bf2b59a-2098-4719-81fb-4f6fa6066628','content','mission_content_package_v1','MissionContentPackageV1','{"teacherId": "user_teacher_demo", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "orchestratorRunId": "agent_run_56679e19-a5e1-4bc2-a392-a5c66e4e79db", "orchestratorPlan": {"planVersion": "orchestrator_plan_v1", "studentId": "student_learning_fraction", "caseId": "case_learning_fraction", "contentType": "learning_focus", "sessionGoal": "\ud559\uad50 \ub9e4\uc810 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019\uc744 \ubd84\uc218\uc640 \ub2e8\uacc4 \uce74\ub4dc\ub85c \ucc28\ub840\ub300\ub85c \ud30c\uc545\ud574 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uace0, \uc65c \uadf8 \uae08\uc561\uc778\uc9c0 \uc9e7\uac8c \uc124\uba85\ud55c\ub2e4.", "targetSkill": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc815\ubcf4\ub97c \ubcf4\uace0 \uc804\uccb4 \uae08\uc561, \uc904\uc5b4\ub4dc\ub294 \uae08\uc561, \ub0a8\ub294 \uae08\uc561\uc744 \uc21c\uc11c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc124\uba85\ud558\uae30", "difficultyPolicy": {"level": "standard", "reason": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ud55c \ucc28\ub840 \uacbd\ud5d8\ud588\uace0, \uc774\ubc88\uc5d0\ub294 \uc0dd\ud65c \ub9e5\ub77d(\ub9e4\uc810)\uc5d0\uc11c \uc804\uccb4-\ud560\uc778-\ucd5c\uc885 \uac00\uaca9\uc744 \ub2e8\uacc4\uc801\uc73c\ub85c \uc5f0\uacb0\ud558\ub294 \uc751\uc6a9 \uc5f0\uc2b5\uc774 \ud544\uc694\ud558\uc9c0\ub9cc, \uc77d\uae30 \ubd80\ub2f4\uc744 \uc904\uc774\uae30 \uc704\ud574 \ubb38\uc7a5\uc740 \uc9e7\uac8c \uc720\uc9c0\ud569\ub2c8\ub2e4."}, "selectedStrategy": ["step-by-step sequencing", "short visual explanation", "teach-back"], "stagePlan": [{"step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "purpose": "\ud559\uad50 \ub9e4\uc810 \uc7a5\uba74 \uadf8\ub9bc\uc744 \ud1b5\ud574 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \uac00\uaca9\uc774 \ud568\uaed8 \uc801\ud78c \uc0c1\ud669\uc744 \uac04\ub2e8\ud788 \uc18c\uac1c\ud558\uace0, \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub77c\ub294 \ud750\ub984\uc744 \uba3c\uc800 \uc2dc\uac01\uc801\uc73c\ub85c \ubcf4\uc5ec\uc900\ub2e4."}, {"step": 2, "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "purpose": "\ud55c \uac00\uc9c0 \ub9e4\uc810 \ubb3c\uac74\uc758 \uac00\uaca9\ud45c\ub97c \ubcf4\uace0 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc5d0 \ud574\ub2f9\ud558\ub294 \uce74\ub4dc 3\uc7a5\uc744 \uc62c\ubc14\ub978 \uc21c\uc11c\ub85c \ubc30\uc5f4\ud558\uba70 \uc808\ucc28 \ud750\ub984\uc744 \uc775\ud78c\ub2e4."}, {"step": 3, "stageRole": "applied_problem", "templateType": "applied_question", "studentTitle": "\ubb38\uc81c 2", "purpose": "\uac19\uc740 \ub9e4\uc810 \uc0c1\ud669\uc5d0\uc11c \ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uacc4\uc0b0\ud55c \ub4a4, \ubcf4\uae30 \uc911\uc5d0\uc11c \ucd5c\uc885 \ub0b4\uc57c \ud558\ub294 \uac00\uaca9\uc744 \uc120\ud0dd\ud574 \ubcf8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "purpose": "\ub9e4\uc810 \ubb3c\uac74 \ud558\ub098\ub97c \uace8\ub77c \u2018\uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\uac00 \ud560\uc778\ub418\uc5b4\uc11c, \uadf8\ub798\uc11c \ub0b4\uac00 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0\u2019\ub97c \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud55c\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\uc804\uccb4 \ubbf8\uc158\uc758 \ubd84\uc704\uae30\ub97c \uc7a1\uae30 \uc704\ud574 \ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ud559\uc0dd\uc774 \uac04\uc2dd\uc744 \uace0\ub974\uba70 \ud560\uc778 \uac00\uaca9\ud45c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\ud559\uad50 \ub9e4\uc810 \ub0b4\ubd80 \uc804\uacbd", "\uac00\uaca9\ud45c\uac00 \ubd99\uc740 \uac04\uc2dd\uc774\ub098 \uc74c\ub8cc \uba87 \uac00\uc9c0", "\uc77c\ubd80 \uac00\uaca9\ud45c\uc5d0 \ud560\uc778 \uc2a4\ud2f0\ucee4\ub098 \ud560\uc778 \ud45c\uc2dc(\uc608: \u2018\ud560\uc778\u2019 \uc544\uc774\ucf58, \uc791\uac8c \ud45c\uc2dc\ub41c \ube44\uc728 \uae30\ud638 \ub4f1)\ub9cc \uc2dc\uac01\uc801 \uc694\uc18c\ub85c \uc554\uc2dc", "\uc911\ud559\uc0dd \ub610\ub798 \ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uad81\uae08\ud574\ud558\ub294 \ubaa8\uc2b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uad6c\uccb4\uc801\uc778 \uc22b\uc790 \ubb38\uc81c\ub098 \uc218\uc2dd", "\uc815\ub2f5\uc744 \uc9c1\uc811 \ub4dc\ub7ec\ub0b4\ub294 \uac00\uaca9 \uc22b\uc790 \uc870\ud569"]}, {"assetRole": "stage_1", "scenePurpose": "\ud55c\ucabd \ubcbd\uba74\uc5d0 \uac00\uaca9\ud45c\uac00 \uc798 \ubcf4\uc774\uac8c \ubd99\uc5b4 \uc788\ub294 \ub9e4\uc810 \ucf54\ub108\ub97c \ud074\ub85c\uc988\uc5c5\ud574 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \ud45c\uc2dc\uac00 \ud568\uaed8 \ubcf4\uc774\ub294 \uc0c1\ud669\uc744 \uc18c\uac1c\ud55c\ub2e4.", "mustShow": ["\uac04\uc2dd 1~2\uac1c\uac00 \ub193\uc778 \uc9c4\uc5f4\ub300", "\uac01 \uac04\uc2dd \uc544\ub798\uc5d0 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \ud45c\uc2dc\uac00 \ud568\uaed8 \uc788\ub294 \uac00\uaca9\ud45c(\uc608: \uc717\uc904\uc740 \uae30\ubcf8 \uac00\uaca9, \uc606\uc5d0 \uc791\uc740 \ud560\uc778 \ubc30\uc9c0)", "\u2018\ud560\uc778\u2019 \uac19\uc740 \uc9e7\uc740 \ub2e8\uc5b4 \ub610\ub294 \ub2e8\uc21c \uc544\uc774\ucf58 \uc218\uc900\uc758 \uc2dc\uac01\uc801 \ud45c\uc2dc(\uad6c\uccb4 \ubb38\uc81c \ubb38\uc7a5\uc740 \uc544\ub2d8)", "\ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uac00\ub9ac\ud0a4\uba70 \uc0b4\ud3b4\ubcf4\ub294 \ubaa8\uc2b5"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ud560\uc778\uac00 \uacc4\uc0b0\uc774 \ub05d\ub09c \ucd5c\uc885 \uac00\uaca9\uc744 \uac15\uc870\ud558\ub294 \uc5f0\ucd9c", "\ubcf5\uc7a1\ud55c \uc218\uc2dd\uc774\ub098 \uc5ec\ub7ec \uc904 \uc124\uba85"]}, {"assetRole": "stage_2", "scenePurpose": "\ud55c \ubb3c\uac74\uc5d0 \ub300\ud574 \u2018\uc6d0\ub798 \uac00\uaca9\u2019, \u2018\ud560\uc778 \uae08\uc561\u2019, \u2018\ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc744 \uac01\uac01 \uce74\ub4dc\ucc98\ub7fc \ub098\ub204\uc5b4 \ubcf4\uc5ec \uc8fc\ub294 \ub290\ub08c\uc744 \uc2dc\uac01\uc801\uc73c\ub85c \ub2f4\ub294\ub2e4.", "mustShow": ["\uac04\uc2dd \ud558\ub098\ub97c \uc911\uc2ec\uc5d0 \ubc30\uce58", "\uadf8 \uc8fc\ubcc0\uc5d0 \uc138 \uc7a5\uc758 \ube48 \uce74\ub4dc \ub610\ub294 \ub9d0\ud48d\uc120 \uc601\uc5ed(\uc21c\uc11c\ub300\ub85c \ubc30\uc5f4\ud560 \uc694\uc18c\ub77c\ub294 \ub290\ub08c\ub9cc)", "\uac01 \uce74\ub4dc\uc5d0\ub294 \uac04\ub2e8\ud55c \uc544\uc774\ucf58(\uc804\uccb4 \uac00\uaca9, \ub0b4\ub824\uac00\ub294 \ud654\uc0b4\ud45c, \uc9c0\uac11\uc5d0\uc11c \ub098\uac00\ub294 \ub3c8 \uac19\uc740 \uc0c1\uc9d5)\ub9cc \ud45c\ud604", "\ubc30\uacbd\uc740 \ub9e4\uc810 \uce74\uc6b4\ud130 \uadfc\ucc98\ub85c \ub2e8\uc21c\ud558\uac8c"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uce74\ub4dc \uc704\uc5d0 \uc2e4\uc81c \uc22b\uc790\ub098 \ubd84\uc218 \uae30\ud638", "\uc815\ub2f5 \uc21c\uc11c\ub97c \uc554\uc2dc\ud558\ub294 \ubc88\ud638(1,2,3 \ub4f1)"]}, {"assetRole": "stage_3", "scenePurpose": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc2a4\ud2f0\ucee4\uac00 \ubd99\uc740 \uac04\uc2dd \uac00\uaca9\ud45c\ub97c \uac15\uc870\ud574, \u2018\uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0\u2019\uc640 \u2018\ucd5c\uc885 \uac00\uaca9\u2019\uc744 \uacc4\uc0b0\ud574\uc57c \ud558\ub294 \uc0c1\ud669\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\uac04\uc2dd\uc774\ub098 \uc74c\ub8cc \ud558\ub098\uc758 \uac00\uaca9\ud45c \ud074\ub85c\uc988\uc5c5", "\uac00\uaca9\ud45c \ud55c\ucabd\uc5d0 \ubd84\uc218 \ubaa8\uc591 \uc544\uc774\ucf58\uc774 \ub4e4\uc5b4\uac04 \ud560\uc778 \ubc30\uc9c0(\uc608: \uc6d0 \uc548\uc5d0 \uac04\ub2e8\ud55c \ubd84\uc218 \uae30\ud638 \ub290\ub08c\ub9cc, \uad6c\uccb4 \uc218\uce58\ub294 \ubd88\uba85\ud655\ud558\uac8c)", "\uacc4\uc0b0\uae30\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ud559\uc0dd \ub610\ub294 \uc190", "\ud560\uc778\uc744 \uace0\ubbfc\ud558\ub294 \ub4ef\ud55c \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\uc644\uc131\ub41c \ucd5c\uc885 \uac00\uaca9 \uc22b\uc790", "\ubd84\uc218 \uac12\uc774 \uc815\ud655\ud788 \uc77d\ud788\ub294 \uc120\uba85\ud55c \uc218\uc2dd"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ud559\uc0dd\uc774 \uce5c\uad6c\ub098 \uc120\uc0dd\ub2d8\uc5d0\uac8c \ub9e4\uc810\uc5d0\uc11c \uace0\ub978 \ubb3c\uac74\uc758 \uc6d0\ub798 \uac00\uaca9\uacfc \ud560\uc778 \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4.", "mustShow": ["\ub9e4\uc810 \uc55e \ud14c\uc774\ube14\uc774\ub098 \ubcf5\ub3c4 \uc758\uc790\uc5d0 \uc549\uc544 \uac04\uc2dd\uc744 \ub4e0 \ud559\uc0dd", "\ud559\uc0dd \uc55e\uc5d0 \uce5c\uad6c\ub098 \uc120\uc0dd\ub2d8 \ud55c \uba85\uc774 \uc549\uc544 \ub4e3\uace0 \uc788\ub294 \ubaa8\uc2b5", "\ucc45\uc0c1 \uc704\uc5d0 \uac04\ub2e8\ud55c \uac00\uaca9\ud45c \ub610\ub294 \uc601\uc218\uc99d \ud55c \uc7a5", "\uc11c\ub85c \ub300\ud654\ub97c \ub098\ub204\ub294 \ub4ef\ud55c \ud45c\uc815\uacfc \ubab8\uc9d3"], "mustNotShow": ["problem text", "choices", "answer", "hint", "\ub300\ud654 \ub9d0\ud48d\uc120 \uc548\uc758 \uad6c\uccb4 \uc22b\uc790\ub098 \uc815\ub2f5 \ubb38\uc7a5", "\ud559\uc2b5 \uc9c4\ub2e8\uacfc \uad00\ub828\ub41c \ub2e8\uc5b4"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ud560\uc778\ub41c \uac00\uaca9\uc744 \uc54c\uc544\ubcf4\ub294 \uc624\ub298\uc758 \ud65c\ub3d9\uc744 \uac04\ub2e8\ud788 \uc548\ub0b4\ud558\uba70 \ud765\ubbf8\ub97c \ub04c\uc5b4\uc900\ub2e4.", "tone": "bright"}, {"assetRole": "stage_1", "voicePurpose": "\ub9e4\uc810 \uc7a5\uba74\uacfc \uac00\uaca9\ud45c\ub97c \uc9e7\uac8c \uc124\uba85\ud558\uba74\uc11c, \uace7 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019 \uc21c\uc11c\ub85c \ubc30\uc6b8 \uac83\uc784\uc744 \uc608\uace0\ud55c\ub2e4.", "tone": "calm"}, {"assetRole": "stage_2", "voicePurpose": "\ud55c \ubb3c\uac74\uc744 \uc608\ub85c \ub4e4\uc5b4 \uc6d0\ub798 \uac00\uaca9, \ud560\uc778 \uae08\uc561, \ub0b4\uc57c \ud558\ub294 \ub3c8\uc744 \uac01\uac01 \uc5b4\ub5a4 \uce74\ub4dc\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uac04\ub2e8\ud788 \ub9d0\ud574 \uc8fc\uace0, \uce74\ub4dc\ub97c \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \ub193\uc544 \ubcf4\ub3c4\ub85d \uc548\ub0b4\ud55c\ub2e4.", "tone": "bright"}, {"assetRole": "stage_3", "voicePurpose": "\ubc29\uae08 \uc5f0\uc2b5\ud55c \uc21c\uc11c\ub97c \ub5a0\uc62c\ub9ac\uac8c \ud558\uba74\uc11c, \ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc5bc\ub9c8\ub098 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uc0dd\uac01\ud55c \ub4a4 \ubcf4\uae30\uc5d0\uc11c \ub9de\ub294 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\ub3c4\ub85d \ub3d5\ub294\ub2e4.", "tone": "calm"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ud559\uc0dd\uc774 \uc9c1\uc811 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \uadf8\ub798\uc11c \ub0bc \ub3c8\u2019\uc744 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc9e7\uac8c \uc124\uba85\ud574 \ubcf4\ub3c4\ub85d \ucc28\ubd84\ud788 \uc694\uccad\ud558\uace0, \ub9d0\uc774 \ub9c9\ud788\uba74 \uc21c\uc11c\ub97c \ub2e4\uc2dc \ub5a0\uc62c\ub9ac\uac8c \uaca9\ub824\ud55c\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["\ub9e4\uc810 \ud560\uc778 \uc0c1\ud669\uc774 \uc911\ud559\uc0dd \uc218\uc900\uc5d0 \uc801\uc808\ud558\uace0, \ubd84\uc218 \uac1c\ub150 \ubcf5\uc2b5\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uac01 \ub2e8\uacc4 \uc124\uba85 \ubb38\uc7a5\uc774 \uc9e7\uace0 \uba85\ub8cc\ud558\uac8c \uad6c\uc131\ub418\uc5b4 \uae34 \uae00\uc744 \uc77d\uae30 \uc5b4\ub824\uc6b4 \ud559\uc0dd\uc5d0\uac8c \uacfc\ubd80\ud558\uac00 \ub418\uc9c0 \uc54a\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\ub2e8\uacc4 \ud750\ub984\uc774 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub85c \ubd84\uba85\ud558\uac8c \ub4dc\ub7ec\ub098\ub294\uc9c0 \uac80\ud1a0\ud574\uc8fc\uc138\uc694.", "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778\uc5d0\uc11c \ubd84\ubaa8\u00b7\ubd84\uc790 \uc758\ubbf8\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud53c\ub4dc\ubc31 \ubb38\uad6c\uc640 \ubcf4\uae30 \uad6c\uc131\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \uc124\uba85 \ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd\uc774 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c8\ubb38\uc774 \uac1c\ubc29\uc801\uc774\ub418, \ubd80\ub2f4\uc2a4\ub7fd\uc9c0 \uc54a\uc740\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694."], "safetyNotes": ["\ub9e4\uc810 \uc7a5\uba74\uacfc \ud559\uc0dd \uce90\ub9ad\ud130\ub294 \ud2b9\uc815 \uc2e4\uc81c \ud559\uc0dd\uacfc \uad6c\ubd84\ub418\ub294 \uc77c\ubc18\uc801\uc778 \ubb18\uc0ac\ub85c \uc81c\uc791\ud569\ub2c8\ub2e4.", "\uc774\ubbf8\uc9c0 \uc18d \uac00\uaca9\uacfc \ubd84\uc218 \ud45c\ud604\uc740 \uc2e4\uc81c \ubb38\uc81c\uc758 \uc815\ub2f5\uc744 \uc9c1\uc811 \ub4dc\ub7ec\ub0b4\uc9c0 \uc54a\ub3c4\ub85d \ud750\ub9bf\ud558\uac70\ub098 \uc0c1\uc9d5\uc801\uc73c\ub85c \ud45c\ud604\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc5d0\uac8c \ud559\uc2b5 \uc5b4\ub824\uc6c0\uc774\ub098 \uc9c4\ub2e8\uacfc \uad00\ub828\ub41c \uc6a9\uc5b4\ub294 \ub9d0\ud558\uc9c0 \uc54a\uc73c\uba70, \ub2e8\uc21c\ud788 \u2018\uc5f0\uc2b5\u2019, \u2018\ud655\uc778\u2019 \uac19\uc740 \uc911\ub9bd\uc801 \ud45c\ud604\ub9cc \uc0ac\uc6a9\ud569\ub2c8\ub2e4.", "\uc2e4\uc2dc\uac04 \uc124\uba85 \ud65c\ub3d9\uc5d0\uc11c\ub294 \uae08\uc804\uc801 \uc2e4\uc218\ub098 \uc624\ub2f5\uc5d0 \ub300\ud574 \ube44\ub09c \ub610\ub294 \ub180\ub9bc\uc73c\ub85c \ub4e4\ub9b4 \uc218 \uc788\ub294 \ud45c\ud604\uc744 \ud53c\ud558\uace0, \ub2e4\uc2dc \uc2dc\ub3c4\ud558\ub3c4\ub85d \uaca9\ub824\ud558\ub294 \ubb38\uc7a5\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4."]}, "caseFile": {"profile": {"id": "student_learning_fraction", "organizationId": "org_yeongju_center", "externalKey": "demo_student_learning_fraction", "displayName": "\uc774\ubbfc\uc900", "grade": "middle_2", "schoolCode": "8811058", "studentType": "learning_focus", "primaryNeed": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \ub2e8\uacc4\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "older", "gradeNumber": "2", "className": "1", "interests": ["\uc694\ub9ac", "\ud0d0\ud5d8"], "readingLoad": "low", "choiceCountLimit": 3, "dashboard": {"attendanceRate": 95, "gradeLabel": "\uc9112", "studentTypeLabel": "\ud559\uc2b5\uc9c0\uc6d0\ud615", "trackLabel": "\uace0\uc5f0\ub839 \ud559\uc2b5\uc9c0\uc6d0\ud615", "statusLabel": "\uc790\ub8cc \uac80\ud1a0", "attendanceLabel": "95%", "summaryLine": "\ubd84\uc218\uc758 \uc804\uccb4-\ubd80\ubd84 \uad00\uacc4\ub97c \uc808\ucc28\uc801\uc73c\ub85c \uc775\ud788\ub294 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\ubd84\uc218 \uac1c\ub150 \ubcf4\uc644 \uc218\uc5c5", "primaryNeedDetail": "\uc804\uccb4\uc640 \ubd80\ubd84\uc744 \uad6c\ubd84\ud558\uace0 \ubd84\ubaa8\u00b7\ubd84\uc790\uc758 \uc758\ubbf8\ub97c \uc21c\uc11c\ub300\ub85c \uc5f0\uacb0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc2d