\ub85c \ud30c\uc545\ud574 \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uace0, \uc65c \uadf8 \uae08\uc561\uc778\uc9c0 \uc9e7\uac8c \uc124\uba85\ud55c\ub2e4.", "status": "teacher_review", "totalSteps": 4, "briefJson": {"orchestratorPlanVersion": "orchestrator_plan_v1", "targetSkill": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc815\ubcf4\ub97c \ubcf4\uace0 \uc804\uccb4 \uae08\uc561, \uc904\uc5b4\ub4dc\ub294 \uae08\uc561, \ub0a8\ub294 \uae08\uc561\uc744 \uc21c\uc11c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc124\uba85\ud558\uae30", "strategy": "\ub9e4\uc810 \uc7a5\uba74 \uadf8\ub9bc\uacfc \ub2e8\uacc4 \uce74\ub4dc\ub97c \ud65c\uc6a9\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \ud750\ub984\uc744 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \uc775\ud78c \ub4a4, \ubcf4\uae30\uc5d0\uc11c \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uace0 \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud558\uae30", "teacherReviewFocus": ["\ub9e4\uc810 \ud560\uc778 \uc0c1\ud669\uc774 \uc911\ud559\uc0dd \uc218\uc900\uc5d0 \uc801\uc808\ud558\uace0, \ubd84\uc218 \uac1c\ub150 \ubcf5\uc2b5\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uac01 \ub2e8\uacc4 \uc124\uba85 \ubb38\uc7a5\uc774 \uc9e7\uace0 \uba85\ub8cc\ud558\uac8c \uad6c\uc131\ub418\uc5b4 \uae34 \uae00\uc744 \uc77d\uae30 \uc5b4\ub824\uc6b4 \ud559\uc0dd\uc5d0\uac8c \uacfc\ubd80\ud558\uac00 \ub418\uc9c0 \uc54a\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\ub2e8\uacc4 \ud750\ub984\uc774 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub85c \ubd84\uba85\ud558\uac8c \ub4dc\ub7ec\ub098\ub294\uc9c0 \uac80\ud1a0\ud574\uc8fc\uc138\uc694.", "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778\uc5d0\uc11c \ubd84\ubaa8\u00b7\ubd84\uc790 \uc758\ubbf8\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud53c\ub4dc\ubc31 \ubb38\uad6c\uc640 \ubcf4\uae30 \uad6c\uc131\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \uc124\uba85 \ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd\uc774 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c8\ubb38\uc774 \uac1c\ubc29\uc801\uc774\ub418, \ubd80\ub2f4\uc2a4\ub7fd\uc9c0 \uc54a\uc740\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694."]}, "stages": [{"id": "stage_learning_fraction_store_discount_1", "missionContentId": "content_learning_fraction_store_discount", "step": 1, "stageRole": "concept_intro", "templateType": "concept_intro", "studentTitle": "\uac1c\ub150 \uc5f4\uae30", "studentInstruction": "\ud559\uad50 \ub9e4\uc810 \uadf8\ub9bc\uc744 \ubcf4\uba70 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \uc21c\uc11c\ub97c \uba3c\uc800 \uc0b4\ud3b4\ubd10\uc694.", "sortOrder": 1, "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio"}, "storyText": "\ud559\uad50 \ub9e4\uc810 \uc9c4\uc5f4\ub300\uc5d0 \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \ub193\uc5ec \uc788\uace0, \uac00\uaca9\ud45c \uc606\uc5d0 \ud560\uc778 \ud45c\uc2dc\uac00 \ubd99\uc5b4 \uc788\uc5b4\uc694. \ud55c \ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\uc5b4 \ubcf4\uba70 \uc5bc\ub9c8\ub098 \ub0b4\uc57c \ud560\uc9c0 \uc0dd\uac01\ud558\uace0 \uc788\uc5b4\uc694.", "missionText": "\uc774\uc81c \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0b4 \ub54c, \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \ucc28\ub840\ub300\ub85c \uc0b4\ud3b4\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcfc \uac70\uc608\uc694."}, "realtimeSpec": null}, {"id": "stage_learning_fraction_store_discount_2", "missionContentId": "content_learning_fraction_store_discount", "step": 2, "stageRole": "basic_problem", "templateType": "sequence_ordering", "studentTitle": "\ubb38\uc81c 1", "studentInstruction": "\ud55c \ubb3c\uac74\uc5d0 \ub300\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019\uc5d0 \ub9de\uac8c \uce74\ub4dc 3\uc7a5\uc744 \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \ub193\uc544 \ubcf4\uc138\uc694.", "sortOrder": 2, "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_2", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_2_audio", "question": "\ucf5c\ub77c \ud55c \ubcd1\uc744 \uc0b4 \ub54c, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uac00\uaca9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774 \uc88b\uc744\uae4c\uc694? \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \uce74\ub4dc 3\uc7a5\uc744 \ubc30\uc5f4\ud574 \ubcf4\uc138\uc694.", "cards": [{"id": "card_original", "text": "\uc6d0\ub798 \uac00\uaca9\uc744 \ubcf8\ub2e4."}, {"id": "card_discount", "text": "\ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc774 \uc5bc\ub9c8\uc778\uc9c0 \ubcf8\ub2e4."}, {"id": "card_pay", "text": "\ud560\uc778\ub41c \ub4a4\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud55c\ub2e4."}], "answerOrder": ["card_original", "card_discount", "card_pay"], "correctFeedback": "\uc798\ud588\uc5b4\uc694! \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub4a4, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\uba74 \ub3fc\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \uc0dd\uac01\ud574\ubcfc\uae4c\uc694? \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \uc5bc\ub9c8\ub098 \uae4e\uc774\ub294\uc9c0 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\ub294 \uc21c\uc11c\uac00 \ub418\ub3c4\ub85d \ubc14\uafd4\ubcf4\uc138\uc694."}, "realtimeSpec": null}, {"id": "stage_learning_fraction_store_discount_3", "missionContentId": "content_learning_fraction_store_discount", "step": 3, "stageRole": "applied_problem", "templateType": "applied_question", "studentTitle": "\ubb38\uc81c 2", "studentInstruction": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc5bc\ub9c8\ub098 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uacc4\uc0b0\ud55c \ub4a4, \ubcf4\uae30\uc5d0\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud560 \ub3c8\uc744 \uace8\ub77c\ubcf4\uc138\uc694.", "sortOrder": 3, "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_3", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_3_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_3", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_3_audio"}, "question": "\ub9e4\uc810\uc5d0\uc11c \uac00\uaca9\uc774 3,000\uc6d0\uc778 \uc0cc\ub4dc\uc704\uce58\uc5d0 \uc624\ub298\uc740 \uac00\uaca9\uc758 1/3\ub9cc\ud07c\uc744 \uae4e\uc544 \uc900\ub2e4\uace0 \ud574\uc694. \uc0cc\ub4dc\uc704\uce58\ub97c \uc0b4 \ub54c, \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc740 \uc5bc\ub9c8\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "1,000\uc6d0"}, {"id": "b", "text": "2,000\uc6d0"}, {"id": "c", "text": "3,000\uc6d0"}], "answer": "b", "correctFeedback": "\ub9de\uc544\uc694! 3,000\uc6d0\uc758 1/3\uc740 1,000\uc6d0\uc774 \uc904\uc5b4\ub4dc\ub294 \uac70\uc608\uc694. \uadf8\ub798\uc11c 3,000\uc6d0 \u2212 1,000\uc6d0 = 2,000\uc6d0\uc774 \ub418\uc5b4, 2,000\uc6d0\uc744 \ub0b4\uba74 \ub3fc\uc694.", "wrongFeedback": "\uc870\uae08 \ub354 \ucc28\uadfc\ucc28\uadfc \uc0dd\uac01\ud574\ubcfc\uae4c\uc694? \uba3c\uc800 3,000\uc6d0\uc758 1/3\uc774 \uc5bc\ub9c8\uc778\uc9c0 \uad6c\ud558\uace0, \uadf8\ub9cc\ud07c \uc904\uc778 \ub4a4\uc5d0 \ub0a8\ub294 \ub3c8\uc774 \uc5bc\ub9c8\uc778\uc9c0 \ub2e4\uc2dc \uacc4\uc0b0\ud574\ubcf4\uc138\uc694."}, "realtimeSpec": null}, {"id": "stage_learning_fraction_store_discount_4", "missionContentId": "content_learning_fraction_store_discount", "step": 4, "stageRole": "realtime_practice", "templateType": "realtime_teach_back", "studentTitle": "\uc124\uba85\ud574\ubcf4\uae30", "studentInstruction": "\ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74 \ud558\ub098\ub97c \uace8\ub790\ub2e4\uace0 \uc0dd\uac01\ud558\uace0, \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \uadf8\ub798\uc11c \ub0b4\uac00 \ub0bc \ub3c8\u2019\uc744 \uc21c\uc11c\ub300\ub85c \ub9d0\ub85c \uc124\uba85\ud574\ubcf4\uc138\uc694.", "sortOrder": 4, "templateJson": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime_audio"}}, "realtimeSpec": {"id": "rt_spec_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ub9e4\uc810 \ud560\uc778 \uac00\uaca9 \ucc28\uadfc\ucc28\uadfc \uc124\uba85\ud558\uae30", "situationText": "\uce5c\uad6c\uac00 \ub9e4\uc810\uc5d0\uc11c \uc0cc\ub4dc\uc704\uce58\uc640 \uc74c\ub8cc\ub97c \ubcf4\ub2e4\uac00, \ud560\uc778 \uac00\uaca9\uc774 \uc5b4\ub5bb\uac8c \uacc4\uc0b0\ub418\ub294\uc9c0 \uad81\uae08\ud574\ud558\uace0 \uc788\uc5b4\uc694. \uce5c\uad6c\uc5d0\uac8c \ud55c \ubb3c\uac74\uc744 \uc608\ub85c \ub4e4\uc5b4, \uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\ub97c \ud560\uc778\ud574 \uc918\uc11c, \uadf8\ub798\uc11c \ub9c8\uc9c0\ub9c9\uc5d0 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \uc21c\uc11c\ub300\ub85c \uc124\uba85\ud574 \uc8fc\uba74 \uc88b\uaca0\uc5b4\uc694.", "aiRole": "\ub9e4\uc810 \uc55e\uc5d0\uc11c \ud568\uaed8 \uc788\ub294 \uce5c\uad6c", "openingLine": "\ub098 \uc624\ub298 \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0ac\ub824\uace0 \ud558\ub294\ub370, \ud560\uc778 \uac00\uaca9\uc774 \ud5f7\uac08\ub824. \uc608\ub97c \ud558\ub098 \uace8\ub77c\uc11c, \uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\ub97c \uae4e\uc544\uc11c, \uadf8\ub798\uc11c \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \uc21c\uc11c\ub300\ub85c \uc54c\ub824\uc904\ub798?", "studentGoal": "\ud55c \ubb3c\uac74\uc744 \uc815\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561 \u2192 \uadf8\ub798\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc744 \uc790\uc2e0\uc758 \ub9d0\ub85c \uac04\ub2e8\ud55c \ud55c\ub450 \ubb38\uc7a5\uc73c\ub85c \uc124\uba85\ud574 \ubcf4\uae30", "rubric": [{"id": "mention_original_price", "label": "\uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\ub294\uc9c0 \ud55c \ubc88\uc774\ub77c\ub3c4 \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "mention_discount_fraction", "label": "\uc5bc\ub9c8\ub97c \ud560\uc778\ud558\ub294\uc9c0, \ubd84\uc218\ub098 \u2018\uc5bc\ub9c8\ub9cc\ud07c \uae4e\uc778\ub2e4\u2019\ub294 \ub9d0\uc744 \uc774\uc6a9\ud574 \uc124\uba85\ud558\ub824\uace0 \uc2dc\ub3c4\ud55c\ub2e4.", "required": false}, {"id": "mention_final_pay", "label": "\ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc744 \ub9d0\ub85c \uc815\ub9ac\ud574 \ubcf8\ub2e4.", "required": false}, {"id": "use_sequence_words", "label": "\u2018\uba3c\uc800, \uadf8\ub9ac\uace0, \uadf8\ub798\uc11c\u2019 \uac19\uc740 \ub9d0\ub85c \uc21c\uc11c\ub97c \ub098\ub204\uc5b4 \ub9d0\ud558\ub824\uace0 \ud55c\ub2e4.", "required": false}, {"id": "meaningful_attempt", "label": "\uc790\uc2e0\uc774 \uc774\ud574\ud55c \ub9cc\ud07c \ub05d\uae4c\uc9c0 \uc124\uba85\ud558\ub824\uace0 \ub178\ub825\ud55c\ub2e4.", "required": true}], "allowedFeedback": ["\uc9c0\uae08\uae4c\uc9c0 \uc124\uba85 \uc798 \ub4e4\uc5c8\uc5b4. \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \uc5b4\ub5bb\uac8c \ub9d0\ud560 \uc218 \uc788\ub294\uc9c0 \ud55c \ubc88\ub9cc \ub354 \uc9e7\uac8c \ub9d0\ud574\ubcfc\uae4c?", "\uad1c\ucc2e\uc544, \uc870\uae08 \ud5f7\uac08\ub824\ub3c4 \ub3fc. \uc774\ubc88\uc5d0\ub294 \u2018\uc5bc\ub9c8\ub97c \uae4e\uc544\uc11c\u2019 \ubd80\ubd84\ub9cc \ud55c \ubb38\uc7a5\uc73c\ub85c \ub2e4\uc2dc \ub9d0\ud574\ubcfc\ub798?", "\uc88b\uc544, \uc774\uc81c \ub9c8\uc9c0\ub9c9\uc73c\ub85c \u2018\uadf8\ub798\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc740 \uc5bc\ub9c8\ub2e4\u2019\ub77c\uace0 \ud55c \ubc88\uc5d0 \uc774\uc5b4\uc11c \ub9d0\ud574\ubcf4\uc790.", "\uc124\uba85\uc774 \uc870\uae08 \uc9e7\uc544\ub3c4 \uad1c\ucc2e\uc544. \u2018\uba3c\uc800 ~, \uadf8\ub9ac\uace0 ~, \uadf8\ub798\uc11c ~\u2019\ucc98\ub7fc \uc21c\uc11c\ub97c \ub098\ub204\uc5b4\uc11c \ub9d0\ud574\ubcf4\uba74 \ub354 \uc774\ud574\ud558\uae30 \uc26c\uc6cc."], "forbidden": ["\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8\uc774\ub098 \ub2a5\ub825\uacfc \uad00\ub828\ub41c \ub9d0\uc744 \ud558\uc9c0 \uc54a\uae30", "\ud559\uc0dd \ub2f5\uc774 \uc9e7\ub2e4\uace0 \uc2e4\ud328\ub77c\uace0 \ub9d0\ud558\uc9c0 \uc54a\uae30", "\uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uac70\ub098 \ub9d0\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 150, "postPracticeReflection": ["\uc6d0\ub798 \uac00\uaca9\ubd80\ud130 \ucc28\ub840\ub300\ub85c \ub9d0\ud558\ub2c8 \uc880 \ub354 \uc774\ud574\uac00 \uc798 \ub410\uc5b4\uc694.", "\ud560\uc778 \uae08\uc561\uc744 \ubd84\uc218\ub85c \ub9d0\ud558\ub294 \uac8c \uc870\uae08 \ud5f7\uac08\ub838\uc5b4\uc694.", "\ub0bc \ub3c8\uc744 \ub2e4\uc2dc \uacc4\uc0b0\ud574 \ubcf4\uba74\uc11c \ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud574\ubcf4\uace0 \uc2f6\uc5b4\uc694."]}}], "assets": [{"id": "asset_content_learning_fraction_store_discount_hero", "missionContentId": "content_learning_fraction_store_discount", "stageId": null, "assetRole": "hero", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud55c\uad6d \uc911\ud559\uad50 \uc548\uc5d0 \uc788\ub294 \ubc1d\uc740 \ubd84\uc704\uae30\uc758 \ud559\uad50 \ub9e4\uc810 \ub0b4\ubd80 \uc804\uacbd. \ub2e4\uc591\ud55c \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \uc9c4\uc5f4\ub41c \uc9c4\uc5f4\ub300\uc640 \ub0c9\uc7a5\uace0\uac00 \ubcf4\uc774\uace0, \uc9c4\uc5f4\ub300 \uc55e\uc5d0\ub294 \uc911\ud559\uc0dd \ub0a8\ud559\uc0dd \ud55c \uba85\uc774 \uac04\uc2dd\uc744 \uace0\ub974\uba70 \uac00\uaca9\ud45c\ub97c \uc720\uc2ec\ud788 \ubc14\ub77c\ubcf4\uace0 \uc788\ub2e4. \uba87\uba87 \uac00\uaca9\ud45c\uc5d0\ub294 \ub178\ub780\uc0c9\uc774\ub098 \ube68\uac04\uc0c9\uc758 \uc791\uc740 \u2018\ud560\uc778\u2019 \uc2a4\ud2f0\ucee4\ub098 \uc138\uc77c \uc544\uc774\ucf58\uc774 \ubd99\uc5b4 \uc788\uc9c0\ub9cc, \uad6c\uccb4\uc801\uc778 \uc22b\uc790\ub098 \ubd84\uc218, \ubb38\uc81c \ubb38\uc7a5\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\ubcf5\uc774\ub098 \ud6c4\ub4dc\ud2f0\ub97c \uc785\uc740 \ud559\uc0dd\uc774 \uace0\ubbfc\ud558\ub294 \ud45c\uc815\uc73c\ub85c \uac00\uaca9\ud45c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74. \uc804\ubc18\uc801\uc778 \uc2a4\ud0c0\uc77c\uc740 \uc120\uba85\ud55c \uc0c9\uac10\uc758 \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ub9cc\ud654\uac00 \uc544\ub2c8\ub77c \uc0ac\uc2e4\uc801\uc778 \ub290\ub08c. \uadf8\ub9bc \uc548\uc5d0\ub294 \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8, \uc218\uc2dd \uac19\uc740 \uae34 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "hero", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_hero_audio", "missionContentId": "content_learning_fraction_store_discount", "stageId": null, "assetRole": "hero", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\uc624\ub298\uc740 \ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0b4 \ub54c, \ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0 \uc6d0\ub798 \uac00\uaca9\uc5d0\uc11c \uc5bc\ub9c8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0, \uadf8\ub798\uc11c \ub0b4\uac00 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \ucc28\uadfc\ucc28\uadfc \uc0b4\ud3b4\ubcfc \uac70\uc608\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_1", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_1", "assetRole": "stage_1", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud559\uad50 \ub9e4\uc810 \uc548\ucabd \ud55c \ucf54\ub108\ub97c \ud074\ub85c\uc988\uc5c5\ud55c \uc7a5\uba74. \uc9c4\uc5f4\ub300\uc5d0 \uacfc\uc790 1~2\uac1c\uc640 \uc74c\ub8cc\uac00 \ub193\uc5ec \uc788\uace0, \uac01 \ubb3c\uac74 \uc544\ub798\uc5d0\ub294 \ud770\uc0c9 \uac00\uaca9\ud45c\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uac00\uaca9\ud45c\uc5d0\ub294 \uad75\uc740 \uae00\uc528\uc758 \uae30\ubcf8 \uac00\uaca9 \uc22b\uc790 \ubaa8\uc591\uacfc \uadf8 \uc606\uc5d0 \uc791\uc740 \ube68\uac04\uc0c9 \ud560\uc778 \ubc30\uc9c0\ub098 \u2018\ud560\uc778\u2019 \uc544\uc774\ucf58\uc774 \ubd99\uc5b4 \uc788\uc9c0\ub9cc, \uae00\uc790\ub294 \ud750\ub9bf\ud574\uc11c \uc77d\ud788\uc9c0 \uc54a\uace0 \uad6c\uccb4\uc801\uc778 \uc218\uc2dd\uc774\ub098 \ubb38\uc81c \ubb38\uc7a5\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc55e\ucabd\uc5d0\ub294 \uc911\ud559\uc0dd \uc815\ub3c4\uc758 \ud559\uc0dd\uc774 \ud55c \uc190\uac00\ub77d\uc73c\ub85c \uac00\uaca9\ud45c\ub97c \uac00\ub9ac\ud0a4\uba70 \uc0b4\ud3b4\ubcf4\uace0 \uc788\ub294 \ubaa8\uc2b5. \ucc28\ubd84\ud55c \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c, \uc7a5\uba74 \uc124\uba85\ub9cc \uc788\uace0 \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub098 \uc815\ub2f5\uc744 \uc554\uc2dc\ud558\ub294 \uc22b\uc790 \uc870\ud569\uc740 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_1", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_1_audio", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_1", "assetRole": "stage_1", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ub9e4\uc810 \uc9c4\uc5f4\ub300\ub97c \ubcf4\uba74, \ubb3c\uac74 \uc544\ub798\uc5d0 \uc6d0\ub798 \uac00\uaca9\uc774 \uc801\ud600 \uc788\uace0 \uc606\uc5d0 \ud560\uc778 \ud45c\uc2dc\uac00 \ud568\uaed8 \ubcf4\uc774\uc8e0. \uc774\uc81c \uc774 \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74\uc11c, \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \uc21c\uc11c\ub97c \uba38\ub9bf\uc18d\uc5d0 \uadf8\ub824\ubcfc\uac8c\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_2", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_2", "assetRole": "stage_2", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud559\uad50 \ub9e4\uc810 \uce74\uc6b4\ud130 \uadfc\ucc98\ub97c \ubc30\uacbd\uc73c\ub85c, \uac00\uc6b4\ub370\uc5d0\ub294 \ud3ec\uc7a5\ub41c \uacfc\uc790 \ud55c \uac1c\uac00 \ud06c\uac8c \ubcf4\uc774\uace0, \uadf8 \uc8fc\ubcc0\uc5d0\ub294 \uc138 \uc7a5\uc758 \ube48 \uce74\ub4dc\ub098 \ub9d0\ud48d\uc120 \uac19\uc740 \uc601\uc5ed\uc774 \ub465\uae00\uac8c \ubc30\uce58\ub418\uc5b4 \uc788\ub2e4. \ud55c \uce74\ub4dc\ub294 \uc804\uccb4 \uac00\uaca9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub3d9\uc804 \ub354\ubbf8 \uc544\uc774\ucf58, \ud55c \uce74\ub4dc\ub294 \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub294 \ud654\uc0b4\ud45c\uc640 \ud560\uc778 \uc544\uc774\ucf58, \ub2e4\ub978 \ud55c \uce74\ub4dc\ub294 \uc9c0\uac11\uc5d0\uc11c \ub3c8\uc774 \ub098\uac00\ub294 \uc791\uc740 \uc544\uc774\ucf58\uc73c\ub85c \ud45c\ud604\ud55c\ub2e4. \uce74\ub4dc \uc548\uc5d0\ub294 \uc22b\uc790\ub098 \ubd84\uc218 \uae30\ud638, \ubb38\uc81c \ubb38\uc7a5\uc740 \uc801\ud600 \uc788\uc9c0 \uc54a\uace0, \ub2e8\uc9c0 \uc21c\uc11c\ub97c \ub9de\ucd94\ub294 \ub2e8\uacc4 \uce74\ub4dc \ub290\ub08c\ub9cc \uc8fc\ub3c4\ub85d \ud55c\ub2e4. \uc804\ubc18\uc801\uc73c\ub85c \uac04\ub2e8\ud558\uace0 \uc120\uba85\ud55c \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8\uc774\uba70, \uc815\ub2f5 \uc21c\uc11c\ub97c \uc554\uc2dc\ud558\ub294 1,2,3 \ubc88\ud638\ub098 \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_2", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_2_audio", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_2", "assetRole": "stage_2", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\uc774\uc81c \uacfc\uc790 \ud55c \uac1c\ub97c \uc815\ud574\uc11c, \uc6d0\ub798 \uac00\uaca9\uc744 \uba3c\uc800 \ubcf4\uace0, \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\ub294 \uc21c\uc11c\ub97c \uce74\ub4dc\ub85c \uc815\ub9ac\ud574\ubcfc\uac8c\uc694. \uc54c\ub9de\uc740 \uc21c\uc11c\ub97c \uace8\ub77c\ubcf4\uc138\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_3", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_3", "assetRole": "stage_3", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \uc0cc\ub4dc\uc704\uce58 \ud558\ub098\uc758 \uac00\uaca9\ud45c\ub97c \uac00\uae5d\uac8c \ube44\ucd98 \uc7a5\uba74. \uac00\uaca9\ud45c\uc5d0\ub294 \ud55c\uae00\ub85c \ub41c \uc0cc\ub4dc\uc704\uce58 \uc774\ub984\uacfc \uae30\ubcf8 \uac00\uaca9 \uc22b\uc790 \ubaa8\uc591\uc774 \ud750\ub9bf\ud558\uac8c \ud45c\uc2dc\ub418\uc5b4 \uc788\uace0, \uc606\uc5d0\ub294 \ubd84\uc218 \ubaa8\uc591 \uc544\uc774\ucf58\uc774 \ub4e4\uc5b4\uac04 \ud560\uc778 \ubc30\uc9c0\uac00 \ubd99\uc5b4 \uc788\ub2e4. \ubd84\uc218 \uc544\uc774\ucf58\uc740 \uc6d0 \uc548\uc5d0 \ub098\ub220\uc9c4 \uc870\uac01\ucc98\ub7fc \uc0c1\uc9d5\uc801\uc73c\ub85c \ubcf4\uc774\uc9c0\ub9cc, \uc815\ud655\ud55c \uc218\ub098 \uae30\ud638\ub294 \uc77d\ud788\uc9c0 \uc54a\uac8c \ucc98\ub9ac\ud55c\ub2e4. \uc544\ub798\ucabd\uc5d0\ub294 \uc190\uc5d0 \uc791\uc740 \uacc4\uc0b0\uae30\ub97c \ub4e4\uace0 \ud654\uba74\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc911\ud559\uc0dd \uc190\uc774 \ubcf4\uc774\uace0, \ud559\uc0dd\uc774 \ud560\uc778 \uac00\uaca9\uc744 \uace0\ubbfc\ud558\ub294 \ub4ef\ud55c \ubd84\uc704\uae30\ub2e4. \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub098 \uc120\ud0dd\uc9c0, \uc815\ub2f5, \uad6c\uccb4 \uc218\uc2dd\uc740 \uadf8\ub9bc\uc5d0 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_3", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_3_audio", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_3", "assetRole": "stage_3", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ubc29\uae08 \uc5f0\uc2b5\ud55c \uc21c\uc11c\ub97c \ub5a0\uc62c\ub824 \ubcfc\uac8c\uc694. \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9 3,000\uc6d0\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c 1/3\ub9cc\ud07c \uc5bc\ub9c8\ub098 \uc904\uc5b4\ub4dc\ub294\uc9c0 \uc0dd\uac01\ud55c \ub4a4, \ubcf4\uae30\uc5d0\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc744 \uace8\ub77c\ubcf4\uba74 \ub3fc\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_4_realtime", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_4", "assetRole": "stage_4_realtime", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ud559\uad50 \ub9e4\uc810 \uc55e \ud14c\uc774\ube14\uc5d0 \uc911\ud559\uc0dd \ub450 \uba85\uc774 \ub9c8\uc8fc \uc549\uc544 \uc788\ub2e4. \ud55c \ud559\uc0dd\uc740 \uac04\uc2dd\uc744 \uc190\uc5d0 \ub4e4\uace0 \uc788\uace0, \ub2e4\ub978 \ud559\uc0dd\uc774\ub098 \uc120\uc0dd\ub2d8\uc740 \uadf8 \uc124\uba85\uc744 \ub4e3\ub294 \ub4ef \uace0\uac1c\ub97c \ub044\ub355\uc774\uba70 \uc8fc\uc758 \uae4a\uac8c \ub4e3\uace0 \uc788\ub2e4. \ucc45\uc0c1 \uc704\uc5d0\ub294 \uac04\ub2e8\ud55c \ub9e4\uc810 \uc601\uc218\uc99d\uc774\ub098 \uc791\uc740 \uac00\uaca9\ud45c \ud55c \uc7a5\uc774 \ub193\uc5ec \uc788\uc9c0\ub9cc, \uadf8 \uc704\uc758 \uc22b\uc790\ub098 \ubb38\uc7a5\uc740 \uc54c\uc544\ubcfc \uc218 \uc5c6\uc744 \uc815\ub3c4\ub85c \ud750\ub9bf\ud558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ud3b8\uc548\ud55c \ud45c\uc815\uc73c\ub85c \ub300\ud654\ub97c \ub098\ub204\ub294 \uc7a5\uba74\uc774\ub2e4. \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c\ub85c \ub530\ub73b\ud558\uace0 \ucc28\ubd84\ud55c \ubd84\uc704\uae30\uc774\uba70, \ub9d0\ud48d\uc120 \uc548\uc5d0 \uad6c\uccb4 \uc22b\uc790\ub098 \uc815\ub2f5 \ubb38\uc7a5, \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_4_realtime", "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_learning_fraction_store_discount_stage_4_realtime_audio", "missionContentId": "content_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_4", "assetRole": "stage_4_realtime", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\uc774\uc81c\ub294 \ub124\uac00 \uce5c\uad6c\uc5d0\uac8c \uc9c1\uc811 \uc124\uba85\ud574\ubcfc \ucc28\ub840\uc608\uc694. \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74 \ud558\ub098\ub97c \uace8\ub790\ub2e4\uace0 \uc0dd\uac01\ud558\uace0, \uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \ubd84\uc218\ub85c \uc5bc\ub9c8\ub97c \ud560\uc778\ud574 \uc92c\ub294\uc9c0, \uadf8\ub798\uc11c \ub9c8\uc9c0\ub9c9\uc5d0 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \uc21c\uc11c\ub300\ub85c \ub9d0\ud574\ubcf4\uc138\uc694. \uc9e7\uac8c \ub9d0\ud574\ub3c4 \uad1c\ucc2e\uc544\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}], "teacherReviewSummary": "\ud559\uad50 \ub9e4\uc810 \ud560\uc778 \uc0c1\ud669\uc744 \ud65c\uc6a9\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \uc21c\uc11c\ub97c \ub2e8\uacc4 \uce74\ub4dc\uc640 \ud55c \ubb38\ud56d \uacc4\uc0b0, \ub9c8\uc9c0\ub9c9 \ub9d0\ub85c \uc124\uba85\uae4c\uc9c0 \uc5f0\uacb0\ud55c \uad6c\uc131\uc774\uba70, \ubb38\uc7a5 \uae38\uc774\ub97c \uc904\uc5ec \uc9112 \ud559\uc2b5\uc9c0\uc6d0\ud615 \ud559\uc0dd\uc758 \uc77d\uae30 \ubd80\ub2f4\uc744 \ub0ae\ucd94\uc5c8\uc2b5\ub2c8\ub2e4."}','gpt-5.1','succeeded','{"attempts": [{"attempt": 1, "tokenUsage": {"input_tokens": 15846, "input_tokens_details": {"cached_tokens": 0}, "output_tokens": 5353, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 21199}}, {"attempt": 2, "tokenUsage": {"input_tokens": 20811, "input_tokens_details": {"cached_tokens": 15744}, "output_tokens": 5351, "output_tokens_details": {"reasoning_tokens": 0}, "total_tokens": 26162}}]}',NULL,NULL,0,'2026-05-04T02:10:38.263320+00:00','2026-05-04T02:11:52.124627+00:00');
INSERT INTO agent_runs VALUES('agent_run_4bc7ff1d-eece-4cad-817c-15bfd21d1209','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_life_bus", "caseId": "case_life_bus", "requestedGoal": "[\ub09c\uc774\ub3c4: \uae30\ucd08] \ub3c4\uc11c\uad00\uc5d0\uc11c \ud544\uc694\ud55c \ucc45\uc744 \ucc3e\uae30 \uc704\ud574 \ud45c\uc9c0 \uc0c9\uacfc \ucc45\uc7a5 \ud45c\uc9c0\ud310\uc744 \ud655\uc778\ud558\uace0, \ubaa8\ub97c \ub54c \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uc5f0\uc2b5.", "contentType": "life_support", "caseFile": {"profile": {"id": "student_life_bus", "organizationId": "org_yeongju_center", "externalKey": "demo_student_life_bus", "displayName": "\ubc15\uc218\ubbfc", "grade": "elementary_6", "schoolCode": "8811067", "studentType": "life_support", "primaryNeed": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \uc5f0\uc2b5\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "life_support", "gradeNumber": "6", "className": "1", "interests": ["\ub3d9\ub124 \uc9c0\ub3c4", "\uc5ed\ud560\uadf9"], "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": 91, "gradeLabel": "\ucd086", "studentTypeLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "trackLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "statusLabel": "\ud559\uc2b5", "attendanceLabel": "91%", "summaryLine": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0 \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \ub9d0\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc77c\uc0c1\uc0dd\ud65c \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5", "primaryNeedDetail": "\ub0af\uc120 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc744 \uc9e7\uac8c \ub9d0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc0c1\ud669 \uadf8\ub9bc + \uc21c\uc11c \uce74\ub4dc + \uc5ed\ud560 \ubc1c\ud654", "supportStrategyDetail": "\uc0c1\ud669 \uadf8\ub9bc, \uc21c\uc11c \uce74\ub4dc, \uc9e7\uc740 \ubaa8\ub378 \ubb38\uc7a5, \uc2e4\uc2dc\uac04 \uc5ed\ud560 \ubc1c\ud654 \uc5f0\uc2b5\uc744 \uc870\ud569\ud55c \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uc0c1\ud669 \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc9c0\uae08 \uc5b4\ub514\uc11c \ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0 \uc798 \ud30c\uc545\ud574\uc694.", "\uc5ed\ud560 \uc5f0\uc2b5\uc5d0\uc11c\ub294 \uc9e7\uc740 \ubb38\uc7a5\uc744 \ub530\ub77c \ub9d0\ud558\ub824\ub294 \uc2dc\ub3c4\uac00 \uc88b\uc544\uc694.", "\ub3d9\ub124 \uc9c0\ub3c4\ub098 \uc2e4\uc81c \uc774\ub3d9 \uc7a5\uba74\uc774 \ub098\uc624\uba74 \uad00\uc2ec\uc744 \uc624\ub798 \uc720\uc9c0\ud574\uc694."], "weaknesses": ["\uc5ec\ub7ec \uc774\ub3d9 \ub2e8\uacc4\ub97c \ud55c \ubc88\uc5d0 \uc815\ub9ac\ud558\uba74 \uc21c\uc11c\uac00 \ud5f7\uac08\ub9b4 \uc218 \uc788\uc5b4\uc694.", "\ub3c4\uc6c0\uc774 \ud544\uc694\ud574\ub3c4 \uba3c\uc800 \ub9d0\ub85c \uc694\uccad\ud558\ub294 \uac83\uc740 \uc544\uc9c1 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\ud574\uc694.", "\ub0af\uc120 \uc7a5\uc18c\uc5d0\uc11c\ub294 \ub2e4\uc74c \ud589\ub3d9\uc744 \ud655\uc778\ud574 \uc8fc\ub294 \ub2e8\uc11c\uac00 \ud544\uc694\ud574\uc694."], "emotionalNote": "\uc0c8\ub85c\uc6b4 \uc7a5\uc18c\ub97c \uc0c1\uc0c1\ud560 \ub54c \ubd88\uc548\uc774 \uc62c\ub77c\uac00\uc9c0\ub9cc, \uc608\uace0 \uc774\ubbf8\uc9c0\uac00 \uc788\uc73c\uba74 \ucc38\uc5ec\uac00 \uc548\uc815\ub429\ub2c8\ub2e4.", "responsePattern": "\uc2dc\uac01 \uc21c\uc11c \uce74\ub4dc\uc640 \uc9e7\uc740 \ubaa8\ub378 \ubb38\uc7a5\uc744 \uba3c\uc800 \uc81c\uacf5\ud558\uba74 \uc2e4\uc81c \ub9d0\ud558\uae30 \uc2dc\ub3c4\uac00 \ub298\uc5b4\ub0a9\ub2c8\ub2e4.", "guardianCooperation"