"\ub2e8\uc11c \ucc3e\uae30", "purpose": "\ucc45 \ud45c\uc9c0 \uc0c9\uacfc \ucc45\uc7a5 \ud45c\uc9c0\ud310\uc744 \uac01\uac01 \ub9de\ucdb0 \ubcf4\uba70 \ucc45\uc744 \ucc3e\ub294 \ub370 \ud544\uc694\ud55c \ub2e8\uc11c\ub97c \ud655\uc778\ud569\ub2c8\ub2e4."}, {"step": 3, "stageRole": "action_selection", "templateType": "decision_card", "studentTitle": "\ud589\ub3d9 \uace0\ub974\uae30", "purpose": "\ub2e8\uc11c\ub97c \ubd10\ub3c4 \ucc45\uc744 \ucc3e\uae30 \uc5b4\ub824\uc6b8 \ub54c, \ud63c\uc790 \uacc4\uc18d \ucc3e\uae30\ubcf4\ub2e4 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \uc9e7\uac8c \ubb3c\uc5b4\ubcf4\ub294 \ud589\ub3d9\uc744 \uace0\ub985\ub2c8\ub2e4."}, {"step": 4, "stageRole": "realtime_practice", "templateType": "realtime_roleplay", "studentTitle": "\ud55c \ubc88 \ud574\ubcf4\uae30", "purpose": "\uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ud544\uc694\ud55c \ucc45\uc744 \ucc3e\uace0 \uc788\ub2e4\uace0 \ub9d0\ud558\uace0, \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc9e7\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubd05\ub2c8\ub2e4."}], "imagePackageIntent": [{"assetRole": "hero", "scenePurpose": "\ubc1d\uace0 \uc870\uc6a9\ud55c \ub3c4\uc11c\uad00\uc5d0\uc11c \ud559\uc0dd\uc774 \ucc3e\uc744 \ucc45\uc744 \ub5a0\uc62c\ub9ac\uba70 \ucc45\uc7a5 \ucabd\uc744 \ubc14\ub77c\ubcf4\ub294 \uc804\uccb4 \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.", "mustShow": ["\ucd08\ub4f1\ud559\uc0dd \ud55c \uba85", "\ub3c4\uc11c\uad00 \ucc45\uc7a5", "\uc0c9\uc774 \ub2e4\ub978 \ucc45 \ud45c\uc9c0\ub4e4", "\uc548\ub0b4 \ub370\uc2a4\ud06c\uc5d0 \uc788\ub294 \uc0ac\uc11c \uc120\uc0dd\ub2d8", "\ud3b8\uc548\ud558\uace0 \uc548\uc804\ud55c \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_1", "scenePurpose": "\ud559\uc0dd\uc774 \ub3c4\uc11c\uad00 \uc785\uad6c\uc5d0\uc11c \ud544\uc694\ud55c \ucc45\uc744 \ucc3e\uc73c\ub7ec \ub4e4\uc5b4\uac00\ub294 \uc0c1\ud669\uc744 \uc608\uace0\ud569\ub2c8\ub2e4.", "mustShow": ["\ub3c4\uc11c\uad00 \uc785\u