2a4 \ubc88\ud638/\uc815\ub958\uc7a5/\ub3c4\uc6c0 \uc694\uccad\uc744 \ucc28\ub840\ub300\ub85c \ud655\uc778\ud558\ub294 \uc0dd\ud65c\uc9c0\uc6d0\ud615 \ubbf8\uc158\uc785\ub2c8\ub2e4.", "approvedByUserId": "user_teacher_demo", "approvedAt": "2026-05-02T00:00:00.000Z", "publishedAt": "2026-05-02T00:00:00.000Z"}], "plannerItems": [{"id": "planner_bus_next", "studentId": "student_life_bus", "caseId": "case_life_bus", "periodType": "next_session", "goalText": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5 1\uac1c\ub97c \ub9d0\ud574\ubcf4\uba74 \uc88b\uaca0\uc5b4\uc694.", "checklistJson": {"checks": ["\ubaa9\uc801\uc9c0 \ub9d0\ud558\uae30", "\ub3c4\uc6c0 \uc694\uccad\ud558\uae30"]}, "status": "planned"}], "publicContextSummary": {"schoolCode": "8811067", "schoolName": "\uc601\uc8fc\uac00\ud765\ucd08\ub4f1\ud559\uad50", "schoolKind": "\ucd08\ub4f1\ud559\uad50", "sources": ["curriculum_seed", "neis_open_api"]}}}','null','gpt-5.5','failed','null','MISSION_CONTENT_QUALITY_INVALID','Stage 2 is not clearly the easiest success step for this student. A 2-pair card matching task with four text items may be harder than Stage 3''s simple two-choice action selection.; For a life_support mission with very low reading load and choice limit 2, Stage 2 should use one concrete clue choice first, such as choosing the useful clue for finding the blue animal book.; Stage 4 practice is relevant, but the realtime rubric marks all target behaviors as not required, which weakens practice of the exact behavior used in stages 1-3: saying the book clue and asking the librarian for help.; Revise Stage 2 into the easiest success step: use a simple two-choice clue identification task tied to the same anchor, such as ''파란 표지 동물책을 찾을 때 먼저 볼 것은?'' with choices ''파란 책 표지'' vs ''의자''. Keep Stage 3 as the next action choice: if it is still hard, ask the librarian. In Stage 4, make the key roleplay behaviors required: say the target book clue at least briefly and ask where it is, using a short sentence like ''파란 동물책 어디에 있어요?'' Keep image prompts scene-only with no cards, UI, problem text, speech bubbles, or answer layouts.',1,'2026-05-04T05:05:40.187519+00:00','2026-05-04T05:07:52.805343+00:00');
INSERT INTO agent_runs VALUES('agent_run_6fbfcd91-5583-4c4a-84e1-340aa4177111','orchestrator','orchestrator_plan_v1','OrchestratorPlanV1','{"teacherId": "user_teacher_demo", "studentId": "student_life_bus", "caseId": "case_life_bus", "requestedGoal": "[\ub09c\uc774\ub3c4: \uae30\ucd08] \ub3c4\uc11c\uad00\uc5d0\uc11c \ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc744 \ucc3e\ub294 \uc0c1\ud669. 1\ub2e8\uacc4\ub294 \ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc774\ub77c\ub294 \ud55c \uac00\uc9c0 \ub2e8\uc11c\ub97c \ubcf4\uc5ec\uc8fc\uace0, 2\ub2e8\uacc4\ub294 \uac00\uc7a5 \uc26c\uc6b4 \uc131\uacf5\uc73c\ub85c \ub450 \uc120\ud0dd\uc9c0 \uc911 \ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \uace0\ub974\uac8c \ud55c\ub2e4. 3\ub2e8\uacc4\ub294 \ucc45\uc744 \ubabb \ucc3e\uc73c\uba74 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ubb3c\uc5b4\ubcf4\ub294 \ud589\ub3d9\uc744 \uace0\ub974\uac8c \ud55c\ub2e4. 4\ub2e8\uacc4\ub294 \"\ud30c\ub780 \ub3d9\ubb3c\ucc45 \uc5b4\ub514\uc5d0 \uc788\uc5b4\uc694?\"\ucc98\ub7fc \ucc45 \ub2e8\uc11c\ub97c \ub9d0\ud558\uace0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uc5ed\ud560\uc5f0\uc2b5\uc744 \ud55c\ub2e4. \uc774\ubbf8\uc9c0\ub294 \uce74\ub4dc, \ub9d0\ud48d\uc120, \ubb38\uc81c UI \uc5c6\uc774 \ub3c4\uc11c\uad00 \uc7a5\uba74\ub9cc \ubcf4\uc5ec\uc900\ub2e4.", "contentType": "life_support", "caseFile": {"profile": {"id": "student_life_bus", "organizationId": "org_yeongju_center", "externalKey": "demo_student_life_bus", "displayName": "\ubc15\uc218\ubbfc", "grade": "elementary_6", "schoolCode": "8811067", "studentType": "life_support", "primaryNeed": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \uc5f0\uc2b5\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "life_support", "gradeNumber": "6", "className": "1", "interests": ["\ub3d9\ub124 \uc9c0\ub3c4", "\uc5ed\ud560\uadf9"], "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": 91, "gradeLabel": "\ucd086", "studentTypeLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "trackLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "statusLabel": "\ud559\uc2b5", "attendanceLabel": "91%", "summaryLine": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0 \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \ub9d0\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc77c\uc0c1\uc0dd\ud65c \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5", "primaryNeedDetail": "\ub0af\uc120 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc744 \uc9e7\uac8c \ub9d0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc0c1\ud669 \uadf8\ub9bc + \uc21c\uc11c \uce74\ub4dc + \uc5ed\ud560 \ubc1c\ud654", "supportStrategyDetail": "\uc0c1\ud669 \uadf8\ub9bc, \uc21c\uc11c \uce74\ub4dc, \uc9e7\uc740 \ubaa8\ub378 \ubb38\uc7a5, \uc2e4\uc2dc\uac04 \uc5ed\ud560 \ubc1c\ud654 \uc5f0\uc2b5\uc744 \uc870\ud569\ud55c \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uc0c1\ud669 \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc9c0\uae08 \uc5b4\ub514\uc11c \ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0 \uc798 \ud30c\uc545\ud574\uc694.", "\uc5ed\ud560 \uc5f0\uc2b5\uc5d0\uc11c\ub294 \uc9e7\uc740 \ubb38\uc7a5\uc744 \ub530\ub77c \ub9d0\ud558\ub824\ub294 \uc2dc\ub3c4\uac00 \uc88b\uc544\uc694.", "\ub3d9\ub124 \uc9c0\ub3c4\ub098 \uc2e4\uc81c \uc774\ub3d9 \uc7a5\uba74\uc774 \ub098\uc624\uba74 \uad00\uc2ec\uc744 \uc624\ub798 \uc720\uc9c0\ud574\uc694."], "weaknesses": ["\uc5ec\ub7ec \uc774\ub3d9 \ub2e8\uacc4\ub97c \ud55c \ubc88\uc5d0 \uc815\ub9ac\ud558\uba74 \uc21c\uc11c\uac00 \ud5f7\uac08\ub9b4 \uc218 \uc788\uc5b4\uc694.", "\ub3c4\uc6c0\uc774 \ud544\uc694\ud574\ub3c4 \uba3c\uc800 \ub9d0\ub85c \uc694\uccad\ud558\ub294 \uac83\uc740 \uc544\uc9c1 \u