e4.", "mustShow": ["\ub3c4\uc11c\uad00 \ucc45\uc7a5", "\ud30c\ub780 \ud45c\uc9c0\uc758 \ub3d9\ubb3c\ucc45 \ud55c \uad8c", "\ub3d9\ubb3c\ucc45\uc744 \ucc3e\ub294 \ud559\uc0dd", "\uc870\uc6a9\ud558\uace0 \uc548\uc804\ud55c \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_2", "scenePurpose": "\ucc45\uc7a5 \uc55e\uc5d0\uc11c \ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \ud655\uc778\ud558\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc8fc\ub418, \uc120\ud0dd\uc9c0\ub098 \uc815\ub2f5 \ud45c\uc2dc \uc5c6\uc774 \uc7a5\uba74\ub9cc \uc81c\uacf5\ud569\ub2c8\ub2e4.", "mustShow": ["\ucc45\uc7a5\uc5d0 \uaf42\ud78c \uc5ec\ub7ec \ucc45", "\ub208\uc5d0 \uc798 \ub744\ub294 \ud30c\ub780 \ud45c\uc9c0 \ucc45", "\ub2e4\ub978 \uc0c9 \ud45c\uc9c0 \ucc45", "\ub2e8\uc11c\ub97c \uc0b4\ud3b4\ubcf4\ub294 \ud559\uc0dd"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_3", "scenePurpose": "\ucc45\uc744 \ubc14\ub85c \ucc3e\uc9c0 \ubabb\ud55c \ud559\uc0dd\uc774 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc218 \uc788\ub294 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4.", "mustShow": ["\ub3c4\uc11c\uad00 \uc548\ub0b4 \ub370\uc2a4\ud06c", "\uce5c\uc808\ud55c \uc0ac\uc11c \uc120\uc0dd\ub2d8", "\ucc45\uc7a5 \uadfc\ucc98\uc5d0 \uc120 \ud559\uc0dd", "\ub3c4\uc6c0\uc744 \uc694\uccad\ud558\uae30 \uc88b\uc740 \uac70\ub9ac\uac10"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}, {"assetRole": "stage_4_realtime", "scenePurpose": "\ud559\uc0dd\uc774 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ucc45 \ub2e8\uc11c\ub97c \ub9d0\ud558\uace0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud558\ub294 \uc5f0\uc2b5\uc744 \ud560 \uc218 \uc788\ub3c4\ub85d \uc548\uc815\uc801\uc778 \ub3c4\uc11c\uad00 \ub300\ud654 \uc7a5\uba74\uc744 \ubcf4\uc5ec \uc90d\ub2c8\ub2e4.", "mustShow": ["\uc0ac\uc11c \uc120\uc0dd\ub2d8\uacfc \ub9c8\uc8fc \ubcf4\ub294 \ud559\uc0dd", "\uac00\uae4c\uc6b4 \ucc45\uc7a5", "\ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc774 \uc788\uc744 \ubc95\ud55c \uc5b4\ub9b0\uc774 \ucc45 \ucf54\ub108", "\ubd88\uc548\uc744 \uc904\uc774\ub294 \ubc1d\uace0 \ucc28\ubd84\ud55c \ubd84\uc704\uae30"], "mustNotShow": ["problem text", "choices", "answer", "hint"]}], "ttsNarrationIntent": [{"assetRole": "hero", "voicePurpose": "\uc624\ub298\uc740 \ub3c4\uc11c\uad00\uc5d0\uc11c \ucc45\uc744 \ucc3e\uace0 \ud544\uc694\ud558\uba74 \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubcfc \uac83\uc784\uc744 \uc9e7\uac8c \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_1", "voicePurpose": "\ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc774\ub77c\ub294 \ud55c \uac00\uc9c0 \ub2e8\uc11c\ub97c \ucc9c\ucc9c\ud788 \ub4e4\ub824\uc90d\ub2c8\ub2e4.", "tone": "calm"}, {"assetRole": "stage_2", "voicePurpose": "\ub450 \uac00\uc9c0 \uc911 \ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \uace0\ub974\uba74 \ub41c\ub2e4\uace0 \uac04\ub2e8\ud788 \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "bright"}, {"assetRole": "stage_3", "voicePurpose": "\ucc45\uc744 \ubabb \ucc3e\uc73c\uba74 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ubb3c\uc5b4\ubcf4\ub294 \ud589\ub3d9\uc744 \uace0\ub974\ub3c4\ub85d \uc548\ub0b4\ud569\ub2c8\ub2e4.", "tone": "reassuring"}, {"assetRole": "stage_4_realtime", "voicePurpose": "\ud30c\ub780 \ub3d9\ubb3c\ucc45 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc9e7\uac8c \ubb3c\uc5b4\ubcf4\ub294 \uc5f0\uc2b5\uc744 \uc2dc\uc791\ud558\ub3c4\ub85d \uaca9\ub824\ud569\ub2c8\ub2e4.", "tone": "reassuring"}], "teacherReviewFocus": ["2\ub2e8\uacc4 \uc120\ud0dd\uc9c0\uac00 \ub450 \uac1c\ub85c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc740 \u201c\ud30c\ub780 \ub3d9\ubb3c\ucc45 \uc5b4\ub514\uc5d0 \uc788\uc5b4\uc694?\u201d\ucc98\ub7fc \uc9e7\uace0 \ub530\ub77c \ub9d0\ud558\uae30 \uc26c\uc6b4 \ud615\ud0dc\ub85c \uc81c\uc2dc\ud574 \uc8fc\uc138\uc694.", "\uc774\ubbf8\uc9c0\uc5d0\ub294 \uce74\ub4dc, \ub9d0\ud48d\uc120, \ubb38\uc81c \ud654\uba74, \uc120\ud0dd\uc9c0, \uc815\ub2f5 \ud45c\uc2dc\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub3c4\ub85d \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc0c8\ub85c\uc6b4 \uc7a5\uc18c\uc5d0\uc11c \ubd88\uc548\uc774 \uc62c\ub77c\uc62c \uc218 \uc788\uc73c\ubbc0\ub85c \uc5ed\ud560 \uc5f0\uc2b5 \uc804 \ub3c4\uc11c\uad00 \uc7a5\uba74\uc744 \ucda9\ubd84\ud788 \uc608\uace0\ud574 \uc8fc\uc138\uc694."], "safetyNotes": ["\ud559\uc0dd \uac1c\uc778\uc815\ubcf4\ub098 \uc2e4\uc81c \ud559\uad50 \uc704\uce58\ub97c \ub300\ud654\uc5d0 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "\ub3c4\uc11c\uad00 \uc7a5\uba74\uc740 \uc548\uc804\ud558\uace0 \uc870\uc6a9\ud55c \ubd84\uc704\uae30\ub85c \uad6c\uc131\ud569\ub2c8\ub2e4.", "\ud559\uc0dd\uc774 \ub9d0\ud558\uae30\ub97c \uba48\ucd94\uba74 \ubb38\uc7a5\uc744 \ub354 \uc9e7\uac8c \ub098\ub204\uc5b4 \ub530\ub77c \ub9d0\ud560 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.", "\ud559\uad50 \uacf5\uac1c \uc815\ubcf4\ub294 \ubc30\uacbd \ucc38\uace0\uc6a9\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uace0 \uac1c\uc778 \ub2a5\ub825 \ud310\ub2e8\uc5d0 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."]}, "caseFile": {"profile": {"id": "student_life_bus", "organizationId": "org_yeongju_center", "externalKey": "demo_student_life_bus", "displayName": "\ubc15\uc218\ubbfc", "grade": "elementary_6", "schoolCode": "8811067", "studentType": "life_support", "primaryNeed": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c \ud655\uc778\uacfc \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \uc5f0\uc2b5\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "profileJson": {"ageBand": "life_support", "gradeNumber": "6", "className": "1", "interests": ["\ub3d9\ub124 \uc9c0\ub3c4", "\uc5ed\ud560\uadf9"], "readingLoad": "very_low", "choiceCountLimit": 2, "dashboard": {"attendanceRate": 91, "gradeLabel": "\ucd086", "studentTypeLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "trackLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\u