deLabel": "\ucd086", "studentTypeLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "trackLabel": "\uc77c\uc0c1\uc0dd\ud65c \uc9c0\uc6d0\ud615", "statusLabel": "\ud559\uc2b5", "attendanceLabel": "91%", "summaryLine": "\uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0 \ub3c4\uc6c0 \uc694\uccad \ud45c\ud604\uc744 \ub9d0\ud558\ub294 \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5\uc774 \uc798 \ub9de\uc544 \ubcf4\uc5ec\uc694.", "primaryNeedTitle": "\uc77c\uc0c1\uc0dd\ud65c \uc758\uc0ac\uc18c\ud1b5 \uc218\uc5c5", "primaryNeedDetail": "\ub0af\uc120 \uc0dd\ud65c \uc0c1\ud669\uc5d0\uc11c \ub2e8\uc11c\ub97c \ud655\uc778\ud558\uace0 \ud544\uc694\ud55c \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5\uc744 \uc9e7\uac8c \ub9d0\ud558\ub294 \uc218\uc5c5\uc774 \uc88b\uaca0\uc5b4\uc694.", "supportStrategyTitle": "\uc0c1\ud669 \uadf8\ub9bc + \uc21c\uc11c \uce74\ub4dc + \uc5ed\ud560 \ubc1c\ud654", "supportStrategyDetail": "\uc0c1\ud669 \uadf8\ub9bc, \uc21c\uc11c \uce74\ub4dc, \uc9e7\uc740 \ubaa8\ub378 \ubb38\uc7a5, \uc2e4\uc2dc\uac04 \uc5ed\ud560 \ubc1c\ud654 \uc5f0\uc2b5\uc744 \uc870\ud569\ud55c \ucf58\ud150\uce20\uac00 \uc88b\uaca0\uc5b4\uc694.", "strengths": ["\uc0c1\ud669 \uadf8\ub9bc\uc744 \ubcf4\uba74 \uc9c0\uae08 \uc5b4\ub514\uc11c \ubb34\uc5c7\uc744 \ud574\uc57c \ud558\ub294\uc9c0 \uc798 \ud30c\uc545\ud574\uc694.", "\uc5ed\ud560 \uc5f0\uc2b5\uc5d0\uc11c\ub294 \uc9e7\uc740 \ubb38\uc7a5\uc744 \ub530\ub77c \ub9d0\ud558\ub824\ub294 \uc2dc\ub3c4\uac00 \uc88b\uc544\uc694.", "\ub3d9\ub124 \uc9c0\ub3c4\ub098 \uc2e4\uc81c \uc774\ub3d9 \uc7a5\uba74\uc774 \ub098\uc624\uba74 \uad00\uc2ec\uc744 \uc624\ub798 \uc720\uc9c0\ud574\uc694."], "weaknesses": ["\uc5ec\ub7ec \uc774\ub3d9 \ub2e8\uacc4\ub97c \ud55c \ubc88\uc5d0 \uc815\ub9ac\ud558\uba74 \uc21c\uc11c\uac00 \ud5f7\uac08\ub9b4 \uc218 \uc788\uc5b4\uc694.", "\ub3c4\uc6c0\uc774 \ud544\uc694\ud574\ub3c4 \uba3c\uc800 \ub9d0\ub85c \uc694\uccad\ud558\ub294 \uac83\uc740 \uc544\uc9c1 \ubd80\ub2f4\uc2a4\ub7ec\uc6cc\ud574\uc694.", "\