d55c \uc0dd\ud65c \uc5f0\uc2b5\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ucc28\ubd84\ud558\uace0 \uba85\ud655\ud55c \uad6c\uc131", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ud654\uba74\uc6a9 \ud45c\uc2dc", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\ucc45 \uc81c\ubaa9 \uae00\uc790", "\uae34 \ud14d\uc2a4\ud2b8"], "textRenderingPolicy": "scene_only_no_problem_text"}, "sourceText": null, "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_generated_001_stage_1_audio", "missionContentId": "content_generated_001", "stageId": "stage_content_generated_001_1", "assetRole": "stage_1", "assetType": "audio", "provider": "elevenlabs", "model": "eleven_multilingual_v2", "promptJson": null, "sourceText": "\ub3c4\uc11c\uad00\uc5d0 \uc654\uc5b4\uc694. \uc624\ub298 \ucc3e\uc744 \ucc45\uc740 \ud30c\ub780 \ud45c\uc9c0\uc758 \ub3d9\ubb3c\ucc45\uc774\uc5d0\uc694. \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uba74 \ub3fc\uc694.", "storageUrl": "", "previewUrl": null, "qaStatus": "pending", "approvalStatus": "pending"}, {"id": "asset_content_generated_001_stage_2", "missionContentId": "content_generated_001", "stageId": "stage_content_generated_001_2", "assetRole": "stage_2", "assetType": "image", "provider": "openai", "model": "gpt-image-2", "promptJson": {"prompt": "\ub3c4\uc11c\uad00 \ucc45\uc7a5\uc5d0 \uc5ec\ub7ec \uad8c\uc758 \ucc45\uc774 \uc815\ub3c8\ub418\uc5b4 \uc788\ub294 \uac00\uae4c\uc6b4 \uad00\ucc30 \uc7a5\uba74. \ud30c\ub780 \ud45c\uc9c0\uc758 \ucc45 \ud55c \uad8c\uc5d0\ub294 \uae00\uc790 \uc5c6\uc774 \uadc0\uc5ec\uc6b4 \ub3d9\ubb3c \uadf8\ub9bc \uc544\uc774\ucf58\uc774 \uc788\uace0, \uc606\uc5d0\ub294 \ud30c\ub780\uc0c9\uc774 \uc544\ub2cc \ub2e4\ub978 \uc0c9 \ucc45 \ud55c\ub450 \uad8c\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud559\uc0dd\uc774 \uc0c9 \ub2e8\uc11c\ub97c \uc27d\uac8c \ubcfc \uc218 \uc788\ub3c4\ub85d \ubc1d\uace0 \ub2e8\uc21c\ud55c \uad6c\ub3c4. \uc2e4\uc81c \ucc45\uc7a5 \uc7a5\uba74