INSERT INTO planner_items VALUES('planner_clock_next','student_learning_clock','case_learning_clock','next_session','시간 읽기 기초를 짧은 시각 단서와 2개 선택지로 익혀보면 좋겠어요.','{"checks": ["\uc9e7\uc740 \ubc14\ub298 \ucc3e\uae30", "2\uac1c \uc120\ud0dd\uc9c0\uc5d0\uc11c \uc2dc\uac04 \uace0\ub974\uae30"]}','planned');
INSERT INTO planner_items VALUES('planner_fraction_next','student_learning_fraction','case_learning_fraction','next_session','분수의 전체-부분 관계를 단계 카드로 설명해보면 좋겠어요.','{"checks": ["\uccab \ubb38\uc81c \uc131\uacf5\uacbd\ud5d8", "\ubd84\ubaa8/\ubd84\uc790 \uc704\uce58 \uc7ac\ud655\uc778"]}','planned');
INSERT INTO mission_contents VALUES('content_bus_001','case_life_bus','student_life_bus','life_support','센터 가는 길: 버스 타기','버스를 타고 센터에 갈 때 필요한 단서와 도움 요청 문장을 연습한다.','approved',4,'{"strategy": "\uc0dd\ud65c \uc7a5\uba74 \uc774\ubbf8\uc9c0, \ub2e8\uc11c \ucc3e\uae30, \ud589\ub3d9 \uc120\ud0dd, 4\ub2e8\uacc4 \uc2e4\uc2dc\uac04 \uc5ed\ud560 \ubc1c\ud654 \uc5f0\uc2b5"}','버스 번호/정류장/도움 요청을 차례대로 확인하는 생활지원형 미션입니다.','user_teacher_demo','2026-05-02T00:00:00.000Z',NULL);
INSERT INTO mission_contents VALUES('content_bus_to_center_001','case_learning_clock','student_learning_clock','learning_focus','버스를 타고 센터에 가요','버스를 타고 센터에 갈 때, 그림을 보고 순서를 떠올리고 잘못 탄 것 같을 때 짧게 도움을 요청하는 말을 연습한다.','published',4,'{"orchestratorPlanVersion": "orchestrator_plan_v1", "targetSkill": "\uc0dd\ud65c \uc7a5\uba74\uc5d0\uc11c \ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c\ub97c \ud655\uc778\ud558\uace0, \uae38\uc774 \ud5f7\uac08\ub9b4 \ub54c \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \uc694\uccad\ud574 \ubcf4\uae30", "strategy": "\uc9e7\uc740 \uadf8\ub9bc \ub2e8\uc11c\uc640 2\uc9c0\uc120\ub2e4 \uc120\ud0dd, \uc21c\uc11c \ub9de\ucd94\uae30, \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud574 \ubcf4\ub294 \ub2e8\uacc4 \uc5f0\uc2b5", "teacherReviewFocus": ["\ub2e8\uacc4 1~3\uc758 \ubaa8\ub4e0 \ubb38\uc7a5\uc774 \ud55c \ubb38\uc7a5 \ub610\ub294 \ub9e4\uc6b0 \uc9e7\uc740 \ub450 \ubb38\uc7a5 \uc774\ub0b4\ub85c \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ubaa8\ub4e0 \uc120\ud0dd\uc9c0\ub294 2\uac1c\ub9cc \uc81c\uc2dc\ub418\ub3c4\ub85d \ud15c\ud50c\ub9bf \uc124\uc815\uacfc \ubb38\ud56d \uad6c\uc131\uc744 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694.", "\ubc84\uc2a4 \ud0c0\ub294 \uc21c\uc11c(\uae30\ub2e4\ub9ac\uae30 \u2192 \ud0c0\uae30 \u2192 \uce74\ub4dc/\ub3c8 \ub0b4\uae30)\uac00 \uc2e4\uc81c \uc9c0\uc5ed \uad50\ud1b5 \uc0c1\ud669\uacfc \ucda9\ub3cc\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc2e4\uc2dc\uac04 \ub9d0\ud558\uae30 \uc5f0\uc2b5 \ubb38\uc7a5(\u2018\ub3c4\uc640\uc8fc\uc138\uc694.\u2019, \u2018\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\u2019 \ub4f1)\uc774 \ud559\uc0dd\uc5d0\uac8c \uc2e4\uc81c\ub85c \ud65c\uc6a9 \uac00\ub2a5\ud55c \ud45c\ud604\uc778\uc9c0, \ud559\uad50\u00b7\uac00\uc815\uacfc \ud611\uc758\ub41c \ud45c\ud604\uc778\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\uc624\ub2f5 \uc120\ud0dd \uc2dc \ud53c\ub4dc\ubc31 \ubb38\uc7a5\uc774 \uc9e7\uace0 \ubd80\ub2f4\uc774 \uc801\uc73c\uba70, \uc7ac\uc2dc\ub3c4 \uc758\uc695\uc744 \ub5a8\uc5b4\ub728\ub9ac\uc9c0 \uc54a\ub294\uc9c0 \uac80\ud1a0\ud574 \uc8fc\uc138\uc694."], "generatedAt": "2026-05-03T01:11:17.295811+00:00", "requestedChanges": []}','교사 검토 완료','user_teacher_demo','2026-05-03T03:11:11.383291+00:00','2026-05-03T03:11:13.010725+00:00');
INSERT INTO mission_contents VALUES('content_clock_001','case_learning_clock','student_learning_clock','learning_focus','시계 탐험: 약속 시간 찾기','시계 그림에서 시침과 분침 단서를 보고 약속 시간을 고른다.','revision_requested',4,'{"achievementStandard": "\uc2dc\uacc4\uc758 \uc2dc\uce68\uacfc \ubd84\uce68\uc744 \ubcf4\uace0 \uc815\uac01 \uc2dc\uac04\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4.", "strategy": "\uadf8\ub9bc \ub2e8\uc11c, 2\uac1c \uc120\ud0dd\uc9c0, \uc9e7\uc740 \uc9c0\uc2dc\ubb38, 4\ub2e8\uacc4 \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud558\ub294 \uc2e4\uc2dc\uac04 \ubc1c\ud654 \uc5f0\uc2b5", "requestedChanges": []}','교사 검토에서 이번 수업에 사용하지 않음','user_teacher_demo','2026-05-02T00:00:00.000Z','2026-05-02T00:00:00.000Z');
INSERT INTO mission_contents VALUES('content_fraction_001','case_learning_fraction','student_learning_fraction','learning_focus','분수 탐험: 빛나는 한 조각','전체 4개 중 1개를 1/4로 표현하고 말로 설명한다.','published',4,'{"achievementStandard": "\uc804\uccb4\uc640 \ubd80\ubd84\uc758 \uad00\uacc4\ub97c \ubd84\uc218\ub85c \ud45c\ud604\ud560 \uc218 \uc788\ub2e4.", "strategy": "\uc2dc\uac01 \uc790\ub8cc\uc640 \uc9e7\uc740 \uc124\uba85, 4\ub2e8\uacc4 \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud558\ub294 \uc2e4\uc2dc\uac04 \ubc1c\ud654 \uc5f0\uc2b5"}','분모/분자 위치 혼동을 줄이기 위해 전체 수를 먼저 세는 흐름입니다.','user_teacher_demo','2026-05-02T00:00:00.000Z','2026-05-02T00:00:00.000Z');
INSERT INTO mission_contents VALUES('content_generated_001','case_life_bus','student_life_bus','life_support','도서관에서 파란 동물책 찾기','도서관에서 파란 표지 동물책 단서를 확인하고, 책을 못 찾으면 사서 선생님에게 짧게 도움을 요청한다.','published',4,'{"orchestratorPlanVersion": "orchestrator_plan_v1", "targetSkill": "\ucc45 \ub2e8\uc11c \ud655\uc778\ud558\uae30\uc640 \ub3c4\uc6c0 \uc694\uccad \ubb38\uc7a5 \ub9d0\ud558\uae30", "strategy": "\uc26c\uc6b4 \uc7a5\uba74 \uad00\ucc30\ub85c \ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0, \ucc45\uc7a5 \uc0b4\ud53c\uae30 \ub4a4 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uaed8 \uc9e7\uac8c \ubb3b\ub294 \uc21c\uc11c\ub97c \uc5f0\uc2b5\ud569\ub2c8\ub2e4.", "teacherReviewFocus": ["2\ub2e8\uacc4\uac00 \uc7a5\uba74 \uad00\ucc30\ud615 \ub450 \uc120\ud0dd\uc9c0\ub85c \uad6c\uc131\ub418\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "3\ub2e8\uacc4\uac00 \ucc45\uc744 \ubabb \ucc3e\uc558\uc744 \ub54c \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ubb3b\ub294 \ud589\ub3d9\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "4\ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd\uc774 \ucc45 \ub2e8\uc11c\uc640 \ub3c4\uc6c0 \uc694\uccad\uc744 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub9d0\ud560 \uc218 \uc788\uac8c \ubb38\uc7a5\uc774 \ub108\ubb34 \uae38\uc9c0 \uc54a\uc740\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694.", "\ubaa8\ub4e0 \uc774\ubbf8\uc9c0\uc5d0 \ub300\ud654 \ud45c\uc2dc, \ubb38\uc81c \ud654\uba74, \uc815\ub2f5 \ud45c\uc2dc\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud574 \uc8fc\uc138\uc694."], "generatedAt": "2026-05-04T05:15:41.640982+00:00"}','교사 검토 완료','user_teacher_demo','2026-05-04T06:11:01.563719+00:00','2026-05-04T05:33:47.579461+00:00');
INSERT INTO mission_contents VALUES('content_learning_fraction_store_discount','case_learning_fraction','student_learning_fraction','learning_focus','매점 할인 가격, 분수로 차근차근 계산하기','학교 매점 가격표를 보고 ‘원래 가격 → 할인 금액 → 낼 돈’을 분수와 단계 카드로 차례대로 파악해 최종 가격을 고르고, 왜 그 금액인지 짧게 설명한다.','teacher_review',4,'{"orchestratorPlanVersion": "orchestrator_plan_v1", "targetSkill": "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778 \uc815\ubcf4\ub97c \ubcf4\uace0 \uc804\uccb4 \uae08\uc561, \uc904\uc5b4\ub4dc\ub294 \uae08\uc561, \ub0a8\ub294 \uae08\uc561\uc744 \uc21c\uc11c\ub300\ub85c \uc774\ud574\ud558\uace0 \uc124\uba85\ud558\uae30", "strategy": "\ub9e4\uc810 \uc7a5\uba74 \uadf8\ub9bc\uacfc \ub2e8\uacc4 \uce74\ub4dc\ub97c \ud65c\uc6a9\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ud560\uc778 \uae08\uc561 \u2192 \ub0bc \ub3c8\u2019 \ud750\ub984\uc744 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \uc775\ud78c \ub4a4, \ubcf4\uae30\uc5d0\uc11c \ucd5c\uc885 \uac00\uaca9\uc744 \uace0\ub974\uace0 \ub9d0\ub85c \ub2e4\uc2dc \uc124\uba85\ud558\uae30", "teacherReviewFocus": ["\ub9e4\uc810 \ud560\uc778 \uc0c1\ud669\uc774 \uc911\ud559\uc0dd \uc218\uc900\uc5d0 \uc801\uc808\ud558\uace0, \ubd84\uc218 \uac1c\ub150 \ubcf5\uc2b5\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\ub418\ub294\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\uac01 \ub2e8\uacc4 \uc124\uba85 \ubb38\uc7a5\uc774 \uc9e7\uace0 \uba85\ub8cc\ud558\uac8c \uad6c\uc131\ub418\uc5b4 \uae34 \uae00\uc744 \uc77d\uae30 \uc5b4\ub824\uc6b4 \ud559\uc0dd\uc5d0\uac8c \uacfc\ubd80\ud558\uac00 \ub418\uc9c0 \uc54a\ub294\uc9c0 \ubd10\uc8fc\uc138\uc694.", "\ub2e8\uacc4 \ud750\ub984\uc774 \u2018\uc6d0\ub798 \uac00\uaca9 \ubcf4\uae30 \u2192 \ud560\uc778 \uae08\uc561 \ucc3e\uae30 \u2192 \ub0bc \ub3c8 \uace0\ub974\uae30\u2019\ub85c \ubd84\uba85\ud558\uac8c \ub4dc\ub7ec\ub098\ub294\uc9c0 \uac80\ud1a0\ud574\uc8fc\uc138\uc694.", "\ubd84\uc218\ub85c \ud45c\uc2dc\ub41c \ud560\uc778\uc5d0\uc11c \ubd84\ubaa8\u00b7\ubd84\uc790 \uc758\ubbf8\ub97c \ud63c\ub3d9\ud558\uc9c0 \uc54a\ub3c4\ub85d \ud53c\ub4dc\ubc31 \ubb38\uad6c\uc640 \ubcf4\uae30 \uad6c\uc131\uc774 \uc801\uc808\ud55c\uc9c0 \ud655\uc778\ud574\uc8fc\uc138\uc694.", "\ub9c8\uc9c0\ub9c9 \uc124\uba85 \ub2e8\uacc4\uc5d0\uc11c \ud559\uc0dd\uc774 \uc790\uc2e0\uc758 \ub9d0\ub85c \uc815\ub9ac\ud560 \uc218 \uc788\ub3c4\ub85d \uc9c8\ubb38\uc774 \uac1c\ubc29\uc801\uc774\ub418, \ubd80\ub2f4\uc2a4\ub7fd\uc9c0 \uc54a\uc740\uc9c0 \uc810\uac80\ud574\uc8fc\uc138\uc694."], "generatedAt": "2026-05-04T02:11:52.104455+00:00"}','학교 매점 할인 상황을 활용해 ‘원래 가격 → 분수로 된 할인 금액 → 낼 돈’ 순서를 단계 카드와 한 문항 계산, 마지막 말로 설명까지 연결한 구성이며, 문장 길이를 줄여 중2 학습지원형 학생의 읽기 부담을 낮추었습니다.',NULL,NULL,NULL);
INSERT INTO content_stages VALUES('stage_bus_1','content_bus_001',1,'scenario_intro','scenario_intro','상황 만나기','센터에 가야 하는 상황을 살펴보세요.','{"imageAssetId": "asset_content_bus_001_stage_1", "audioAssetId": "asset_content_bus_001_stage_1_audio", "storyText": "\uc218\ubbfc\uc774\uac00 \uc6b0\ub9ac \ub3d9\ub124 \uc13c\ud130\uc5d0 \uac00\ub824\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0 \uc654\uc5b4\uc694.", "missionText": "\ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud574\uc57c \ud560\uae4c\uc694?", "assetBundle": {"imageAssetId": "asset_content_bus_001_stage_1", "audioAssetId": "asset_content_bus_001_stage_1_audio"}}','null',1);
INSERT INTO content_stages VALUES('stage_bus_2','content_bus_001',2,'clue_identification','scene_observation','단서 찾기','버스를 타기 전에 중요한 단서를 골라보세요.','{"question": "\uc13c\ud130\uc5d0 \uac00\ub824\uba74 \ubb34\uc5c7\uc744 \uba3c\uc800 \ud655\uc778\ud558\uba74 \uc88b\uc744\uae4c\uc694?", "imageAssetId": "asset_content_bus_001_stage_2", "audioAssetId": "asset_content_bus_001_stage_2_audio", "choices": [{"id": "a", "text": "\ubc84\uc2a4 \ubc88\ud638"}, {"id": "b", "text": "\ud558\ub298 \uc0c9"}], "answer": "a", "correctFeedback": "\uc88b\uc544\uc694. \ubc84\uc2a4 \ubc88\ud638\ub97c \uba3c\uc800 \ud655\uc778\ud574\uc694.", "wrongFeedback": "\uc13c\ud130\ub85c \uac00\ub294 \ubc84\uc2a4\uc778\uc9c0 \uc54c\ub824\uc8fc\ub294 \ub2e8\uc11c\ub97c \ucc3e\uc544\ubcfc\uae4c\uc694?", "assetBundle": {"imageAssetId": "asset_content_bus_001_stage_2", "audioAssetId": "asset_content_bus_001_stage_2_audio"}}','null',2);
INSERT INTO content_stages VALUES('stage_bus_3','content_bus_001',3,'action_selection','sequence_ordering','행동 고르기','센터에 가는 순서를 차례대로 골라보세요.','{"question": "\uc13c\ud130\uc5d0 \uac00\ub294 \uc21c\uc11c\ub97c \ub9de\ucdb0\ubcf4\uc138\uc694.", "imageAssetId": "asset_content_bus_001_stage_3", "audioAssetId": "asset_content_bus_001_stage_3_audio", "cards": [{"id": "check_bus", "text": "\ubc84\uc2a4 \ubc88\ud638 \ud655\uc778"}, {"id": "take_bus", "text": "\ubc84\uc2a4 \ud0c0\uae30"}], "answerOrder": ["check_bus", "take_bus"], "correctFeedback": "\uc88b\uc544\uc694. \uba3c\uc800 \ud655\uc778\ud558\uace0, \uadf8\ub2e4\uc74c \ubc84\uc2a4\ub97c \ud0c0\uc694.", "wrongFeedback": "\ubc84\uc2a4\ub97c \ud0c0\uae30 \uc804\uc5d0 \ud655\uc778\ud574\uc57c \ud560 \uc77c\uc744 \uc55e\uc73c\ub85c \uc62e\uaca8\ubcfc\uae4c\uc694?", "assetBundle": {"imageAssetId": "asset_content_bus_001_stage_3", "audioAssetId": "asset_content_bus_001_stage_3_audio"}}','null',3);
INSERT INTO content_stages VALUES('stage_bus_4','content_bus_001',4,'realtime_practice','realtime_roleplay','한 번 해보기','AI 안내 직원에게 센터 가는 길을 물어보세요.','{"imageAssetId": "asset_content_bus_001_stage_4_realtime", "audioAssetId": "asset_content_bus_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_bus_001_stage_4_realtime", "audioAssetId": "asset_content_bus_001_stage_4_realtime_audio"}}','{"id": "rt_spec_bus_001", "stageId": "stage_bus_4", "templateType": "realtime_roleplay", "imageAssetId": "asset_content_bus_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc815\ub958\uc7a5\uc5d0\uc11c \ub3c4\uc6c0 \uc694\uccad\ud558\uae30", "situationText": "\ud559\uc0dd\uc774 \uc13c\ud130\uc5d0 \uac00\ub824\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \uc548\ub0b4 \uc9c1\uc6d0\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud569\ub2c8\ub2e4.", "aiRole": "\uc815\ub958\uc7a5 \uc548\ub0b4 \uc9c1\uc6d0", "openingLine": "\uc5b4\ub514\ub85c \uac00\ub824\uace0 \ud558\ub098\uc694? \uc81c\uac00 \ub3c4\uc640\uc904\uac8c\uc694.", "studentGoal": "\uc13c\ud130\uc5d0 \uac00\uc57c \ud55c\ub2e4\uace0 \ub9d0\ud558\uace0 \uc5b4\ub5a4 \ubc84\uc2a4\ub97c \ud0c0\uc57c \ud558\ub294\uc9c0 \ub3c4\uc6c0 \uc694\uccad\ud558\uae30", "rubric": [{"id": "state_destination", "label": "\ubaa9\uc801\uc9c0\ub97c \ub9d0\ud55c\ub2e4", "required": true}, {"id": "ask_help", "label": "\ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4", "required": true}, {"id": "confirm_next_action", "label": "\ub2e4\uc74c \ud589\ub3d9\uc744 \ud655\uc778\ud55c\ub2e4", "required": true}], "allowedFeedback": ["\uc88b\uc544\uc694. \uc5b4\ub514\ub85c \uac00\ub294\uc9c0 \ub9d0\ud588\uc5b4\uc694.", "\uc5b4\ub5a4 \ub3c4\uc6c0\uc744 \ubc1b\uace0 \uc2f6\uc740\uc9c0\ub3c4 \ub9d0\ud574\ubcfc\uae4c\uc694?"], "forbidden": ["\uc0c8\ub85c\uc6b4 \uc774\ub3d9 \ubb38\uc81c \ub9cc\ub4e4\uc9c0 \uc54a\uae30", "\ud559\uc0dd \uac1c\uc778\uc815\ubcf4 \ubb3b\uc9c0 \uc54a\uae30", "\ubd88\uc548\uac10\uc744 \ud0a4\uc6b0\ub294 \ud45c\ud604 \uae08\uc9c0"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\ud560 \uc218 \uc788\uc744 \uac83 \uac19\uc544\uc694", "\uc870\uae08 \ub5a8\ub824\uc694", "\ub2e4\uc2dc \uc5f0\uc2b5\ud558\uace0 \uc2f6\uc5b4\uc694"]}',4);
INSERT INTO content_stages VALUES('stage_bus_to_center_001_1','content_bus_to_center_001',1,'concept_intro','concept_intro','개념 열기','그림을 보면서 오늘 어떤 길로 가는지 생각해 봅시다.','{"imageAssetId": "asset_content_bus_to_center_001_stage_1", "audioAssetId": "asset_content_bus_to_center_001_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_1", "audioAssetId": "asset_content_bus_to_center_001_stage_1_audio"}, "storyText": "\uc9c0\uc6b0\uac00 \uc13c\ud130\uc5d0 \uac00\ub824\uace0 \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uace0 \uc788\uc5b4\uc694.", "missionText": "\uc624\ub298\uc740 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uc13c\ud130\uc5d0 \uac00\ub294 \uae38\uacfc \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \ud568\uaed8 \uc5f0\uc2b5\ud574 \ubd05\uc2dc\ub2e4."}','null',1);
INSERT INTO content_stages VALUES('stage_bus_to_center_001_2','content_bus_to_center_001',2,'basic_problem','scene_question','문제 1','두 그림을 보고, 지금 지우가 있는 곳을 골라 봅시다.','{"imageAssetId": "asset_content_bus_to_center_001_stage_2", "audioAssetId": "asset_content_bus_to_center_001_stage_2_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_2", "audioAssetId": "asset_content_bus_to_center_001_stage_2_audio"}, "question": "\uc9c0\uc6b0\uc640 \ub9c8\uc2a4\ucf54\ud2b8\uac00 \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\ub294 \uacf3\uc740 \uc5b4\ub290 \ucabd \uadf8\ub9bc\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "\ubc84\uc2a4 \uc815\ub958\uc7a5"}, {"id": "b", "text": "\uc9d1 \uc548\uc774\ub098 \uad50\uc2e4"}], "answer": "a", "correctFeedback": "\ub9de\uc544\uc694. \ubc84\uc2a4 \uc815\ub958\uc7a5\uc5d0\uc11c \uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \uae30\ub2e4\ub9ac\uace0 \uc788\uc5b4\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \ubcf4\uc544\uc694. \ubc84\uc2a4 \ud45c\uc9c0\ud310\uc774 \ubcf4\uc774\ub294 \uacf3\uc744 \uace8\ub77c \ubd05\uc2dc\ub2e4."}','null',2);
INSERT INTO content_stages VALUES('stage_bus_to_center_001_3','content_bus_to_center_001',3,'applied_problem','sequence_ordering','문제 2','버스를 탈 때 먼저 할 일과 그다음 할 일을 순서대로 골라 봅시다.','{"imageAssetId": "asset_content_bus_to_center_001_stage_3", "audioAssetId": "asset_content_bus_to_center_001_stage_3_audio", "question": "\ubc84\uc2a4\ub97c \ud0c8 \ub54c \uc5b4\ub5a4 \uc77c\uc744 \uba3c\uc800 \ud558\uace0, \uadf8\ub2e4\uc74c\uc5d0 \ubb34\uc5c7\uc744 \ud558\uba74 \uc88b\uc744\uae4c\uc694?", "cards": [{"id": "wait", "text": "\uc815\ub958\uc7a5\uc5d0\uc11c \ubc14\ub974\uac8c \uc11c\uc11c \uae30\ub2e4\ub9ac\uae30"}, {"id": "ride", "text": "\ubc84\uc2a4 \ubb38\uc774 \uc5f4\ub9ac\uba74 \ucc28\ubd84\ud788 \ud0c0\uae30"}], "answerOrder": ["wait", "ride"], "correctFeedback": "\uc88b\uc544\uc694. \uba3c\uc800 \uc815\ub958\uc7a5\uc5d0\uc11c \uae30\ub2e4\ub9ac\uace0, \uadf8\ub2e4\uc74c\uc5d0 \ucc28\ubd84\ud788 \ubc84\uc2a4\ub97c \ud0c0\uba74 \ub3fc\uc694.", "wrongFeedback": "\uc815\ub958\uc7a5\uc5d0\uc11c \uba3c\uc800 \uae30\ub2e4\ub9ac\ub294 \uc7a5\uba74\uc774 \uc55e\uc5d0 \uc624\ub3c4\ub85d \ub2e4\uc2dc \uace8\ub77c \ubd05\uc2dc\ub2e4.", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_3", "audioAssetId": "asset_content_bus_to_center_001_stage_3_audio"}}','null',3);
INSERT INTO content_stages VALUES('stage_bus_to_center_001_4','content_bus_to_center_001',4,'realtime_practice','realtime_teach_back','설명해보기','버스 안 그림을 보면서 길이 헷갈릴 때 짧게 도움을 부탁하는 말을 직접 해 봅시다.','{"imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "audioAssetId": "asset_content_bus_to_center_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "audioAssetId": "asset_content_bus_to_center_001_stage_4_realtime_audio"}}','{"id": "rt_spec_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0 \uc5f0\uc2b5\ud558\uae30", "situationText": "\uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uac00\ub294 \uae38\uc5d0 \uc870\uae08 \ud5f7\uac08\ub824\uc11c, \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uaed8 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ubb3c\uc5b4\ubcf4\ub824\uace0 \ud574\uc694.", "aiRole": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uc9c0\uc6b0 \uacc1\uc5d0 \uc788\ub294 \uce5c\uc808\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce5c\uad6c", "openingLine": "\uc9c0\uc6b0\uc57c, \uae38\uc774 \uc870\uae08 \ud5f7\uac08\ub9ac\uba74 \uc5b4\ub5bb\uac8c \ub9d0\ud574 \ubcfc\uae4c?", "studentGoal": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ud5f7\uac08\ub9b4 \ub54c \"\ub3c4\uc640\uc8fc\uc138\uc694.\", \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\" \uac19\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud574 \ubcf4\uae30", "rubric": [{"id": "say_help", "label": "\ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\ub3c4\uc640\uc8fc\uc138\uc694.\")", "required": true}, {"id": "ask_where_get_off", "label": "\ub0b4\ub9ac\ub294 \uacf3\uc744 \ubb3c\uc5b4\ubcf4\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\")", "required": false}], "allowedFeedback": ["\uc88b\uc544\uc694. \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \uc798 \ud588\uc5b4\uc694.", "\uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0\ub3c4 \uc9e7\uac8c \ubb3c\uc5b4\ubcfc \uc218\ub3c4 \uc788\uc5b4\uc694.", "\ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub9d0\ud574\ub3c4 \uad1c\ucc2e\uc544\uc694. \ud55c \ubb38\uc7a5\ub9cc \ud574\ub3c4 \uc88b\uc544\uc694."], "forbidden": ["\uc9c4\ub2e8\uba85\uc774\ub098 \uac80\uc0ac \uacb0\uacfc\ub97c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uae30", "\uc9d1 \uc8fc\uc18c, \uc804\ud654\ubc88\ud638 \uac19\uc740 \uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\ub9d0\ud574 \ubcf4\ub2c8 \uad1c\ucc2e\uc558\uc5b4\uc694.", "\uc870\uae08 \uc5b4\ub835\uc9c0\ub9cc \ud574 \ubcfc \ub9cc \ud588\uc5b4\uc694.", "\ub098\uc911\uc5d0 \ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud574 \ubcf4\uace0 \uc2f6\uc5b4\uc694."]}',4);
INSERT INTO content_stages VALUES('stage_clock_1','content_clock_001',1,'concept_intro','concept_intro','개념 열기','시침과 분침이 어디에 있는지 보세요.','{"imageAssetId": "asset_content_clock_001_stage_1", "audioAssetId": "asset_content_clock_001_stage_1_audio", "storyText": "\uc9c0\uc6b0\uac00 \uc57d\uc18d \uc2dc\uac04\uc5d0 \ub9de\ucdb0 \uc900\ube44\ud558\ub824\uace0 \uc2dc\uacc4\ub97c \ubcf4\uace0 \uc788\uc5b4\uc694.", "missionText": "\uba3c\uc800 \uc9e7\uc740 \ubc14\ub298\uacfc \uae34 \ubc14\ub298\uc744 \ucc3e\uc544\ubd05\uc2dc\ub2e4.", "assetBundle": {"imageAssetId": "asset_content_clock_001_stage_1", "audioAssetId": "asset_content_clock_001_stage_1_audio"}}','null',1);
INSERT INTO content_stages VALUES('stage_clock_2','content_clock_001',2,'basic_problem','scene_question','문제 1','짧은 바늘이 가리키는 숫자를 고르세요.','{"imageAssetId": "asset_content_clock_001_stage_2", "audioAssetId": "asset_content_clock_001_stage_2_audio", "question": "\uc9e7\uc740 \ubc14\ub298\uc740 \uc5b4\ub290 \uc22b\uc790\ub97c \uac00\ub9ac\ud0a4\ub098\uc694?", "choices": [{"id": "a", "text": "3"}, {"id": "b", "text": "6"}], "answer": "a", "correctFeedback": "\ub9de\uc544\uc694. \uc9e7\uc740 \ubc14\ub298\uc774 3\uc744 \uac00\ub9ac\ud0a4\uace0 \uc788\uc5b4\uc694.", "wrongFeedback": "\uc9e7\uc740 \ubc14\ub298\uc744 \uba3c\uc800 \ucc3e\uc544\ubd05\uc2dc\ub2e4.", "assetBundle": {"imageAssetId": "asset_content_clock_001_stage_2", "audioAssetId": "asset_content_clock_001_stage_2_audio"}}','null',2);
INSERT INTO content_stages VALUES('stage_clock_3','content_clock_001',3,'applied_problem','sequence_ordering','문제 2','시계를 읽는 순서를 고르세요.','{"imageAssetId": "asset_content_clock_001_stage_3", "audioAssetId": "asset_content_clock_001_stage_3_audio", "question": "\uc2dc\uacc4\ub97c \uc77d\uc744 \ub54c \ubb34\uc5c7\uc744 \uba3c\uc800 \ubcf4\uba74 \uc88b\uc744\uae4c\uc694?", "cards": [{"id": "hour", "text": "\uc9e7\uc740 \ubc14\ub298 \ubcf4\uae30"}, {"id": "minute", "text": "\uae34 \ubc14\ub298 \ubcf4\uae30"}], "answerOrder": ["hour", "minute"], "correctFeedback": "\uc88b\uc544\uc694. \uc9e7\uc740 \ubc14\ub298, \uae34 \ubc14\ub298 \uc21c\uc11c\ub85c \ubcf4\uba74 \ub418\uc5b4\uc694.", "wrongFeedback": "\uc9e7\uc740 \ubc14\ub298\uc744 \uba3c\uc800 \ubcf4\ub294 \ud750\ub984\uc73c\ub85c \ub2e4\uc2dc \uace0\ub974\uc138\uc694.", "assetBundle": {"imageAssetId": "asset_content_clock_001_stage_3", "audioAssetId": "asset_content_clock_001_stage_3_audio"}}','null',3);
INSERT INTO content_stages VALUES('stage_clock_4','content_clock_001',4,'realtime_practice','realtime_teach_back','설명해보기','별이에게 시계를 읽는 방법을 말해봅시다.','{"imageAssetId": "asset_content_clock_001_stage_4_realtime", "audioAssetId": "asset_content_clock_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_clock_001_stage_4_realtime", "audioAssetId": "asset_content_clock_001_stage_4_realtime_audio"}}','{"id": "rt_spec_clock_001", "stageId": "stage_clock_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_clock_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc2dc\uacc4 \uc77d\ub294 \ubc29\ubc95 \uc124\uba85\ud558\uae30", "situationText": "\ubcc4\uc774\uac00 \uc2dc\uacc4 \uadf8\ub9bc\uc744 \ubcf4\uace0 \uba3c\uc800 \ubb34\uc5c7\uc744 \ubd10\uc57c \ud558\ub294\uc9c0 \ubb3c\uc5b4\ubd05\ub2c8\ub2e4.", "aiRole": "\uc2dc\uacc4\ub97c \ubc30\uc6b0\ub294 \uce5c\uad6c", "openingLine": "\uc2dc\uacc4\ub97c \uc77d\uc744 \ub54c \uc5b4\ub5a4 \ubc14\ub298\uc744 \uba3c\uc800 \ubcf4\uba74 \ub418\uc5b4?", "studentGoal": "\uc9e7\uc740 \ubc14\ub298\uc744 \uba3c\uc800 \ubcf4\uace0 \uae34 \ubc14\ub298\uc744 \ubcf8\ub2e4\uace0 \uc124\uba85\ud558\uae30", "rubric": [{"id": "mention_hour_hand", "label": "\uc9e7\uc740 \ubc14\ub298\uc744 \uba3c\uc800 \ubcf8\ub2e4", "required": true}, {"id": "mention_minute_hand", "label": "\uae34 \ubc14\ub298\uc744 \ub2e4\uc74c\uc5d0 \ubcf8\ub2e4", "required": true}], "allowedFeedback": ["\uc88b\uc544\uc694. \uba3c\uc800 \ubcfc \ubc14\ub298\uc744 \ub9d0\ud588\uc5b4\uc694.", "\uc774\uc81c \uae34 \ubc14\ub298\uae4c\uc9c0 \uc774\uc5b4\uc11c \ub9d0\ud574\ubd05\uc2dc\ub2e4."], "forbidden": ["\uc9c4\ub2e8\uba85 \uc5b8\uae09 \uae08\uc9c0", "\uac1c\uc778\uc815\ubcf4 \ubb3b\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\uc26c\uc6e0\uc5b4\uc694", "\uc870\uae08 \ud5f7\uac08\ub838\uc5b4\uc694", "\ub2e4\uc2dc \uc5f0\uc2b5\ud558\uace0 \uc2f6\uc5b4\uc694"]}',4);
INSERT INTO content_stages VALUES('stage_fraction_1','content_fraction_001',1,'concept_intro','concept_intro','개념 열기','피자 지도를 보며 전체와 부분을 확인해요.','{"imageAssetId": "asset_content_fraction_001_stage_1", "audioAssetId": "asset_content_fraction_001_stage_1_audio", "storyText": "\ud53c\uc790 \ud55c \ud310\uc774 \uac19\uc740 \ud06c\uae30 4\uc870\uac01\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\uc5b4\uc694.", "missionText": "\ube5b\ub098\ub294 \uc870\uac01\uc774 \uc804\uccb4 \uc911 \uc5bc\ub9c8\uc778\uc9c0 \ucc3e\uc544\ubd10\uc694.", "assetBundle": {"imageAssetId": "asset_content_fraction_001_stage_1", "audioAssetId": "asset_content_fraction_001_stage_1_audio"}}','null',1);
INSERT INTO content_stages VALUES('stage_fraction_2','content_fraction_001',2,'basic_problem','partition_picker','문제 1','전체 조각 수와 고른 조각 수를 차례대로 세어보세요.','{"imageAssetId": "asset_content_fraction_001_stage_2", "audioAssetId": "asset_content_fraction_001_stage_2_audio", "question": "\uc804\uccb4\ub294 \uba87 \uc870\uac01\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "1\uc870\uac01"}, {"id": "b", "text": "4\uc870\uac01"}, {"id": "c", "text": "2\uc870\uac01"}], "answer": "b", "correctFeedback": "\ub9de\uc544\uc694. \uc804\uccb4\ub294 4\uc870\uac01\uc774\uc5d0\uc694.", "wrongFeedback": "\ud53c\uc790 \ud55c \ud310\uc774 \uba87 \uce78\uc73c\ub85c \ub098\ub258\uc5c8\ub294\uc9c0 \ub2e4\uc2dc \uc138\uc5b4\ubcfc\uae4c\uc694?", "assetBundle": {"imageAssetId": "asset_content_fraction_001_stage_2", "audioAssetId": "asset_content_fraction_001_stage_2_audio"}}','null',2);
INSERT INTO content_stages VALUES('stage_fraction_3','content_fraction_001',3,'applied_problem','blank_fill','문제 2','고른 조각 수와 전체 조각 수를 분수 자리에 넣어보세요.','{"imageAssetId": "asset_content_fraction_001_stage_3", "audioAssetId": "asset_content_fraction_001_stage_3_audio", "question": "\uc804\uccb4 4\uac1c \uc911 1\uac1c\ub294 __ / __ \uc774\uc5d0\uc694.", "acceptedAnswers": [{"numerator": "1", "denominator": "4"}], "correctFeedback": "\uc88b\uc544\uc694. \uc704\uc5d0\ub294 \uace0\ub978 \uac83 1, \uc544\ub798\uc5d0\ub294 \uc804\uccb4 4\uac00 \uc640\uc694.", "wrongFeedback": "\uc704\uc5d0\ub294 \uace0\ub978 \uc870\uac01 \uc218, \uc544\ub798\uc5d0\ub294 \uc804\uccb4 \uc870\uac01 \uc218\ub97c \ub123\uc5b4\uc694.", "assetBundle": {"imageAssetId": "asset_content_fraction_001_stage_3", "audioAssetId": "asset_content_fraction_001_stage_3_audio"}}','null',3);
INSERT INTO content_stages VALUES('stage_fraction_4','content_fraction_001',4,'realtime_practice','realtime_teach_back','설명해보기','별이에게 왜 1/4인지 말로 설명해보세요.','{"imageAssetId": "asset_content_fraction_001_stage_4_realtime", "audioAssetId": "asset_content_fraction_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_fraction_001_stage_4_realtime", "audioAssetId": "asset_content_fraction_001_stage_4_realtime_audio"}}','{"id": "rt_spec_fraction_001", "stageId": "stage_fraction_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_fraction_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ubcc4\uc774\uc5d0\uac8c \ubd84\uc218 \uc124\uba85\ud558\uae30", "situationText": "\ubcc4\uc774\uac00 \ube5b\ub098\ub294 \ud53c\uc790 \uc870\uac01\uc744 \ubcf4\uace0 \uc65c 1/4\uc778\uc9c0 \uad81\uae08\ud574\ud574\uc694.", "aiRole": "\ubcc4\uc774", "openingLine": "\uc65c 4/1\uc774 \uc544\ub2c8\ub77c 1/4\uc778\uc9c0 \uc54c\ub824\uc904\ub798?", "studentGoal": "\uc804\uccb4 4\uac1c \uc911 \uace0\ub978 \uac83\uc774 1\uac1c\ub77c\uc11c 1/4\uc774\ub77c\uace0 \uc124\uba85\ud558\uae30", "rubric": [{"id": "mention_whole", "label": "\uc804\uccb4\uac00 4\uac1c\uc784\uc744 \ub9d0\ud55c\ub2e4", "required": true}, {"id": "mention_part", "label": "\uace0\ub978 \uac83\uc774 1\uac1c\uc784\uc744 \ub9d0\ud55c\ub2e4", "required": true}, {"id": "connect_fraction", "label": "1/4\ub85c \uc5f0\uacb0\ud55c\ub2e4", "required": true}], "allowedFeedback": ["\uc88b\uc544\uc694. \uc804\uccb4\uac00 \uba87 \uac1c\uc778\uc9c0 \ub9d0\ud588\uc5b4\uc694.", "\uace0\ub978 \uac83\uc774 \uba87 \uac1c\uc778\uc9c0\ub3c4 \ub9d0\ud574\ubcfc\uae4c\uc694?", "\uc774\uc81c 1/4\uc774\ub77c\ub294 \ud45c\ud604\uae4c\uc9c0 \uc774\uc5b4\uc11c \ub9d0\ud574\ubd10\uc694."], "forbidden": ["\uc0c8 \ubb38\uc81c\ub97c \ub9cc\ub4e4\uc9c0 \uc54a\uae30", "\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8 \ub77c\ubca8 \ub9d0\ud558\uc9c0 \uc54a\uae30", "\uac1c\uc778\uc815\ubcf4 \uc5b8\uae09\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\uc26c\uc6e0\uc5b4\uc694", "\uc870\uae08 \ud5f7\uac08\ub838\uc5b4\uc694", "\ub2e4\uc2dc \uc5f0\uc2b5\ud558\uace0 \uc2f6\uc5b4\uc694"]}',4);
INSERT INTO content_stages VALUES('stage_content_generated_001_1','content_generated_001',1,'scenario_intro','scenario_intro','상황 만나기','도서관에서 찾아야 할 책을 천천히 확인해 보세요.','{"imageAssetId": "asset_content_generated_001_stage_1", "audioAssetId": "asset_content_generated_001_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_generated_001_stage_1", "audioAssetId": "asset_content_generated_001_stage_1_audio"}, "storyText": "\ub3c4\uc11c\uad00\uc5d0 \uc654\uc5b4\uc694. \uc624\ub298 \ucc3e\uc744 \ucc45\uc740 \ud30c\ub780 \ud45c\uc9c0\uc758 \ub3d9\ubb3c\ucc45\uc774\uc5d0\uc694.", "missionText": "\ucc45\uc7a5 \uc55e\uc5d0\uc11c \ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc744 \ucc3e\uc544\ubcf4\uace0, \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc73c\uba74 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uaed8 \ubb3c\uc5b4\ubd10\uc694."}','null',1);
INSERT INTO content_stages VALUES('stage_content_generated_001_2','content_generated_001',2,'clue_identification','scene_observation','단서 찾기','찾아야 할 책의 단서를 골라보세요.','{"imageAssetId": "asset_content_generated_001_stage_2", "audioAssetId": "asset_content_generated_001_stage_2_audio", "assetBundle": {"imageAssetId": "asset_content_generated_001_stage_2", "audioAssetId": "asset_content_generated_001_stage_2_audio"}, "question": "\ucc3e\uc544\uc57c \ud560 \ub3d9\ubb3c\ucc45\uc758 \ud45c\uc9c0\ub294 \uc5b4\ub5a4 \uc0c9\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "\ud30c\ub780 \ud45c\uc9c0"}, {"id": "b", "text": "\ube68\uac04 \ud45c\uc9c0"}], "answer": "a", "correctFeedback": "\uc88b\uc544\uc694. \ud30c\ub780 \ud45c\uc9c0\ub97c \uba3c\uc800 \ubcf4\uba74 \ucc3e\uae30 \uc26c\uc6cc\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \ucc45 \ub2e8\uc11c\ub97c \ub5a0\uc62c\ub824\ubcfc\uae4c\uc694? \uc624\ub298 \ucc3e\uc744 \ucc45\uc740 \ud30c\ub780 \ud45c\uc9c0\uc608\uc694."}','null',2);
INSERT INTO content_stages VALUES('stage_content_generated_001_3','content_generated_001',3,'action_selection','sequence_ordering','행동 고르기','책을 찾는 순서를 차례대로 놓아보세요.','{"imageAssetId": "asset_content_generated_001_stage_3", "audioAssetId": "asset_content_generated_001_stage_3_audio", "question": "\ud30c\ub780 \ub3d9\ubb3c\ucc45\uc744 \ucc3e\ub2e4\uac00 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc744 \ub54c, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \ud558\uba74 \uc88b\uc744\uae4c\uc694?", "cards": [{"id": "check_clue", "text": "\ud30c\ub780 \ud45c\uc9c0 \uae30\uc5b5\ud558\uae30"}, {"id": "look_shelf", "text": "\ucc45\uc7a5 \uc0b4\ud3b4\ubcf4\uae30"}, {"id": "ask_librarian", "text": "\uc0ac\uc11c \uc120\uc0dd\ub2d8\uaed8 \ubb3b\uae30"}], "answerOrder": ["check_clue", "look_shelf", "ask_librarian"], "correctFeedback": "\uc88b\uc544\uc694. \ub2e8\uc11c\ub97c \uae30\uc5b5\ud558\uace0, \ucc45\uc7a5\uc744 \ubcf8 \ub4a4, \ud544\uc694\ud558\uba74 \ubb3c\uc5b4\ubcf4\uba74 \ub3fc\uc694.", "wrongFeedback": "\uba3c\uc800 \ucc3e\uc744 \ucc45\uc758 \ub2e8\uc11c\ub97c \ub5a0\uc62c\ub9ac\uace0, \uadf8\ub2e4\uc74c \ucc45\uc7a5\uc744 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uc544\uc694.", "assetBundle": {"imageAssetId": "asset_content_generated_001_stage_3", "audioAssetId": "asset_content_generated_001_stage_3_audio"}}','null',3);
INSERT INTO content_stages VALUES('stage_content_generated_001_4','content_generated_001',4,'realtime_practice','realtime_roleplay','한 번 해보기','사서 선생님에게 찾는 책의 단서를 말하고 도움을 요청해 보세요.','{"imageAssetId": "asset_content_generated_001_stage_4_realtime", "audioAssetId": "asset_content_generated_001_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_generated_001_stage_4_realtime", "audioAssetId": "asset_content_generated_001_stage_4_realtime_audio"}}','{"id": "rt_spec_content_generated_001_4", "stageId": "stage_content_generated_001_4", "templateType": "realtime_roleplay", "imageAssetId": "asset_content_generated_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\uc0ac\uc11c \uc120\uc0dd\ub2d8\uaed8 \ucc45 \ubb3c\uc5b4\ubcf4\uae30", "situationText": "\ud559\uc0dd\uc774 \ub3c4\uc11c\uad00\uc5d0\uc11c \ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc744 \ucc3e\ub2e4\uac00 \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ub3c4\uc6c0\uc744 \uc694\uccad\ud569\ub2c8\ub2e4.", "aiRole": "\uc0ac\uc11c \uc120\uc0dd\ub2d8", "openingLine": "\uc548\ub155\ud558\uc138\uc694. \uc5b4\ub5a4 \ucc45\uc744 \ucc3e\uace0 \uc788\ub098\uc694? \uc81c\uac00 \ub3c4\uc640\uc904\uac8c\uc694.", "studentGoal": "\ud30c\ub780 \ud45c\uc9c0 \ub3d9\ubb3c\ucc45\uc744 \ucc3e\uace0 \uc788\ub2e4\uace0 \ub9d0\ud558\uace0, \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \uc9e7\uac8c \ubb3c\uc5b4\ubd05\ub2c8\ub2e4.", "rubric": [{"id": "try_saying", "label": "\uc9e7\uac8c\ub77c\ub3c4 \ub9d0\ud574\ubcf8\ub2e4", "required": true}, {"id": "say_clue", "label": "\ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \ub9d0\ud55c\ub2e4", "required": false}, {"id": "ask_help", "label": "\uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ub3c4\uc6c0\uc744 \uc694\uccad\ud55c\ub2e4", "required": false}, {"id": "listen_next", "label": "\ub2e4\uc74c\uc5d0 \uac08 \uacf3\uc744 \ub4e4\uc5b4\ubcf8\ub2e4", "required": false}], "allowedFeedback": ["\uc88b\uc544\uc694. \ucc3e\ub294 \ucc45\uc744 \ub9d0\ud574\ubcf4\ub824\ub294 \uc2dc\ub3c4\uac00 \uc88b\uc558\uc5b4\uc694.", "\uc9e7\uac8c \ub9d0\ud574\ub3c4 \uad1c\ucc2e\uc544\uc694. \ud30c\ub780 \ub3d9\ubb3c\ucc45\uc774\ub77c\uace0 \ud55c \ubc88 \ub354 \ub9d0\ud574\ubcfc\uae4c\uc694?", "\uc798\ud588\uc5b4\uc694. \uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0 \ubb3c\uc5b4\ubcf4\ub294 \ub9d0\ub3c4 \ubd99\uc5ec\ubcfc\uae4c\uc694?", "\uad1c\ucc2e\uc544\uc694. \uc0ac\uc11c \uc120\uc0dd\ub2d8\uc774 \ub3c4\uc640\uc904 \uc218 \uc788\uc5b4\uc694. \ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub9d0\ud574\ubcfc\uae4c\uc694?"], "forbidden": ["\ud559\uc0dd \uac1c\uc778\uc815\ubcf4 \ubb3b\uc9c0 \uc54a\uae30", "\uc2e4\uc81c \ub3c4\uc11c\uad00 \uc704\uce58 \ubb3b\uc9c0 \uc54a\uae30", "\ucc45\uc744 \ubabb \ucc3e\ub294 \uc0c1\ud669\uc744 \ubd80\uc815\uc801\uc73c\ub85c \ub9d0\ud558\uc9c0 \uc54a\uae30", "\uae34 \ubb38\uc7a5\uc744 \ud55c \ubc88\uc5d0 \uc694\uad6c\ud558\uc9c0 \uc54a\uae30", "\uc815\ud574\uc9c4 \ub0b1\ub9d0\uc744 \ub9d0\ud558\uc9c0 \ubabb\ud588\ub2e4\uace0 \uac70\uc808\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\uc9e7\uac8c \ub9d0\ud574\ubd24\uc5b4\uc694", "\ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud558\uace0 \uc2f6\uc5b4\uc694"]}',4);
INSERT INTO content_stages VALUES('stage_learning_fraction_store_discount_1','content_learning_fraction_store_discount',1,'concept_intro','concept_intro','개념 열기','학교 매점 그림을 보며 ‘원래 가격 → 할인 금액 → 낼 돈’ 순서를 먼저 살펴봐요.','{"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_1", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_1_audio"}, "storyText": "\ud559\uad50 \ub9e4\uc810 \uc9c4\uc5f4\ub300\uc5d0 \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \ub193\uc5ec \uc788\uace0, \uac00\uaca9\ud45c \uc606\uc5d0 \ud560\uc778 \ud45c\uc2dc\uac00 \ubd99\uc5b4 \uc788\uc5b4\uc694. \ud55c \ud559\uc0dd\uc774 \uac00\uaca9\ud45c\ub97c \uc190\uac00\ub77d\uc73c\ub85c \uc9da\uc5b4 \ubcf4\uba70 \uc5bc\ub9c8\ub098 \ub0b4\uc57c \ud560\uc9c0 \uc0dd\uac01\ud558\uace0 \uc788\uc5b4\uc694.", "missionText": "\uc774\uc81c \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0b4 \ub54c, \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub2e4\uc74c, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \ucc28\ub840\ub300\ub85c \uc0b4\ud3b4\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcfc \uac70\uc608\uc694."}','null',1);
INSERT INTO content_stages VALUES('stage_learning_fraction_store_discount_2','content_learning_fraction_store_discount',2,'basic_problem','sequence_ordering','문제 1','한 물건에 대해 ‘원래 가격 → 할인 금액 → 낼 돈’에 맞게 카드 3장을 알맞은 순서로 놓아 보세요.','{"imageAssetId": "asset_content_learning_fraction_store_discount_stage_2", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_2_audio", "question": "\ucf5c\ub77c \ud55c \ubcd1\uc744 \uc0b4 \ub54c, \uc5b4\ub5a4 \uc21c\uc11c\ub85c \uac00\uaca9\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc774 \uc88b\uc744\uae4c\uc694? \uc54c\ub9de\uc740 \uc21c\uc11c\ub85c \uce74\ub4dc 3\uc7a5\uc744 \ubc30\uc5f4\ud574 \ubcf4\uc138\uc694.", "cards": [{"id": "card_original", "text": "\uc6d0\ub798 \uac00\uaca9\uc744 \ubcf8\ub2e4."}, {"id": "card_discount", "text": "\ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc774 \uc5bc\ub9c8\uc778\uc9c0 \ubcf8\ub2e4."}, {"id": "card_pay", "text": "\ud560\uc778\ub41c \ub4a4\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud55c\ub2e4."}], "answerOrder": ["card_original", "card_discount", "card_pay"], "correctFeedback": "\uc798\ud588\uc5b4\uc694! \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561\uc744 \ud655\uc778\ud55c \ub4a4, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\uba74 \ub3fc\uc694.", "wrongFeedback": "\ub2e4\uc2dc \ud55c \ubc88 \uc0dd\uac01\ud574\ubcfc\uae4c\uc694? \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \ubcf4\uace0, \uadf8\ub2e4\uc74c \uc5bc\ub9c8\ub098 \uae4e\uc774\ub294\uc9c0 \ubcf4\uace0, \ub9c8\uc9c0\ub9c9\uc5d0 \ub0bc \ub3c8\uc744 \uacc4\uc0b0\ud558\ub294 \uc21c\uc11c\uac00 \ub418\ub3c4\ub85d \ubc14\uafd4\ubcf4\uc138\uc694.", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_2", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_2_audio"}}','null',2);
INSERT INTO content_stages VALUES('stage_learning_fraction_store_discount_3','content_learning_fraction_store_discount',3,'applied_problem','applied_question','문제 2','분수로 표시된 할인 금액을 보고 얼마나 줄어드는지 계산한 뒤, 보기에서 내가 내야 할 돈을 골라보세요.','{"imageAssetId": "asset_content_learning_fraction_store_discount_stage_3", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_3_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_3", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_3_audio"}, "question": "\ub9e4\uc810\uc5d0\uc11c \uac00\uaca9\uc774 3,000\uc6d0\uc778 \uc0cc\ub4dc\uc704\uce58\uc5d0 \uc624\ub298\uc740 \uac00\uaca9\uc758 1/3\ub9cc\ud07c\uc744 \uae4e\uc544 \uc900\ub2e4\uace0 \ud574\uc694. \uc0cc\ub4dc\uc704\uce58\ub97c \uc0b4 \ub54c, \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc740 \uc5bc\ub9c8\uc778\uac00\uc694?", "choices": [{"id": "a", "text": "1,000\uc6d0"}, {"id": "b", "text": "2,000\uc6d0"}, {"id": "c", "text": "3,000\uc6d0"}], "answer": "b", "correctFeedback": "\ub9de\uc544\uc694! 3,000\uc6d0\uc758 1/3\uc740 1,000\uc6d0\uc774 \uc904\uc5b4\ub4dc\ub294 \uac70\uc608\uc694. \uadf8\ub798\uc11c 3,000\uc6d0 \u2212 1,000\uc6d0 = 2,000\uc6d0\uc774 \ub418\uc5b4, 2,000\uc6d0\uc744 \ub0b4\uba74 \ub3fc\uc694.", "wrongFeedback": "\uc870\uae08 \ub354 \ucc28\uadfc\ucc28\uadfc \uc0dd\uac01\ud574\ubcfc\uae4c\uc694? \uba3c\uc800 3,000\uc6d0\uc758 1/3\uc774 \uc5bc\ub9c8\uc778\uc9c0 \uad6c\ud558\uace0, \uadf8\ub9cc\ud07c \uc904\uc778 \ub4a4\uc5d0 \ub0a8\ub294 \ub3c8\uc774 \uc5bc\ub9c8\uc778\uc9c0 \ub2e4\uc2dc \uacc4\uc0b0\ud574\ubcf4\uc138\uc694."}','null',3);
INSERT INTO content_stages VALUES('stage_learning_fraction_store_discount_4','content_learning_fraction_store_discount',4,'realtime_practice','realtime_teach_back','설명해보기','매점에서 물건 하나를 골랐다고 생각하고, ‘원래 가격 → 할인 금액 → 그래서 내가 낼 돈’을 순서대로 말로 설명해보세요.','{"imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime_audio", "assetBundle": {"imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "audioAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime_audio"}}','{"id": "rt_spec_learning_fraction_store_discount", "stageId": "stage_learning_fraction_store_discount_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_learning_fraction_store_discount_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ub9e4\uc810 \ud560\uc778 \uac00\uaca9 \ucc28\uadfc\ucc28\uadfc \uc124\uba85\ud558\uae30", "situationText": "\uce5c\uad6c\uac00 \ub9e4\uc810\uc5d0\uc11c \uc0cc\ub4dc\uc704\uce58\uc640 \uc74c\ub8cc\ub97c \ubcf4\ub2e4\uac00, \ud560\uc778 \uac00\uaca9\uc774 \uc5b4\ub5bb\uac8c \uacc4\uc0b0\ub418\ub294\uc9c0 \uad81\uae08\ud574\ud558\uace0 \uc788\uc5b4\uc694. \uce5c\uad6c\uc5d0\uac8c \ud55c \ubb3c\uac74\uc744 \uc608\ub85c \ub4e4\uc5b4, \uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\ub97c \ud560\uc778\ud574 \uc918\uc11c, \uadf8\ub798\uc11c \ub9c8\uc9c0\ub9c9\uc5d0 \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \uc21c\uc11c\ub300\ub85c \uc124\uba85\ud574 \uc8fc\uba74 \uc88b\uaca0\uc5b4\uc694.", "aiRole": "\ub9e4\uc810 \uc55e\uc5d0\uc11c \ud568\uaed8 \uc788\ub294 \uce5c\uad6c", "openingLine": "\ub098 \uc624\ub298 \ub9e4\uc810\uc5d0\uc11c \ubb3c\uac74\uc744 \uc0ac\ub824\uace0 \ud558\ub294\ub370, \ud560\uc778 \uac00\uaca9\uc774 \ud5f7\uac08\ub824. \uc608\ub97c \ud558\ub098 \uace8\ub77c\uc11c, \uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\uace0, \uc5bc\ub9c8\ub97c \uae4e\uc544\uc11c, \uadf8\ub798\uc11c \uc5bc\ub9c8\ub97c \ub0b4\uc57c \ud558\ub294\uc9c0 \uc21c\uc11c\ub300\ub85c \uc54c\ub824\uc904\ub798?", "studentGoal": "\ud55c \ubb3c\uac74\uc744 \uc815\ud574 \u2018\uc6d0\ub798 \uac00\uaca9 \u2192 \ubd84\uc218\ub85c \ub41c \ud560\uc778 \uae08\uc561 \u2192 \uadf8\ub798\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\u2019\uc744 \uc790\uc2e0\uc758 \ub9d0\ub85c \uac04\ub2e8\ud55c \ud55c\ub450 \ubb38\uc7a5\uc73c\ub85c \uc124\uba85\ud574 \ubcf4\uae30", "rubric": [{"id": "mention_original_price", "label": "\uc6d0\ub798 \uac00\uaca9\uc774 \uc5bc\ub9c8\uc600\ub294\uc9c0 \ud55c \ubc88\uc774\ub77c\ub3c4 \ub9d0\ud55c\ub2e4.", "required": false}, {"id": "mention_discount_fraction", "label": "\uc5bc\ub9c8\ub97c \ud560\uc778\ud558\ub294\uc9c0, \ubd84\uc218\ub098 \u2018\uc5bc\ub9c8\ub9cc\ud07c \uae4e\uc778\ub2e4\u2019\ub294 \ub9d0\uc744 \uc774\uc6a9\ud574 \uc124\uba85\ud558\ub824\uace0 \uc2dc\ub3c4\ud55c\ub2e4.", "required": false}, {"id": "mention_final_pay", "label": "\ub9c8\uc9c0\ub9c9\uc5d0 \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc744 \ub9d0\ub85c \uc815\ub9ac\ud574 \ubcf8\ub2e4.", "required": false}, {"id": "use_sequence_words", "label": "\u2018\uba3c\uc800, \uadf8\ub9ac\uace0, \uadf8\ub798\uc11c\u2019 \uac19\uc740 \ub9d0\ub85c \uc21c\uc11c\ub97c \ub098\ub204\uc5b4 \ub9d0\ud558\ub824\uace0 \ud55c\ub2e4.", "required": false}, {"id": "meaningful_attempt", "label": "\uc790\uc2e0\uc774 \uc774\ud574\ud55c \ub9cc\ud07c \ub05d\uae4c\uc9c0 \uc124\uba85\ud558\ub824\uace0 \ub178\ub825\ud55c\ub2e4.", "required": true}], "allowedFeedback": ["\uc9c0\uae08\uae4c\uc9c0 \uc124\uba85 \uc798 \ub4e4\uc5c8\uc5b4. \uba3c\uc800 \uc6d0\ub798 \uac00\uaca9\uc744 \uc5b4\ub5bb\uac8c \ub9d0\ud560 \uc218 \uc788\ub294\uc9c0 \ud55c \ubc88\ub9cc \ub354 \uc9e7\uac8c \ub9d0\ud574\ubcfc\uae4c?", "\uad1c\ucc2e\uc544, \uc870\uae08 \ud5f7\uac08\ub824\ub3c4 \ub3fc. \uc774\ubc88\uc5d0\ub294 \u2018\uc5bc\ub9c8\ub97c \uae4e\uc544\uc11c\u2019 \ubd80\ubd84\ub9cc \ud55c \ubb38\uc7a5\uc73c\ub85c \ub2e4\uc2dc \ub9d0\ud574\ubcfc\ub798?", "\uc88b\uc544, \uc774\uc81c \ub9c8\uc9c0\ub9c9\uc73c\ub85c \u2018\uadf8\ub798\uc11c \ub0b4\uac00 \ub0b4\uc57c \ud558\ub294 \ub3c8\uc740 \uc5bc\ub9c8\ub2e4\u2019\ub77c\uace0 \ud55c \ubc88\uc5d0 \uc774\uc5b4\uc11c \ub9d0\ud574\ubcf4\uc790.", "\uc124\uba85\uc774 \uc870\uae08 \uc9e7\uc544\ub3c4 \uad1c\ucc2e\uc544. \u2018\uba3c\uc800 ~, \uadf8\ub9ac\uace0 ~, \uadf8\ub798\uc11c ~\u2019\ucc98\ub7fc \uc21c\uc11c\ub97c \ub098\ub204\uc5b4\uc11c \ub9d0\ud574\ubcf4\uba74 \ub354 \uc774\ud574\ud558\uae30 \uc26c\uc6cc."], "forbidden": ["\ud559\uc0dd\uc5d0\uac8c \uc9c4\ub2e8\uc774\ub098 \ub2a5\ub825\uacfc \uad00\ub828\ub41c \ub9d0\uc744 \ud558\uc9c0 \uc54a\uae30", "\ud559\uc0dd \ub2f5\uc774 \uc9e7\ub2e4\uace0 \uc2e4\ud328\ub77c\uace0 \ub9d0\ud558\uc9c0 \uc54a\uae30", "\uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uac70\ub098 \ub9d0\ud558\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 150, "postPracticeReflection": ["\uc6d0\ub798 \uac00\uaca9\ubd80\ud130 \ucc28\ub840\ub300\ub85c \ub9d0\ud558\ub2c8 \uc880 \ub354 \uc774\ud574\uac00 \uc798 \ub410\uc5b4\uc694.", "\ud560\uc778 \uae08\uc561\uc744 \ubd84\uc218\ub85c \ub9d0\ud558\ub294 \uac8c \uc870\uae08 \ud5f7\uac08\ub838\uc5b4\uc694.", "\ub0bc \ub3c8\uc744 \ub2e4\uc2dc \uacc4\uc0b0\ud574 \ubcf4\uba74\uc11c \ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud574\ubcf4\uace0 \uc2f6\uc5b4\uc694."]}',4);
