INSERT INTO content_assets VALUES('asset_content_generated_001_hero','content_generated_001',NULL,'hero','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration of a calm, bright public library interior. Show wide aisles, neat bookshelves, warm natural light, and a librarian desk in the distance. A blue-covered animal picture book is visible naturally on one shelf, with only a simple animal icon on the cover and no readable title. Include one elementary-age Korean student entering or looking around comfortably, not stressed. Composition should feel like a welcoming overview before the mission starts, with clear subject separation and generous empty space for frontend UI overlay. Warm but not childish, polished digital illustration, soft realistic proportions, varied library colors, no decorative gradient blobs, no stock-photo feeling.", "visualRole": "hero", "scene": "\uc870\uc6a9\ud55c \ub3c4\uc11c\uad00 \uc804\uccb4 \uc0c1\ud669 \uc608\uace0", "style": "\ub530\ub73b\ud55c \ud55c\uad6d \uad50\uc721\uc6a9 \ub514\uc9c0\ud138 \uc77c\ub7ec\uc2a4\ud2b8, \ubd80\ub4dc\ub7ec\uc6b4 \uc0c9\uac10, \uba85\ud655\ud55c \uad6c\ub3c4", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ud654\uba74\uc6a9 \ub2e8\ucd94", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\ubcf5\uc7a1\ud55c \uae30\ud638", "\ud45c\uc9c0 \uc81c\ubaa9"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no readable book titles", "no UI panels or buttons", "no speech bubbles", "no worksheet-like layout"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "blue animal book is visible but not presented as a UI answer"]}',NULL,'/generated/assets/content_generated_001/asset_content_generated_001_hero.png','/generated/assets/content_generated_001/asset_content_generated_001_hero.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_hero_audio','content_generated_001',NULL,'hero','audio','elevenlabs','eleven_multilingual_v2','null','오늘은 도서관에서 파란 동물책을 찾고, 필요하면 사서 선생님께 도움을 요청해 볼 거예요.','/generated/assets/content_generated_001/asset_content_generated_001_hero_audio.mp3','/generated/assets/content_generated_001/asset_content_generated_001_hero_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_1','content_generated_001','stage_content_generated_001_1','stage_1','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration inside a Korean public library. An elementary-age Korean student stands calmly in front of a low bookshelf, looking at the books and preparing to find a book. On the nearby shelf, show several books and one clearly blue-covered animal picture book with a simple animal icon only, no readable words. The mood is quiet, safe, and supportive. Use warm daylight, clean shapes, clear spatial layout, and enough empty space on one side for UI overlay. The scene should introduce the situation of remembering the clue: a blue animal book, without displaying any problem text.", "visualRole": "stage_1", "scene": "\ub3c4\uc11c\uad00 \ucc45\uc7a5 \uc55e\uc5d0\uc11c \ucc3e\uc744 \ucc45\uc744 \ub5a0\uc62c\ub9ac\ub294 \uc2dc\uc791 \uc7a5\uba74", "style": "\uce5c\uadfc\ud55c \uc0dd\ud65c \uc5f0\uc2b5\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ucc28\ubd84\ud558\uace0 \uba85\ud655\ud55c \uad6c\uc131", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ud654\uba74\uc6a9 \ud45c\uc2dc", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\ucc45 \uc81c\ubaa9 \uae00\uc790", "\uae34 \ud14d\uc2a4\ud2b8"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no readable book titles", "no UI panels or buttons", "no speech bubbles", "no correct answer marks"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "student is calmly observing the bookshelf"]}',NULL,'/generated/assets/content_generated_001/asset_content_generated_001_stage_1.png','/generated/assets/content_generated_001/asset_content_generated_001_stage_1.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_1_audio','content_generated_001','stage_content_generated_001_1','stage_1','audio','elevenlabs','eleven_multilingual_v2','null','도서관에 왔어요. 오늘 찾을 책은 파란 표지의 동물책이에요. 천천히 살펴보면 돼요.','/generated/assets/content_generated_001/asset_content_generated_001_stage_1_audio.mp3','/generated/assets/content_generated_001/asset_content_generated_001_stage_1_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_2','content_generated_001','stage_content_generated_001_2','stage_2','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech close observation illustration of a library bookshelf. Show a tidy row of books with one blue-covered book featuring a simple cute animal icon on the cover, no text. Nearby, include one or two other books in different colors such as red or beige, but keep the composition natural and not like answer choices. The blue cover should be easy to notice as a real-world visual clue. Use low visual clutter, warm library lighting, clean educational illustration style, and leave some calm empty space for frontend overlay. Do not create cards, labels, buttons, comparison panels, or any worksheet-like arrangement.", "visualRole": "stage_2", "scene": "\ud30c\ub780 \ud45c\uc9c0 \ub2e8\uc11c\ub97c \ud655\uc778\ud560 \uc218 \uc788\ub294 \ucc45\uc7a5 \uad00\ucc30 \uc7a5\uba74", "style": "\uae68\ub057\ud55c \ud55c\uad6d \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ub2e8\uc21c\ud55c \uc2dc\uac01 \ub2e8\uc11c, \ub0ae\uc740 \uc2dc\uac01 \ud63c\uc7a1\ub3c4", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\uc120\ud0dd\uc6a9 \ub2e8\ucd94 \ubaa8\uc591", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\uc22b\uc790", "\uae34 \uae00\uc790"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no readable book titles", "no selection buttons", "no check marks or X marks", "no numbered labels"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "blue cover clue is visually clear without becoming an answer panel"]}',NULL,'/generated/assets/content_generated_001/asset_content_generated_001_stage_2.png','/generated/assets/content_generated_001/asset_content_generated_001_stage_2.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_2_audio','content_generated_001','stage_content_generated_001_2','stage_2','audio','elevenlabs','eleven_multilingual_v2','null','이번에는 책의 단서 하나에 집중해요. 파란 표지를 찾아보면 좋아요.','/generated/assets/content_generated_001/asset_content_generated_001_stage_2_audio.mp3','/generated/assets/content_generated_001/asset_content_generated_001_stage_2_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_3','content_generated_001','stage_content_generated_001_3','stage_3','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration of a calm library aisle showing the next-action situation. An elementary-age Korean student stands near a bookshelf, looking around after not easily finding the book. In the mid-background, a friendly librarian teacher is visible at a simple librarian desk, ready to help. The shelf area and the librarian desk are connected by a clear open walkway, suggesting the student can look at the shelf and then ask for help. Keep the mood supportive and non-stressful. Warm lighting, polished digital illustration, clear subject separation, enough empty space for UI overlay. No sequence cards, no arrows, no step numbers, no dialogue graphics.", "visualRole": "stage_3", "scene": "\ucc45\uc7a5 \uc55e\uc5d0\uc11c \ub2e4\uc74c \ud589\ub3d9\uc744 \ub5a0\uc62c\ub9ac\ub294 \ub3c4\uc11c\uad00 \ud1b5\ub85c", "style": "\uc9c0\uc9c0\uc801\uc778 \uc0dd\ud65c \uc7a5\uba74 \uc77c\ub7ec\uc2a4\ud2b8, \ubd80\ub4dc\ub7ec\uc6b4 \uc870\uba85, \ubd84\uba85\ud55c \uacf5\uac04 \uad00\uacc4", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ud654\uba74\uc6a9 \uc21c\uc11c \ud45c\uc2dc", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\ub370\uc2a4\ud06c \uc548\ub0b4\ubb38 \uae00\uc790", "\uae34 \ud14d\uc2a4\ud2b8"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no sequence labels", "no arrows or numbered steps", "no speech bubbles", "no desk sign text"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "space clearly shows bookshelf and librarian as possible next support"]}',NULL,'/generated/assets/content_generated_001/asset_content_generated_001_stage_3.png','/generated/assets/content_generated_001/asset_content_generated_001_stage_3.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_3_audio','content_generated_001','stage_content_generated_001_3','stage_3','audio','elevenlabs','eleven_multilingual_v2','null','책을 바로 못 찾아도 괜찮아요. 단서를 기억하고 책장을 본 뒤, 사서 선생님께 물어볼 수 있어요.','/generated/assets/content_generated_001/asset_content_generated_001_stage_3_audio.mp3','/generated/assets/content_generated_001/asset_content_generated_001_stage_3_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_4_realtime','content_generated_001','stage_content_generated_001_4','stage_4_realtime','image','openai','gpt-image-2','{"prompt": "Premium Korean edtech illustration for a speaking practice scene in a public library. A student stands comfortably at a librarian desk, facing a kind librarian teacher who is ready to listen and help. The distance between them feels respectful and not intimidating. In the background, show bookshelves with a few blue-covered books that have simple animal icons only, no readable titles. The scene should visually support the idea of asking the librarian for the blue animal book. Warm, quiet library atmosphere, polished digital illustration, friendly but not childish, clear subject separation, and generous empty space for frontend UI overlay. No speech bubbles or dialogue symbols.", "visualRole": "stage_4_realtime", "scene": "\uc0ac\uc11c \uc120\uc0dd\ub2d8\uc5d0\uac8c \ucc45 \ub2e8\uc11c\ub97c \ub9d0\ud558\uba70 \ub3c4\uc6c0\uc744 \uc694\uccad\ud560 \uc900\ube44 \uc7a5\uba74", "style": "\ub530\ub73b\ud55c \ub9d0\ud558\uae30 \uc5f0\uc2b5\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ud55c\uad6d \ub3c4\uc11c\uad00 \ubc30\uacbd, \uc548\uc815\uc801\uc778 \ubd84\uc704\uae30", "avoid": ["\uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790", "\ub300\ud654 \ub0b4\uc6a9\uc744 \ub098\ud0c0\ub0b4\ub294 \ub3c4\ud615", "\ud654\uba74\uc6a9 \ub2e8\ucd94", "\uc815\ub2f5 \ud45c\uc2dc", "\uc124\uba85 \ubb38\uad6c", "\uae34 \ud14d\uc2a4\ud2b8"], "textRenderingPolicy": "scene_only_no_problem_text", "promptVersion": "image_brief_v1", "negativePromptRules": ["no problem statements", "no answer choices", "no hints", "no long Korean text", "no watermark", "no speech bubbles", "no chat icons", "no UI panels or buttons", "no readable desk signs or book titles"], "ocrRequired": false, "qaChecklist": ["scene matches stage purpose", "no UI text embedded", "no confusing extra answer objects", "student-safe tone", "student and librarian interaction feels supportive for realtime practice"]}',NULL,'/generated/assets/content_generated_001/asset_content_generated_001_stage_4_realtime.png','/generated/assets/content_generated_001/asset_content_generated_001_stage_4_realtime.png','passed','approved');
INSERT INTO content_assets VALUES('asset_content_generated_001_stage_4_realtime_audio','content_generated_001','stage_content_generated_001_4','stage_4_realtime','audio','elevenlabs','eleven_multilingual_v2','null','이제 사서 선생님께 말해볼 거예요. 파란 동물책 어디에 있어요, 처럼 짧게 물어봐도 괜찮아요.','/generated/assets/content_generated_001/asset_content_generated_001_stage_4_realtime_audio.mp3','/generated/assets/content_generated_001/asset_content_generated_001_stage_4_realtime_audio.mp3','passed','approved');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_hero','content_learning_fraction_store_discount',NULL,'hero','image','openai','gpt-image-2','{"prompt": "\ud55c\uad6d \uc911\ud559\uad50 \uc548\uc5d0 \uc788\ub294 \ubc1d\uc740 \ubd84\uc704\uae30\uc758 \ud559\uad50 \ub9e4\uc810 \ub0b4\ubd80 \uc804\uacbd. \ub2e4\uc591\ud55c \uacfc\uc790\uc640 \uc74c\ub8cc\uac00 \uc9c4\uc5f4\ub41c \uc9c4\uc5f4\ub300\uc640 \ub0c9\uc7a5\uace0\uac00 \ubcf4\uc774\uace0, \uc9c4\uc5f4\ub300 \uc55e\uc5d0\ub294 \uc911\ud559\uc0dd \ub0a8\ud559\uc0dd \ud55c \uba85\uc774 \uac04\uc2dd\uc744 \uace0\ub974\uba70 \uac00\uaca9\ud45c\ub97c \uc720\uc2ec\ud788 \ubc14\ub77c\ubcf4\uace0 \uc788\ub2e4. \uba87\uba87 \uac00\uaca9\ud45c\uc5d0\ub294 \ub178\ub780\uc0c9\uc774\ub098 \ube68\uac04\uc0c9\uc758 \uc791\uc740 \u2018\ud560\uc778\u2019 \uc2a4\ud2f0\ucee4\ub098 \uc138\uc77c \uc544\uc774\ucf58\uc774 \ubd99\uc5b4 \uc788\uc9c0\ub9cc, \uad6c\uccb4\uc801\uc778 \uc22b\uc790\ub098 \ubd84\uc218, \ubb38\uc81c \ubb38\uc7a5\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uad50\ubcf5\uc774\ub098 \ud6c4\ub4dc\ud2f0\ub97c \uc785\uc740 \ud559\uc0dd\uc774 \uace0\ubbfc\ud558\ub294 \ud45c\uc815\uc73c\ub85c \uac00\uaca9\ud45c\ub97c \ubc14\ub77c\ubcf4\ub294 \uc7a5\uba74. \uc804\ubc18\uc801\uc778 \uc2a4\ud0c0\uc77c\uc740 \uc120\uba85\ud55c \uc0c9\uac10\uc758 \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8, \ub9cc\ud654\uac00 \uc544\ub2c8\ub77c \uc0ac\uc2e4\uc801\uc778 \ub290\ub08c. \uadf8\ub9bc \uc548\uc5d0\ub294 \ubb38\uc81c \ubb38\uc7a5, \uc120\ud0dd\uc9c0, \uc815\ub2f5, \ud78c\ud2b8, \uc218\uc2dd \uac19\uc740 \uae34 \uae00\uc790\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "hero", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_hero.png','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_hero.png','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_hero_audio','content_learning_fraction_store_discount',NULL,'hero','audio','elevenlabs','eleven_multilingual_v2','null','오늘은 학교 매점에서 물건을 살 때, 분수로 표시된 할인 금액을 보고 원래 가격에서 얼마가 줄어드는지, 그래서 내가 얼마를 내야 하는지 차근차근 살펴볼 거예요.','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_hero_audio.mp3','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_hero_audio.mp3','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_1','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_1','stage_1','image','openai','gpt-image-2','{"prompt": "\ud559\uad50 \ub9e4\uc810 \uc548\ucabd \ud55c \ucf54\ub108\ub97c \ud074\ub85c\uc988\uc5c5\ud55c \uc7a5\uba74. \uc9c4\uc5f4\ub300\uc5d0 \uacfc\uc790 1~2\uac1c\uc640 \uc74c\ub8cc\uac00 \ub193\uc5ec \uc788\uace0, \uac01 \ubb3c\uac74 \uc544\ub798\uc5d0\ub294 \ud770\uc0c9 \uac00\uaca9\ud45c\uac00 \ubd99\uc5b4 \uc788\ub2e4. \uac00\uaca9\ud45c\uc5d0\ub294 \uad75\uc740 \uae00\uc528\uc758 \uae30\ubcf8 \uac00\uaca9 \uc22b\uc790 \ubaa8\uc591\uacfc \uadf8 \uc606\uc5d0 \uc791\uc740 \ube68\uac04\uc0c9 \ud560\uc778 \ubc30\uc9c0\ub098 \u2018\ud560\uc778\u2019 \uc544\uc774\ucf58\uc774 \ubd99\uc5b4 \uc788\uc9c0\ub9cc, \uae00\uc790\ub294 \ud750\ub9bf\ud574\uc11c \uc77d\ud788\uc9c0 \uc54a\uace0 \uad6c\uccb4\uc801\uc778 \uc218\uc2dd\uc774\ub098 \ubb38\uc81c \ubb38\uc7a5\uc740 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \uc55e\ucabd\uc5d0\ub294 \uc911\ud559\uc0dd \uc815\ub3c4\uc758 \ud559\uc0dd\uc774 \ud55c \uc190\uac00\ub77d\uc73c\ub85c \uac00\uaca9\ud45c\ub97c \uac00\ub9ac\ud0a4\uba70 \uc0b4\ud3b4\ubcf4\uace0 \uc788\ub294 \ubaa8\uc2b5. \ucc28\ubd84\ud55c \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c, \uc7a5\uba74 \uc124\uba85\ub9cc \uc788\uace0 \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub098 \uc815\ub2f5\uc744 \uc554\uc2dc\ud558\ub294 \uc22b\uc790 \uc870\ud569\uc740 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_1", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_1.png','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_1.png','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_1_audio','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_1','stage_1','audio','elevenlabs','eleven_multilingual_v2','null','매점 진열대를 보면, 물건 아래에 원래 가격이 적혀 있고 옆에 할인 표시가 함께 보이죠. 이제 이 장면을 떠올리면서, ‘원래 가격 → 할인 금액 → 낼 돈’ 순서를 머릿속에 그려볼게요.','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_1_audio.mp3','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_1_audio.mp3','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_2','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_2','stage_2','image','openai','gpt-image-2','{"prompt": "\ud559\uad50 \ub9e4\uc810 \uce74\uc6b4\ud130 \uadfc\ucc98\ub97c \ubc30\uacbd\uc73c\ub85c, \uac00\uc6b4\ub370\uc5d0\ub294 \ud3ec\uc7a5\ub41c \uacfc\uc790 \ud55c \uac1c\uac00 \ud06c\uac8c \ubcf4\uc774\uace0, \uadf8 \uc8fc\ubcc0\uc5d0\ub294 \uc138 \uc7a5\uc758 \ube48 \uce74\ub4dc\ub098 \ub9d0\ud48d\uc120 \uac19\uc740 \uc601\uc5ed\uc774 \ub465\uae00\uac8c \ubc30\uce58\ub418\uc5b4 \uc788\ub2e4. \ud55c \uce74\ub4dc\ub294 \uc804\uccb4 \uac00\uaca9\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub3d9\uc804 \ub354\ubbf8 \uc544\uc774\ucf58, \ud55c \uce74\ub4dc\ub294 \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub294 \ud654\uc0b4\ud45c\uc640 \ud560\uc778 \uc544\uc774\ucf58, \ub2e4\ub978 \ud55c \uce74\ub4dc\ub294 \uc9c0\uac11\uc5d0\uc11c \ub3c8\uc774 \ub098\uac00\ub294 \uc791\uc740 \uc544\uc774\ucf58\uc73c\ub85c \ud45c\ud604\ud55c\ub2e4. \uce74\ub4dc \uc548\uc5d0\ub294 \uc22b\uc790\ub098 \ubd84\uc218 \uae30\ud638, \ubb38\uc81c \ubb38\uc7a5\uc740 \uc801\ud600 \uc788\uc9c0 \uc54a\uace0, \ub2e8\uc9c0 \uc21c\uc11c\ub97c \ub9de\ucd94\ub294 \ub2e8\uacc4 \uce74\ub4dc \ub290\ub08c\ub9cc \uc8fc\ub3c4\ub85d \ud55c\ub2e4. \uc804\ubc18\uc801\uc73c\ub85c \uac04\ub2e8\ud558\uace0 \uc120\uba85\ud55c \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8\uc774\uba70, \uc815\ub2f5 \uc21c\uc11c\ub97c \uc554\uc2dc\ud558\ub294 1,2,3 \ubc88\ud638\ub098 \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_2", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_2.png','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_2.png','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_2_audio','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_2','stage_2','audio','elevenlabs','eleven_multilingual_v2','null','이제 과자 한 개를 정해서, 원래 가격을 먼저 보고, 분수로 된 할인 금액을 보고, 마지막에 내가 낼 돈을 계산하는 순서를 카드로 정리해볼게요. 알맞은 순서를 골라보세요.','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_2_audio.mp3','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_2_audio.mp3','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_3','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_3','stage_3','image','openai','gpt-image-2','{"prompt": "\ud559\uad50 \ub9e4\uc810\uc5d0\uc11c \uc0cc\ub4dc\uc704\uce58 \ud558\ub098\uc758 \uac00\uaca9\ud45c\ub97c \uac00\uae5d\uac8c \ube44\ucd98 \uc7a5\uba74. \uac00\uaca9\ud45c\uc5d0\ub294 \ud55c\uae00\ub85c \ub41c \uc0cc\ub4dc\uc704\uce58 \uc774\ub984\uacfc \uae30\ubcf8 \uac00\uaca9 \uc22b\uc790 \ubaa8\uc591\uc774 \ud750\ub9bf\ud558\uac8c \ud45c\uc2dc\ub418\uc5b4 \uc788\uace0, \uc606\uc5d0\ub294 \ubd84\uc218 \ubaa8\uc591 \uc544\uc774\ucf58\uc774 \ub4e4\uc5b4\uac04 \ud560\uc778 \ubc30\uc9c0\uac00 \ubd99\uc5b4 \uc788\ub2e4. \ubd84\uc218 \uc544\uc774\ucf58\uc740 \uc6d0 \uc548\uc5d0 \ub098\ub220\uc9c4 \uc870\uac01\ucc98\ub7fc \uc0c1\uc9d5\uc801\uc73c\ub85c \ubcf4\uc774\uc9c0\ub9cc, \uc815\ud655\ud55c \uc218\ub098 \uae30\ud638\ub294 \uc77d\ud788\uc9c0 \uc54a\uac8c \ucc98\ub9ac\ud55c\ub2e4. \uc544\ub798\ucabd\uc5d0\ub294 \uc190\uc5d0 \uc791\uc740 \uacc4\uc0b0\uae30\ub97c \ub4e4\uace0 \ud654\uba74\uc744 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \uc911\ud559\uc0dd \uc190\uc774 \ubcf4\uc774\uace0, \ud559\uc0dd\uc774 \ud560\uc778 \uac00\uaca9\uc744 \uace0\ubbfc\ud558\ub294 \ub4ef\ud55c \ubd84\uc704\uae30\ub2e4. \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub098 \uc120\ud0dd\uc9c0, \uc815\ub2f5, \uad6c\uccb4 \uc218\uc2dd\uc740 \uadf8\ub9bc\uc5d0 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_3", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_3.png','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_3.png','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_3_audio','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_3','stage_3','audio','elevenlabs','eleven_multilingual_v2','null','방금 연습한 순서를 떠올려 볼게요. 먼저 원래 가격 3,000원을 보고, 그다음 1/3만큼 얼마나 줄어드는지 생각한 뒤, 보기에서 내가 내야 하는 돈을 골라보면 돼요.','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_3_audio.mp3','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_3_audio.mp3','passed','pending');
INSERT INTO content_assets VALUES('asset_content_learning_fraction_store_discount_stage_4_realtime','content_learning_fraction_store_discount','stage_learning_fraction_store_discount_4','stage_4_realtime','image','openai','gpt-image-2','{"prompt": "\ud559\uad50 \ub9e4\uc810 \uc55e \ud14c\uc774\ube14\uc5d0 \uc911\ud559\uc0dd \ub450 \uba85\uc774 \ub9c8\uc8fc \uc549\uc544 \uc788\ub2e4. \ud55c \ud559\uc0dd\uc740 \uac04\uc2dd\uc744 \uc190\uc5d0 \ub4e4\uace0 \uc788\uace0, \ub2e4\ub978 \ud559\uc0dd\uc774\ub098 \uc120\uc0dd\ub2d8\uc740 \uadf8 \uc124\uba85\uc744 \ub4e3\ub294 \ub4ef \uace0\uac1c\ub97c \ub044\ub355\uc774\uba70 \uc8fc\uc758 \uae4a\uac8c \ub4e3\uace0 \uc788\ub2e4. \ucc45\uc0c1 \uc704\uc5d0\ub294 \uac04\ub2e8\ud55c \ub9e4\uc810 \uc601\uc218\uc99d\uc774\ub098 \uc791\uc740 \uac00\uaca9\ud45c \ud55c \uc7a5\uc774 \ub193\uc5ec \uc788\uc9c0\ub9cc, \uadf8 \uc704\uc758 \uc22b\uc790\ub098 \ubb38\uc7a5\uc740 \uc54c\uc544\ubcfc \uc218 \uc5c6\uc744 \uc815\ub3c4\ub85c \ud750\ub9bf\ud558\ub2e4. \ub450 \uc0ac\ub78c\uc740 \ud3b8\uc548\ud55c \ud45c\uc815\uc73c\ub85c \ub300\ud654\ub97c \ub098\ub204\ub294 \uc7a5\uba74\uc774\ub2e4. \uad50\uc721\uc6a9 \uc77c\ub7ec\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c\ub85c \ub530\ub73b\ud558\uace0 \ucc28\ubd84\ud55c \ubd84\uc704\uae30\uc774\uba70, \ub9d0\ud48d\uc120 \uc548\uc5d0 \uad6c\uccb4 \uc22b\uc790\ub098 \uc815\ub2f5 \ubb38\uc7a5, \ubb38\uc81c \ud14d\uc2a4\ud2b8\ub294 \ub123\uc9c0 \uc54a\ub294\ub2e4.", "visualRole": "stage_4_realtime", "textRenderingPolicy": "scene_only_no_problem_text"}',NULL,'/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_4_realtime.png','/generated/assets/content_learning_fraction_store_discount/asset_content_learning_fraction_store_discount_stage_4_realtime.png','passed','pending');
