INSERT INTO realtime_practice_sessions VALUES('rt_session_18564742-eab0-48ec-a556-294e0b74fd53','attempt_00409e90-adf3-48d1-a2a1-2383e62c4524','content_bus_to_center_001','stage_bus_to_center_001_4','student_learning_clock','openai','gpt-realtime','completed','{"id": "rt_spec_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0 \uc5f0\uc2b5\ud558\uae30", "situationText": "\uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uac00\ub294 \uae38\uc5d0 \uc870\uae08 \ud5f7\uac08\ub824\uc11c, \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uaed8 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ubb3c\uc5b4\ubcf4\ub824\uace0 \ud574\uc694.", "aiRole": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uc9c0\uc6b0 \uacc1\uc5d0 \uc788\ub294 \uce5c\uc808\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce5c\uad6c", "openingLine": "\uc9c0\uc6b0\uc57c, \uae38\uc774 \uc870\uae08 \ud5f7\uac08\ub9ac\uba74 \uc5b4\ub5bb\uac8c \ub9d0\ud574 \ubcfc\uae4c?", "studentGoal": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ud5f7\uac08\ub9b4 \ub54c \"\ub3c4\uc640\uc8fc\uc138\uc694.\", \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\" \uac19\uc740 \uc9e7\uc740 \ubb38\uc7a5\uc73c\ub85c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud574 \ubcf4\uae30", "rubric": [{"id": "say_help", "label": "\ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\ub3c4\uc640\uc8fc\uc138\uc694.\")", "required": true}, {"id": "ask_where_get_off", "label": "\ub0b4\ub9ac\ub294 \uacf3\uc744 \ubb3c\uc5b4\ubcf4\ub294 \ub9d0\uc744 \ud55c\ub2e4. (\uc608: \"\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694?\")", "required": false}], "allowedFeedback": ["\uc88b\uc544\uc694. \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0\uc744 \uc798 \ud588\uc5b4\uc694.", "\uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0\ub3c4 \uc9e7\uac8c \ubb3c\uc5b4\ubcfc \uc218\ub3c4 \uc788\uc5b4\uc694.", "\ucc9c\ucc9c\ud788 \ub2e4\uc2dc \ub9d0\ud574\ub3c4 \uad1c\ucc2e\uc544\uc694. \ud55c \ubb38\uc7a5\ub9cc \ud574\ub3c4 \uc88b\uc544\uc694."], "forbidden": ["\uc9c4\ub2e8\uba85\uc774\ub098 \uac80\uc0ac \uacb0\uacfc\ub97c \ub9d0\ud558\uac8c \ud558\uc9c0 \uc54a\uae30", "\uc9d1 \uc8fc\uc18c, \uc804\ud654\ubc88\ud638 \uac19\uc740 \uac1c\uc778\uc815\ubcf4\ub97c \ubb3b\uc9c0 \uc54a\uae30"], "maxTurns": 6, "maxDurationSec": 120, "postPracticeReflection": ["\ub9d0\ud574 \ubcf4\ub2c8 \uad1c\ucc2e\uc558\uc5b4\uc694.", "\uc870\uae08 \uc5b4\ub835\uc9c0\ub9cc \ud574 \ubcfc \ub9cc \ud588\uc5b4\uc694.", "\ub098\uc911\uc5d0 \ud55c \ubc88 \ub354 \uc5f0\uc2b5\ud574 \ubcf4\uace0 \uc2f6\uc5b4\uc694."]}',NULL,'2026-05-04T01:36:09.135054+00:00',4,82,'{"practiced": true, "supportNeeded": null}','시스템: 마이크 입력을 듣고 있어요. / 시스템: 말을 들었어요. 답변을 기다리는 중이에요. / 학생: 어디에서 내려요? / 상대: 좋아, 지금 아주 잘했어. 그럼 다음에는 이렇게도 말해볼까? “이 정거장이 맞나요?” 한번 해볼래? / 시스템: 마이크 입력을 듣고 있어요. / 시스템: 말을 들었어요. 답변을 기다리는 중이에요. / 학생: 이 정거장이 맞나요? / 상대: 잘했어! 이제 정말 자연스럽게 들려. 지우야, 스스로 물어볼 수 있다는 게 참 멋져. 다음 번에도 이렇게 차근차근 물어보면 분명 잘할 수 있어. 계속 용기 내서 해보자!');
