INSERT INTO review_summaries VALUES('review_8e4e4863-a211-4f68-9de6-5a883254711d','attempt_00409e90-adf3-48d1-a2a1-2383e62c4524','student_learning_clock',1,1,'완료율 100% / 정답률 100% / 회고: 재밌었다! / 실시간 연습: 시스템: 마이크 입력을 듣고 있어요. / 시스템: 말을 들었어요. 답변을 기다리는 중이에요. / 학생: 어디에서 내려요? / 상대: 좋아, 지금 아주 잘했어. 그럼 다음에는 이렇게도 말해볼까? “이 정거장이 맞나요?” 한번 해볼래? / 시스템: 마이크 입력을 듣고 있어요. / 시스템: 말을 들었어요. 답변을 기다리는 중이에요. / 학생: 이 정거장이 맞나요? / 상대: 잘했어! 이제 정말 자연스럽게 들려. 지우야, 스스로 물어볼 수 있다는 게 참 멋져. 다음 번에도 이렇게 차근차근 물어보면 분명 잘할 수 있어. 계속 용기 내서 해보자!','{"answerCount": 2, "correctCount": 2, "wrongCount": 0, "reflection": {"reflectionChoice": "\uc7ac\ubc0c\uc5c8\ub2e4!", "shortText": "\uc7ac\ubc0c\uc5c8\ub2e4!"}}','{"id": "rt_session_18564742-eab0-48ec-a556-294e0b74fd53", "attemptId": "attempt_00409e90-adf3-48d1-a2a1-2383e62c4524", "missionContentId": "content_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "studentId": "student_learning_clock", "provider": "openai", "model": "gpt-realtime", "status": "completed", "specSnapshotJson": {"id": "rt_spec_bus_to_center_001", "stageId": "stage_bus_to_center_001_4", "templateType": "realtime_teach_back", "imageAssetId": "asset_content_bus_to_center_001_stage_4_realtime", "mode": "voice_or_text", "practiceTitle": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \ub3c4\uc6c0\uc744 \ubd80\ud0c1\ud558\ub294 \ub9d0 \uc5f0\uc2b5\ud558\uae30", "situationText": "\uc9c0\uc6b0\uac00 \ubc84\uc2a4\ub97c \ud0c0\uace0 \uac00\ub294 \uae38\uc5d0 \uc870\uae08 \ud5f7\uac08\ub824\uc11c, \ub9c8\uc2a4\ucf54\ud2b8\ub098 \uae30\uc0ac\ub2d8\uaed8 \uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc57c \ud558\ub294\uc9c0 \uc870\uc2ec\uc2a4\ub7fd\uac8c \ubb3c\uc5b4\ubcf4\ub824\uace0 \ud574\uc694.", "aiRole": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \uc9c0\uc6b0 \uacc1\uc5d0 \uc788\ub294 \uce5c\uc808\ud55c \ub9c8\uc2a4\ucf54\ud2b8 \uce5c\uad6c", "openingLine": "\uc9c0\uc6b0\uc57c, \uae38\uc774 \uc870\uae08 \ud5f7\uac08\ub9ac\uba74 \uc5b4\ub5bb\uac8c \ub9d0\ud574 \ubcfc\uae4c?", "studentGoal": "\ubc84\uc2a4 \uc548\uc5d0\uc11c \u