\uc5b4\ub514\uc5d0\uc11c \ub0b4\ub824\uc694? / \uc0c1\ub300: \uc88b\uc544, \uc9c0\uae08 \uc544\uc8fc \uc798\ud588\uc5b4. \uadf8\ub7fc \ub2e4\uc74c\uc5d0\ub294 \uc774\ub807\uac8c\ub3c4 \ub9d0\ud574\ubcfc\uae4c? \u201c\uc774 \uc815\uac70\uc7a5\uc774 \ub9de\ub098\uc694?\u201d \ud55c\ubc88 \ud574\ubcfc\ub798? / \uc2dc\uc2a4\ud15c: \ub9c8\uc774\ud06c \uc785\ub825\uc744 \ub4e3\uace0 \uc788\uc5b4\uc694. / \uc2dc\uc2a4\ud15c: \ub9d0\uc744 \ub4e4\uc5c8\uc5b4\uc694. \ub2f5\ubcc0\uc744 \uae30\ub2e4\ub9ac\ub294 \uc911\uc774\uc5d0\uc694. / \ud559\uc0dd: \uc774 \uc815\uac70\uc7a5\uc774 \ub9de\ub098\uc694? / \uc0c1\ub300: \uc798\ud588\uc5b4! \uc774\uc81c \uc815\ub9d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\ub824. \uc9c0\uc6b0\uc57c, \uc2a4\uc2a4\ub85c \ubb3c\uc5b4\ubcfc \uc218 \uc788\ub2e4\ub294 \uac8c \ucc38 \uba4b\uc838. \ub2e4\uc74c \ubc88\uc5d0\ub3c4 \uc774\ub807\uac8c \ucc28\uadfc\ucc28\uadfc \ubb3c\uc5b4\ubcf4\uba74 \ubd84\uba85 \uc798\ud560 \uc218 \uc788\uc5b4. \uacc4\uc18d \uc6a9\uae30 \ub0b4\uc11c \ud574\ubcf4\uc790!"}');
INSERT INTO review_summaries VALUES('review_bus_20260502','attempt_bus_20260502','student_life_bus',1,1,'4단계를 모두 완료했습니다. 이동 경로 그림과 2지선다 단서에는 잘 반응했고, 도움 요청 역할극은 확인 문장 연습이 더 필요합니다.','{"answerCount": 2, "correctCount": 2, "wrongCount": 0, "patterns": ["\ub2e4\uc74c \ud589\ub3d9\uc744 \ud655\uc778\ud558\ub294 \ubb38\uc7a5\uc740 \uc608\uc2dc\ub97c \ub4e4\uc740 \ub4a4 \ub530\ub77c \ub9d0\ud568"]}','{"sessionId": "rt_session_bus_20260502", "rubricPassed": ["state_destination", "ask_help"], "rubricNeedsPractice": ["confirm_next_action"], "nextSupport": "\uc9e7\uc740 \ud655\uc778 \ubb38\uc7a5 \ud55c \uac00\uc9c0\ub97c \uba3c\uc800 \uc5f0\uc2b5\ud569\ub2c8\ub2e4. \uc608: ''\uc774\uc81c \uc5b4\ub5a4 \ubc84\uc2a4\ub97c \ud0c0\uba74 \ub3fc\uc694?''"}');
